#[derive(Debug, Deserialize)]
struct StartEnvelope {
    #[serde(rename = "type")]
    event_type: String,
    request: WorkerRequest,
}

#[derive(Debug, Deserialize)]
struct WorkerRequest {
    task_instruction: String,
    task_context: Value,
    #[serde(default)]
    initial_messages: Vec<Value>,
    #[serde(default)]
    initial_trajectory: Vec<Value>,
    tool_schemas: Vec<Value>,
    #[serde(default, alias = "max_turns")]
    max_turns_audit: usize,
    model_used: String,
    todo_items: Vec<TodoItem>,
    verification_command: String,
    thresholds: Thresholds,
    #[serde(default)]
    prompt_policy: PromptPolicy,
}

#[derive(Debug, Deserialize)]
struct Thresholds {
    compaction_char_threshold: usize,
    verification_checkpoint_turns: Vec<usize>,
    verification_checkpoint_cooldown_turns: usize,
    verification_checkpoint_max: usize,
    verification_checkpoint_min_tool_calls: usize,
    no_progress_checkpoint_tool_calls: usize,
    no_progress_checkpoint_cooldown_turns: usize,
    no_progress_checkpoint_max: usize,
    #[allow(dead_code)]
    #[serde(default = "default_late_no_progress_turn_percent")]
    late_no_progress_turn_percent: usize,
    #[serde(default = "default_stalled_tool_loop_calls")]
    stalled_tool_loop_calls: usize,
    #[serde(default = "default_stalled_tool_loop_cooldown_turns")]
    stalled_tool_loop_cooldown_turns: usize,
    #[serde(default = "default_stalled_tool_loop_max")]
    stalled_tool_loop_max: usize,
    deliverable_checkpoint_min_tool_calls: usize,
    deliverable_checkpoint_cooldown_turns: usize,
    deliverable_checkpoint_max: usize,
    empty_response_recovery_limit: usize,
    #[serde(default = "default_ephemeral_tool_output_max_chars")]
    ephemeral_tool_output_max_chars: usize,
    #[serde(default = "default_ephemeral_tool_output_keep_recent")]
    ephemeral_tool_output_keep_recent: usize,
    #[serde(default = "default_timeout_escalation_count")]
    timeout_escalation_count: usize,
    #[allow(dead_code)]
    #[serde(default = "default_timeout_escalation_late_turn_percent")]
    timeout_escalation_late_turn_percent: usize,
}

fn default_ephemeral_tool_output_max_chars() -> usize {
    4000
}

fn default_ephemeral_tool_output_keep_recent() -> usize {
    4
}

fn default_timeout_escalation_count() -> usize {
    2
}

fn default_timeout_escalation_late_turn_percent() -> usize {
    66
}

fn default_late_no_progress_turn_percent() -> usize {
    70
}

fn default_stalled_tool_loop_calls() -> usize {
    20
}

fn default_stalled_tool_loop_cooldown_turns() -> usize {
    8
}

fn default_stalled_tool_loop_max() -> usize {
    2
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct TodoItem {
    id: String,
    content: String,
    status: String,
}

#[derive(Clone, Debug, Deserialize)]
struct PromptPolicy {
    #[serde(default = "default_system_prompt")]
    system_prompt: String,
    #[serde(default)]
    tool_descriptions: String,
    #[serde(default)]
    notifications: String,
    #[serde(default = "default_task_guidance")]
    task_guidance: String,
    #[serde(default = "default_post_task_checks")]
    post_task_checks: String,
    #[serde(default = "default_self_test")]
    self_test: String,
}

impl Default for PromptPolicy {
    fn default() -> Self {
        Self {
            system_prompt: default_system_prompt(),
            tool_descriptions: String::new(),
            notifications: String::new(),
            task_guidance: default_task_guidance(),
            post_task_checks: default_post_task_checks(),
            self_test: default_self_test(),
        }
    }
}

