fn initialize_worker_messages(stdin: &mut impl BufRead, state: &mut WorkerState) {
    if !state.messages.is_empty() {
        return;
    }

    let system_prompt = render_system_prompt(&state.prompt_policy);
    state.messages.push(json!({
        "role": "system",
        "content": system_prompt,
    }));

    let entrypoint_scan = bounded_entrypoint_scan(stdin, state);
    let memory_hint = memory_availability_hint(state);
    apply_memory_failure_summary_preflight_contracts(state);
    let environment_context = join_non_empty(&[
        task_context_string(&state.task_context, "environment_context"),
        entrypoint_scan,
        memory_hint,
        format!(
            "Completion condition: {}",
            task_context_string_or(
                &state.task_context,
                "completion_condition",
                "Harbor verifier decides pass/fail."
            )
        ),
    ]);
    let verification_guidance = join_non_empty(&[
        state.prompt_policy.post_task_checks.trim().to_string(),
        state.prompt_policy.self_test.trim().to_string(),
    ]);
    let task_message = render_task_prompt(
        &state.task_instruction,
        &state.task_context,
        &state.prompt_policy.task_guidance,
        &environment_context,
        &verification_guidance,
    );
    state.messages.push(json!({
        "role": "user",
        "content": task_message,
    }));
}

fn render_system_prompt(policy: &PromptPolicy) -> String {
    let mut parts = vec![policy.system_prompt.trim().to_string()];
    if !policy.tool_descriptions.trim().is_empty() {
        parts.push(format!(
            "## Available Tools\n\n{}",
            policy.tool_descriptions.trim()
        ));
    }
    if !policy.notifications.trim().is_empty() {
        parts.push(format!(
            "## Notifications\n\n{}",
            policy.notifications.trim()
        ));
    }
    join_non_empty(&parts)
}

fn render_task_prompt(
    instruction: &str,
    task_context: &Value,
    task_guidance: &str,
    environment_context: &str,
    verification_guidance: &str,
) -> String {
    let mut sections = Vec::new();
    sections.push(format!("## Task\n\n{}", instruction));
    if !environment_context.trim().is_empty() {
        sections.push(format!(
            "## Environment Context\n{}",
            environment_context.trim()
        ));
    }
    sections.push(format!(
        "## Task Metadata\n- Domain: {}\n- Difficulty: {}\n- Task ID: {}",
        task_context_string_or(task_context, "domain", "unknown"),
        task_context_string_or(task_context, "difficulty", "unknown"),
        task_context_string_or(task_context, "task_id", "unknown")
    ));
    if !task_guidance.trim().is_empty() {
        sections.push(format!("## Guidance\n{}", task_guidance.trim()));
    }
    if !verification_guidance.trim().is_empty() {
        sections.push(verification_guidance.trim().to_string());
    }
    let previous_errors = previous_errors_section(task_context);
    if !previous_errors.is_empty() {
        sections.push(previous_errors);
    }
    join_non_empty(&sections)
}

fn previous_errors_section(task_context: &Value) -> String {
    let Some(errors) = task_context
        .get("previous_errors")
        .and_then(Value::as_array)
    else {
        return String::new();
    };
    let mut lines = Vec::new();
    for item in errors {
        let text = item
            .as_str()
            .map(str::to_string)
            .unwrap_or_else(|| item.to_string());
        let trimmed = text.trim();
        if !trimmed.is_empty() {
            lines.push(format!("- {}", truncate(trimmed, 2000)));
        }
    }
    if lines.is_empty() {
        return String::new();
    }
    format!(
        "## Previous Attempts (Learn From These)\n{}",
        lines.join("\n")
    )
}

fn bounded_entrypoint_scan(stdin: &mut impl BufRead, state: &mut WorkerState) -> String {
    if !has_tool(&state.tool_schemas, "bash") {
        return String::new();
    }
    let command = bounded_entrypoint_scan_command();
    let args = json!({"command": command, "timeout": 15});
    send_event(&json!({
        "type": "tool_request",
        "id": "entrypoint-scan",
        "tool": "bash",
        "args": args,
    }));
    let result = match read_typed_response::<ToolResponse>(stdin, "tool_response") {
        Ok(value) => value,
        Err(error) => ToolResponse {
            success: false,
            output: String::new(),
            error,
            duration_ms: 0.0,
            metadata: json!({}),
        },
    };
    state.append_trajectory(json!({
        "type": "entrypoint_scan",
        "success": result.success,
        "output": truncate(&result.output, 4000),
        "error": result.error,
        "operation_timeout_seconds_audit_only": 15,
        "entrypoint_scan_loop_stop_condition": false,
        "master_loop_stop_condition": false,
        "sub_agent_loop_stop_condition": false,
        "time_round_limit_stop_condition": false,
    }));
    if !result.success {
        return format!("Bounded entrypoint scan failed: {}", result.error);
    }
    format!(
        "Bounded entrypoint scan:\n{}",
        truncate(&result.output, 4000)
    )
}

fn bounded_entrypoint_scan_command() -> &'static str {
    concat!(
        "printf 'PWD: '; pwd\n",
        "printf '\\nTop-level files:\\n'; ls -la | sed -n '1,80p'\n",
        "printf '\\nLikely entrypoints:\\n'; ",
        "find . -maxdepth 2 -type f ",
        "\\( -name 'README*' -o -name 'pyproject.toml' -o -name 'package.json' ",
        "-o -name 'Makefile' -o -name '*.py' -o -name '*.sh' \\) ",
        "2>/dev/null | sed -n '1,80p'\n",
        "if [ -d /tests ]; then\n",
        "  printf '\\nVerifier surface files (visible /tests, read-only):\\n'\n",
        "  find /tests -maxdepth 2 -type f ",
        "\\( -name 'test*.py' -o -name '*.sh' -o -name 'pytest.ini' -o -name '*.txt' \\) ",
        "2>/dev/null | sed -n '1,40p'\n",
        "  printf '\\nVerifier-facing artifact and command hints (visible /tests snippets):\\n'\n",
        "  find /tests -maxdepth 2 -type f ",
        "\\( -name 'test*.py' -o -name '*.sh' -o -name 'pytest.ini' -o -name '*.txt' \\) ",
        "-print0 2>/dev/null | xargs -0 -r grep -InE ",
        "\"(/app/[^[:space:]\\\"')]+|/tmp/[^[:space:]\\\"')]+|/jail/[^[:space:]\\\"')]+|subprocess[.]run|pmars|gcc|pytest|assert |open\\(|Path\\()\" ",
        "2>/dev/null | sed -n '1,80p'\n",
        "fi"
    )
}

fn memory_availability_hint(state: &mut WorkerState) -> String {
    let task_id = task_context_string(&state.task_context, "task_id");
    if task_id.trim().is_empty() {
        return String::new();
    }
    let memory_path = task_context_string(&state.task_context, "memory_path");
    let memory_path = if memory_path.trim().is_empty() {
        task_context_string(&state.task_context, "hl_memory_path")
    } else {
        memory_path
    };
    if memory_path.trim().is_empty() {
        return String::new();
    }
    let runs_dir = Path::new(&memory_path).join("runs");
    if !runs_dir.exists() {
        return String::new();
    }

    let mut result_paths = Vec::new();
    if let Ok(entries) = fs::read_dir(&runs_dir) {
        for entry in entries.flatten() {
            result_paths.push(entry.path().join("result.json"));
        }
    }
    result_paths.sort();

    let mut total = 0usize;
    let mut passed = 0usize;
    let mut failed = 0usize;
    let mut last_trial_id = String::new();
    let mut last_trial_sort_key = String::new();
    let mut prior_failure_records = Vec::new();
    let mut prior_pass_records = Vec::new();
    for result_path in result_paths {
        let Ok(text) = fs::read_to_string(&result_path) else {
            continue;
        };
        let Ok(data) = serde_json::from_str::<Value>(&text) else {
            continue;
        };
        if task_context_string_or(&data, "task_id", "") != task_id {
            continue;
        }
        total += 1;
        let mut current_trial_id = task_context_string(&data, "trial_id");
        if current_trial_id.is_empty() {
            current_trial_id = result_path
                .parent()
                .and_then(Path::file_name)
                .and_then(|value| value.to_str())
                .unwrap_or("")
                .to_string();
        }
        let sort_key = prior_trial_sort_key(&data, &result_path, &current_trial_id);
        if last_trial_sort_key.is_empty() || sort_key > last_trial_sort_key {
            last_trial_sort_key = sort_key.clone();
            last_trial_id = current_trial_id.clone();
        }
        let status = task_context_string(&data, "status").to_ascii_lowercase();
        let score = safe_float(data.get("score"));
        if status == "passed" || score >= 1.0 {
            passed += 1;
            if let Some(summary) = prior_trial_pass_summary(&data, &current_trial_id, status, score)
            {
                prior_pass_records.push(PriorPassMemoryRecord { sort_key, summary });
            }
        } else if ["failed", "timeout", "error", "cancelled"].contains(&status.as_str())
            || score < 1.0
        {
            failed += 1;
            if let Some(summary) =
                prior_trial_failure_summary(&data, &result_path, &current_trial_id, status, score)
            {
                prior_failure_records.push(PriorTrialMemoryRecord { sort_key, summary });
            }
        }
    }

    if total == 0 {
        return String::new();
    }
    prior_pass_records.sort_by(|left, right| left.sort_key.cmp(&right.sort_key));
    let recent_pass_summaries: Vec<PriorPassSummary> = prior_pass_records
        .iter()
        .rev()
        .take(2)
        .map(|record| record.summary.clone())
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .collect();
    let pass_summary_lines = recent_pass_summaries
        .iter()
        .map(render_prior_pass_summary)
        .collect::<Vec<_>>();
    prior_failure_records.sort_by(|left, right| left.sort_key.cmp(&right.sort_key));
    let recent_failure_summaries: Vec<PriorTrialSummary> = prior_failure_records
        .iter()
        .rev()
        .take(3)
        .map(|record| record.summary.clone())
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .collect();
    let failure_summary_lines = recent_failure_summaries
        .iter()
        .map(render_prior_failure_summary)
        .collect::<Vec<_>>();
    let recurring_patterns = recurring_prior_failure_patterns(&prior_failure_records);
    add_memory_deliverable_targets(state, &failure_summary_lines);
    state.memory_failure_summary_lines = failure_summary_lines.clone();
    let injected_content = match (
        pass_summary_lines.is_empty(),
        failure_summary_lines.is_empty(),
    ) {
        (false, false) => "bounded_pass_and_failure_summary",
        (false, true) => "bounded_pass_summary",
        (true, false) => "bounded_failure_summary",
        (true, true) => "availability_only",
    };
    state.append_trajectory(json!({
        "type": "memory_availability_hint",
        "task_id": task_id,
        "prior_trials": total,
        "prior_passes": passed,
        "prior_failures": failed,
        "last_trial_id": last_trial_id,
        "injected_content": injected_content,
        "pass_summary_count": pass_summary_lines.len(),
        "failure_summary_count": failure_summary_lines.len(),
        "recurring_pattern_count": recurring_patterns.len(),
    }));
    let mut hint = format!(
        "Same-task memory: {total} prior host-side trial(s) exist ({passed} pass, {failed} non-pass). This prompt exposes only bounded structured summaries from prior result.json files: full logs, trajectories, artifact paths, and host memory paths are not inlined and are not mounted in the task workspace through the normal file or shell tools. Do not spend task time searching the current filesystem for host HL memory; use this only as a signal to avoid repeated failure modes while focusing on the current workspace."
    );
    if !recurring_patterns.is_empty() {
        hint.push_str("\nRecurring prior failure patterns:\n");
        hint.push_str(&recurring_patterns.join("\n"));
    }
    if !pass_summary_lines.is_empty() {
        hint.push_str("\nRecent verified pass signals:\n");
        hint.push_str(&pass_summary_lines.join("\n"));
    }
    if !failure_summary_lines.is_empty() {
        hint.push_str("\nRecent prior failure signals:\n");
        hint.push_str(&failure_summary_lines.join("\n"));
    }
    hint
}

fn apply_memory_failure_summary_preflight_contracts(state: &mut WorkerState) {
    if state.memory_failure_summary_lines.is_empty() {
        return;
    }
    let text = state.memory_failure_summary_lines.join("\n");
    if state_transition_set_contracts_from_text(&text)
        .iter()
        .any(|contract| contract.starts_with("state_transition_set_contract:"))
    {
        state.state_transition_set_preflight_required = true;
    }
}

fn prior_trial_sort_key(data: &Value, result_path: &Path, trial_id: &str) -> String {
    let timestamp = first_non_empty(&[
        task_context_string(data, "timestamp"),
        task_context_string(data.get("metadata").unwrap_or(&Value::Null), "timestamp"),
    ]);
    if !timestamp.is_empty() {
        return format!("0:{timestamp}:{trial_id}");
    }
    let modified = result_path
        .metadata()
        .and_then(|metadata| metadata.modified())
        .ok()
        .and_then(|time| time.duration_since(UNIX_EPOCH).ok())
        .map(|duration| duration.as_nanos())
        .unwrap_or(0);
    format!("1:{modified:039}:{trial_id}")
}

fn recurring_prior_failure_patterns(records: &[PriorTrialMemoryRecord]) -> Vec<String> {
    let mut counts: HashMap<String, usize> = HashMap::new();
    let mut labels: HashMap<String, String> = HashMap::new();
    for record in records {
        for (key, label) in prior_failure_pattern_keys(&record.summary) {
            *counts.entry(key.clone()).or_insert(0) += 1;
            labels.entry(key).or_insert(label);
        }
    }

    let mut ranked = counts
        .into_iter()
        .filter(|(_, count)| *count >= 2)
        .collect::<Vec<_>>();
    ranked.sort_by(|(left_key, left_count), (right_key, right_count)| {
        right_count
            .cmp(left_count)
            .then_with(|| left_key.cmp(right_key))
    });
    ranked
        .into_iter()
        .take(3)
        .filter_map(|(key, count)| {
            let label = labels.get(&key)?;
            Some(format!(
                "- recurring_pattern count={count}: {}",
                sanitize_memory_summary_fragment(label, 360)
            ))
        })
        .collect()
}

fn prior_failure_pattern_keys(summary: &PriorTrialSummary) -> Vec<(String, String)> {
    let mut patterns = Vec::new();
    let trajectory = summary.trajectory_signal.to_ascii_lowercase();
    let signal = summary.failure_signal.to_ascii_lowercase();
    let tail = summary.error_tail.to_ascii_lowercase();
    let timeout_phase = summary.timeout_phase.to_ascii_lowercase();

    if trajectory.contains("dependency_setup_trap")
        || trajectory.contains("failed_dependency_step")
        || trajectory.contains("dependency_output_failure")
        || signal.contains("dependency")
    {
        patterns.push((
            "dependency_setup_trap".to_string(),
            "dependency/setup loop repeated across prior non-passing trials; avoid package-manager, manual download, and source-build replay, and produce a dependency-free or cached-artifact deliverable first".to_string(),
        ));
    }
    if trajectory.contains("long_command_replay_trap")
        || timeout_phase.contains("agent_execution")
        || tail.contains("agent execution timed out")
    {
        patterns.push((
            "long_command_replay_trap".to_string(),
            "prior non-passing trials replayed long setup, build, download, training, or search commands without convergence; start with the smallest deliverable and bounded checks".to_string(),
        ));
    }
    if trajectory.contains("tool_timeout phase=build_compile")
        || trajectory.contains("tool_timeout phase=cross_arch_build")
        || trajectory.contains("tool_timeout phase=long_compute")
    {
        patterns.push((
            "long_build_or_compute_timeout".to_string(),
            "long build/compute commands timed out repeatedly; use a tiny fixture, lower parallelism, partial artifact reuse, or a direct implementation before any full run".to_string(),
        ));
    }
    if summary.verifier_failure.contains("verifier_failed=") {
        patterns.push((
            "verifier_mismatch".to_string(),
            "Harbor verifier failures repeat; extract the exact failed assertion or expected artifact and fix that semantic contract before broad exploration".to_string(),
        ));
    }
    patterns
}

fn prior_trial_failure_summary(
    data: &Value,
    result_path: &Path,
    trial_id: &str,
    status: String,
    score: f64,
) -> Option<PriorTrialSummary> {
    let metadata = data.get("metadata").unwrap_or(&Value::Null);
    let timeout_phase = task_context_string(metadata, "timeout_phase");
    let failure_signal = first_non_empty(&[
        task_context_string(metadata, "failure_category"),
        task_context_string(metadata, "agent_exception_type"),
        task_context_string(metadata, "score_exclusion_reason"),
        task_context_string(data, "failure_category"),
    ]);
    let verifier_failure = prior_verifier_failure_summary(data);
    let trajectory_signal = prior_trajectory_failure_summary(result_path);
    let error_tail = prior_error_tail(data);
    if status.trim().is_empty()
        && timeout_phase.trim().is_empty()
        && failure_signal.trim().is_empty()
        && verifier_failure.trim().is_empty()
        && trajectory_signal.trim().is_empty()
        && error_tail.trim().is_empty()
    {
        return None;
    }
    Some(PriorTrialSummary {
        trial_id: sanitize_memory_summary_fragment(trial_id, 80),
        status: sanitize_memory_summary_fragment(&status, 40),
        score,
        timeout_phase: sanitize_memory_summary_fragment(&timeout_phase, 80),
        failure_signal: sanitize_memory_summary_fragment(&failure_signal, 120),
        verifier_failure: sanitize_memory_summary_fragment(&verifier_failure, 520),
        trajectory_signal: sanitize_memory_summary_fragment(&trajectory_signal, 520),
        error_tail: sanitize_memory_summary_fragment(&error_tail, 220),
    })
}

fn prior_trial_pass_summary(
    data: &Value,
    trial_id: &str,
    status: String,
    score: f64,
) -> Option<PriorPassSummary> {
    let verified = data
        .get("verified")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    if !verified {
        return None;
    }
    let verifier_success = prior_verifier_success_summary(data);
    let metadata_signal = prior_pass_metadata_signal(data);
    let model_signal = prior_pass_model_signal(data);
    Some(PriorPassSummary {
        trial_id: sanitize_memory_summary_fragment(trial_id, 80),
        status: sanitize_memory_summary_fragment(&status, 40),
        score,
        verified,
        verifier_success: sanitize_memory_summary_fragment(&verifier_success, 220),
        metadata_signal: sanitize_memory_summary_fragment(&metadata_signal, 220),
        model_signal: sanitize_memory_summary_fragment(&model_signal, 160),
    })
}

fn prior_pass_metadata_signal(data: &Value) -> String {
    let metadata = data.get("metadata").unwrap_or(&Value::Null);
    let task_metadata = first_object([data.get("task_metadata"), metadata.get("task_metadata")]);
    let mut parts = Vec::new();
    for (label, value) in [
        ("domain", task_context_string(data, "task_domain")),
        ("difficulty", task_context_string(data, "task_difficulty")),
        ("category", task_context_string(task_metadata, "category")),
        ("task_type", task_context_string(task_metadata, "task_type")),
    ] {
        if !value.trim().is_empty() {
            parts.push(format!("{label}={value}"));
        }
    }
    let tags = string_array(task_metadata.get("tags"))
        .into_iter()
        .take(5)
        .collect::<Vec<_>>();
    if !tags.is_empty() {
        parts.push(format!("tags=[{}]", tags.join("; ")));
    }
    parts.join(", ")
}

fn prior_pass_model_signal(data: &Value) -> String {
    let metadata = data.get("metadata").unwrap_or(&Value::Null);
    let model_config = metadata.get("model_config").unwrap_or(&Value::Null);
    let mut parts = Vec::new();
    for (label, value) in [
        ("model", task_context_string(data, "model_used")),
        ("provider", task_context_string(model_config, "provider")),
        ("scope_model", task_context_string(model_config, "model")),
    ] {
        if !value.trim().is_empty() {
            parts.push(format!("{label}={value}"));
        }
    }
    parts.join(", ")
}

fn prior_verifier_success_summary(data: &Value) -> String {
    let mut sources = Vec::new();
    let metadata = data.get("metadata").unwrap_or(&Value::Null);
    for value in [
        metadata.get("verifier_logs"),
        data.get("verifier_logs"),
        data.get("verifier_output"),
    ]
    .into_iter()
    .flatten()
    {
        if let Some(text) = value.as_str() {
            sources.push(text.to_string());
        }
    }
    for source in sources {
        for block in ctrf_json_blocks(&source) {
            if let Some(summary) = summarize_ctrf_success_block(&block) {
                return summary;
            }
        }
    }
    String::new()
}

fn prior_trajectory_failure_summary(result_path: &Path) -> String {
    let Some(run_dir) = result_path.parent() else {
        return String::new();
    };
    let trajectory_path = run_dir.join("trajectory.jsonl");
    let Ok(text) = fs::read_to_string(&trajectory_path) else {
        return String::new();
    };
    let lines = text.lines().rev().take(120).collect::<Vec<_>>();
    let mut signals = Vec::new();
    let mut tool_timeout_evidence = 0usize;
    let mut dependency_setup_evidence = 0usize;
    let mut saw_dependency_checkpoint = false;
    let mut saw_terminal_environment_unavailable = false;
    for line in lines.into_iter().rev() {
        let Ok(event) = serde_json::from_str::<Value>(line) else {
            continue;
        };
        let event_type = task_context_string_or(&event, "type", "");
        match event_type.as_str() {
            "tool_timeout_recovery_prompt" => {
                let tool = task_context_string(&event, "tool");
                let command = task_context_string(&event, "command");
                tool_timeout_evidence += 1;
                if classify_timeout_phase(&tool, &command) == "dependency_setup" {
                    dependency_setup_evidence += 1;
                }
            }
            "tool_call" => {
                let error = task_context_string(&event, "error");
                let output = task_context_string(&event, "output");
                if text_mentions_timeout(&format!("{error}\n{output}")) {
                    tool_timeout_evidence += 1;
                }
                if trajectory_tool_call_failure_signal(&event)
                    .map(|signal| {
                        signal.starts_with("failed_dependency_step")
                            || signal.starts_with("dependency_output_failure")
                    })
                    .unwrap_or(false)
                {
                    dependency_setup_evidence += 1;
                }
            }
            "dependency_recovery_checkpoint" => {
                saw_dependency_checkpoint = true;
                dependency_setup_evidence += 1;
            }
            "terminal_environment_unavailable" => {
                saw_terminal_environment_unavailable = true;
            }
            _ => {}
        }
        if let Some(signal) = trajectory_event_failure_signal(&event) {
            if !signals.iter().any(|existing| existing == &signal) {
                signals.push(signal);
            }
        }
        if signals.len() >= 3
            && dependency_setup_evidence >= 2
            && saw_dependency_checkpoint
            && saw_terminal_environment_unavailable
        {
            break;
        }
    }
    if dependency_setup_evidence >= 2
        && saw_dependency_checkpoint
        && saw_terminal_environment_unavailable
    {
        let strategy_signal = "dependency_setup_trap: prior install/build loop exhausted the run and terminal became unavailable; avoid replaying package managers or source builds; use existing tools or cached artifacts; produce the smallest deliverable early".to_string();
        if !signals.iter().any(|existing| existing == &strategy_signal) {
            signals.insert(0, strategy_signal);
        }
    }
    if dependency_setup_evidence < 2
        && (tool_timeout_evidence >= 3
            || (tool_timeout_evidence >= 2 && saw_terminal_environment_unavailable))
    {
        let strategy_signal = "long_command_replay_trap: prior run replayed long commands without convergence; bound setup/build/download work; avoid background package managers or lock cleanup; create or check the smallest deliverable before more broad work".to_string();
        if !signals.iter().any(|existing| existing == &strategy_signal) {
            let insert_at = if signals
                .first()
                .map(|signal| signal.starts_with("dependency_setup_trap"))
                .unwrap_or(false)
            {
                1
            } else {
                0
            };
            signals.insert(insert_at, strategy_signal);
        }
    }
    signals.truncate(4);
    signals.join("; ")
}

fn text_mentions_timeout(text: &str) -> bool {
    let lowered = text.to_ascii_lowercase();
    lowered.contains("timed out")
        || lowered.contains("timeout")
        || lowered.contains("timeoutexpired")
}

fn trajectory_event_failure_signal(event: &Value) -> Option<String> {
    let event_type = task_context_string_or(event, "type", "");
    match event_type.as_str() {
        "terminal_environment_unavailable" => {
            let error = task_context_string(event, "error");
            Some(format!(
                "terminal_environment_unavailable: {}",
                first_non_empty(&[error, "service stopped".to_string()])
            ))
        }
        "tool_timeout_recovery_prompt" => {
            let tool = task_context_string(event, "tool");
            let command = task_context_string(event, "command");
            let phase = classify_timeout_phase(&tool, &command);
            Some(format!(
                "tool_timeout phase={} command={}",
                phase,
                command_summary_for_memory(&command)
            ))
        }
        "dependency_recovery_checkpoint" => Some(
            "dependency_recovery_checkpoint: repeated package/tool setup failures blocked progress"
                .to_string(),
        ),
        "tool_call" => trajectory_tool_call_failure_signal(event),
        _ => None,
    }
}

fn trajectory_tool_call_failure_signal(event: &Value) -> Option<String> {
    let success = event
        .get("success")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let args = event.get("args").unwrap_or(&Value::Null);
    let command = task_context_string(args, "command");
    let error = task_context_string(event, "error");
    let output = task_context_string(event, "output");
    let text = format!("{error}\n{output}");
    let metadata = event.get("metadata").unwrap_or(&Value::Null);
    let semantic_kind = task_context_string(metadata, "semantic_failure_kind");

    if !success {
        if command_looks_like_package_management(&command) || looks_like_dependency_failure(&text) {
            return Some(format!(
                "failed_dependency_step command={} error={}",
                command_summary_for_memory(&command),
                first_non_empty(&[semantic_kind, dependency_error_summary(&text)])
            ));
        }
        if !error.trim().is_empty() {
            return Some(format!(
                "failed_tool error={} command={}",
                error,
                command_summary_for_memory(&command)
            ));
        }
    }

    if command_looks_like_package_management(&command) && looks_like_dependency_failure(&text) {
        return Some(format!(
            "dependency_output_failure command={} error={}",
            command_summary_for_memory(&command),
            dependency_error_summary(&text)
        ));
    }
    None
}

fn command_summary_for_memory(command: &str) -> String {
    let mut tokens = shell_tokens(command);
    if tokens.len() > 8 {
        tokens.truncate(8);
    }
    truncate(&tokens.join(" "), 140)
}

fn dependency_error_summary(text: &str) -> String {
    let needles = [
        "could not get lock",
        "unable to acquire the dpkg frontend lock",
        "unable to locate package",
        "no matching distribution found",
        "certificate verify failed",
        "unable to access index for repository",
        "cannot open url",
        "is not available for this version of r",
        "command timed out",
        "service \"main\" is not running",
    ];
    let lowered = text.to_ascii_lowercase();
    for needle in needles {
        if lowered.contains(needle) {
            return needle.to_string();
        }
    }
    first_non_empty(
        &text
            .lines()
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .take(1)
            .map(str::to_string)
            .collect::<Vec<_>>(),
    )
}

fn prior_verifier_failure_summary(data: &Value) -> String {
    let mut sources = Vec::new();
    let metadata = data.get("metadata").unwrap_or(&Value::Null);
    for value in [
        metadata.get("verifier_logs"),
        data.get("verifier_logs"),
        data.get("verifier_output"),
    ]
    .into_iter()
    .flatten()
    {
        if let Some(text) = value.as_str() {
            sources.push(text.to_string());
        }
    }
    if let Some(items) = data.get("error_log").and_then(Value::as_array) {
        for item in items {
            if let Some(text) = item.as_str() {
                sources.push(text.to_string());
            } else if !item.is_null() {
                sources.push(item.to_string());
            }
        }
    }

    for source in sources {
        for block in ctrf_json_blocks(&source) {
            if let Some(summary) = summarize_ctrf_failure_block(&block) {
                return summary;
            }
        }
    }
    String::new()
}

fn ctrf_json_blocks(text: &str) -> Vec<String> {
    let mut blocks = Vec::new();
    let marker = "## ctrf.json";
    let mut search_start = 0usize;
    while let Some(marker_offset) = text[search_start..].find(marker) {
        let after_marker = search_start + marker_offset + marker.len();
        let Some(relative_json_start) = text[after_marker..].find('{') else {
            break;
        };
        let json_start = after_marker + relative_json_start;
        if let Some(json_end) = balanced_json_object_end(text, json_start) {
            blocks.push(text[json_start..json_end].to_string());
            search_start = json_end;
        } else {
            break;
        }
    }
    blocks
}

fn balanced_json_object_end(text: &str, start: usize) -> Option<usize> {
    let mut depth = 0usize;
    let mut in_string = false;
    let mut escaped = false;
    for (offset, ch) in text[start..].char_indices() {
        if in_string {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_string = false;
            }
            continue;
        }
        match ch {
            '"' => in_string = true,
            '{' => depth += 1,
            '}' => {
                depth = depth.saturating_sub(1);
                if depth == 0 {
                    return Some(start + offset + ch.len_utf8());
                }
            }
            _ => {}
        }
    }
    None
}

fn summarize_ctrf_failure_block(block: &str) -> Option<String> {
    let Ok(data) = serde_json::from_str::<Value>(block) else {
        return None;
    };
    let results = data.get("results").unwrap_or(&data);
    let summary = results.get("summary").unwrap_or(&Value::Null);
    let failed = safe_usize(summary.get("failed"));
    let tests = safe_usize(summary.get("tests"));
    let passed = safe_usize(summary.get("passed"));
    if failed == 0 {
        return None;
    }

    let mut failed_tests = Vec::new();
    let mut failed_test_evidence = Vec::new();
    if let Some(items) = results.get("tests").and_then(Value::as_array) {
        for item in items {
            let status = task_context_string_or(item, "status", "").to_ascii_lowercase();
            let raw_status = task_context_string_or(item, "raw_status", "").to_ascii_lowercase();
            if status != "failed" && !raw_status.contains("failed") {
                continue;
            }
            let name = first_non_empty(&[
                task_context_string(item, "name"),
                task_context_string(item, "file_path"),
            ]);
            let trace = task_context_string(item, "trace");
            let trace_failure = verifier_trace_failure_line(&trace);
            let message =
                verifier_failure_detail(&task_context_string(item, "message"), &trace_failure);
            let mut evidence_parts = Vec::new();
            if !name.trim().is_empty() {
                evidence_parts.push(name.clone());
            }
            if !trace.trim().is_empty() {
                evidence_parts.push(trace.clone());
            }
            if !message.trim().is_empty() {
                evidence_parts.push(message.clone());
            }
            if !evidence_parts.is_empty() {
                failed_test_evidence.push(evidence_parts.join("\n"));
            }
            let mut parts = Vec::new();
            if !name.trim().is_empty() {
                parts.push(sanitize_memory_summary_fragment(&name, 90));
            }
            if !message.trim().is_empty() {
                parts.push(sanitize_memory_summary_fragment(&message, 140));
            }
            if !parts.is_empty() {
                failed_tests.push(parts.join(" => "));
            }
            if failed_tests.len() >= 3 {
                break;
            }
        }
    }

    let mut parts = vec![format!("verifier_failed={failed}/{tests} tests")];
    if passed > 0 {
        parts.push(format!("passed={passed}"));
    }
    if !failed_tests.is_empty() {
        let size_cap_evidence = deliverable_size_cap_evidence_from_text(block);
        let tokenized_output_evidence = tokenized_output_file_evidence(block);
        let literal_output_evidence = literal_output_file_evidence(block);
        let missing_output_evidence = missing_output_artifact_evidence(block);
        let caffe_cifar10_evidence = caffe_cifar10_artifact_contract(block);
        let verifier_focus = verifier_repair_focus(if failed_test_evidence.is_empty() {
            &failed_tests
        } else {
            &failed_test_evidence
        });
        let repair_focus = if size_cap_evidence.is_some() {
            "repair_deliverable_size_cap".to_string()
        } else if caffe_cifar10_evidence.is_some() {
            "repair_caffe_cifar10_artifact_contract".to_string()
        } else if tokenized_output_evidence.is_some() {
            "repair_tokenized_output_file_contract".to_string()
        } else if literal_output_evidence.is_some() {
            "repair_literal_output_file_content".to_string()
        } else if missing_output_evidence.is_some()
            && matches!(
                verifier_focus.as_str(),
                "produce_expected_file_or_path" | "rerun_specific_failed_tests_after_fix"
            )
        {
            "repair_missing_output_artifact_contract".to_string()
        } else {
            verifier_focus
        };
        parts.push(format!("repair_focus={repair_focus}"));
        let expected_artifacts = verifier_expected_artifacts(block);
        if !expected_artifacts.is_empty() {
            parts.push(format!(
                "expected_artifacts=[{}]",
                expected_artifacts.join("; ")
            ));
        }
        if let Some(evidence) = size_cap_evidence {
            parts.push(format!(
                "size_cap=[{} < {} bytes{}]",
                evidence.path,
                evidence.limit_bytes,
                evidence
                    .observed_bytes
                    .map(|value| format!(" observed={value}"))
                    .unwrap_or_default()
            ));
        }
        if let Some(evidence) = literal_output_evidence {
            parts.push(format!(
                "literal_output=[{} == {}]",
                evidence.path,
                quoted_contract_literal(&evidence.expected)
            ));
        }
        if let Some(evidence) = tokenized_output_evidence {
            parts.push(format!(
                "tokenized_output=[{} tokens={}]",
                evidence.path,
                evidence.expected_tokens.join("|")
            ));
        }
        if let Some(evidence) = missing_output_evidence {
            parts.push(format!(
                "missing_output=[{}]",
                memory_summary_expected_artifact_paths(&evidence.paths).join("; ")
            ));
        }
        parts.push(format!("failed_tests=[{}]", failed_tests.join("; ")));
    }
    Some(parts.join(", "))
}

fn memory_summary_expected_artifact_paths(paths: &[String]) -> Vec<String> {
    paths
        .iter()
        .map(|path| normalize_expected_artifact_path(path))
        .collect()
}

fn normalize_expected_artifact_path(path: &str) -> String {
    let trimmed = path.trim();
    if looks_like_verifier_expected_artifact_path(trimmed) {
        return trimmed.to_string();
    }
    Path::new(trimmed)
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or(trimmed)
        .to_string()
}

fn summarize_ctrf_success_block(block: &str) -> Option<String> {
    let Ok(data) = serde_json::from_str::<Value>(block) else {
        return None;
    };
    let results = data.get("results").unwrap_or(&data);
    let summary = results.get("summary").unwrap_or(&Value::Null);
    let failed = safe_usize(summary.get("failed"));
    if failed != 0 {
        return None;
    }
    let tests = safe_usize(summary.get("tests"));
    let passed = safe_usize(summary.get("passed"));
    if tests == 0 && passed == 0 {
        return None;
    }
    let mut parts = vec![format!("verifier_passed={passed}/{tests} tests")];
    let mut passed_tests = Vec::new();
    if let Some(items) = results.get("tests").and_then(Value::as_array) {
        for item in items {
            let status = task_context_string_or(item, "status", "").to_ascii_lowercase();
            let raw_status = task_context_string_or(item, "raw_status", "").to_ascii_lowercase();
            if status != "passed" && raw_status != "passed" {
                continue;
            }
            let name = first_non_empty(&[
                task_context_string(item, "name"),
                task_context_string(item, "file_path"),
            ]);
            if !name.trim().is_empty() {
                passed_tests.push(sanitize_memory_summary_fragment(&name, 80));
            }
            if passed_tests.len() >= 3 {
                break;
            }
        }
    }
    if !passed_tests.is_empty() {
        parts.push(format!("passed_tests=[{}]", passed_tests.join("; ")));
    }
    Some(parts.join(", "))
}

fn verifier_failure_detail(message: &str, trace_failure: &str) -> String {
    let message = message.trim();
    if message.is_empty() {
        return sanitize_memory_summary_fragment(trace_failure.trim(), 180);
    }
    if trace_failure.trim().is_empty() {
        return message.to_string();
    }
    if verifier_message_is_generic(message) {
        return sanitize_memory_summary_fragment(trace_failure.trim(), 180);
    }
    message.to_string()
}

fn verifier_message_is_generic(message: &str) -> bool {
    let lowered = message.to_ascii_lowercase();
    lowered.contains("call phase")
        || lowered == "the test failed"
        || lowered == "assertion error"
        || lowered == "subprocess failed"
}

fn verifier_repair_focus(failed_tests: &[String]) -> String {
    let lowered = failed_tests.join("\n").to_ascii_lowercase();
    if looks_like_git_sanitization_scope_failure(&lowered) {
        return "repair_git_sanitization_scope_contract".to_string();
    }
    if looks_like_gpt2_codegolf_text_contract_failure(&lowered) {
        return "repair_gpt2_codegolf_text_contract".to_string();
    }
    if looks_like_caffe_cifar10_artifact_failure(&lowered) {
        return "repair_caffe_cifar10_artifact_contract".to_string();
    }
    if looks_like_adaptive_rejection_sampler_contract_failure(&lowered) {
        return "repair_adaptive_rejection_sampler_api_contract".to_string();
    }
    if looks_like_spectral_peak_fit_failure(&lowered) {
        return "repair_spectral_peak_fit_contract".to_string();
    }
    if looks_like_structured_csv_table_failure(&lowered) {
        return "repair_structured_csv_table_contract".to_string();
    }
    if looks_like_structured_numeric_output_failure(&lowered) {
        return "repair_structured_numeric_output_contract".to_string();
    }
    if looks_like_generated_script_structure_failure(&lowered) {
        return "repair_generated_script_structure_contract".to_string();
    }
    if looks_like_arithmetic_reference_failure(&lowered) {
        return "repair_arithmetic_reference_implementation".to_string();
    }
    if looks_like_dataset_shard_generalization_failure(&lowered) {
        return "repair_dataset_shard_generalization".to_string();
    }
    if looks_like_dna_insert_primer_pair_failure(&lowered) {
        return "repair_dna_insert_primer_pair_contract".to_string();
    }
    if looks_like_dna_assembly_primer_failure(&lowered) {
        return "repair_dna_assembly_primer_contract".to_string();
    }
    if looks_like_html_filter_blocks_xss_failure(&lowered) {
        return "repair_html_filter_blocks_xss_contract".to_string();
    }
    if looks_like_html_filter_alert_bypass_failure(&lowered) {
        return "repair_html_filter_alert_bypass_contract".to_string();
    }
    if looks_like_sparql_result_set_aggregation_failure(&lowered) {
        return "repair_sparql_result_set_aggregation".to_string();
    }
    if looks_like_tokenized_output_file_failure(&lowered) {
        return "repair_tokenized_output_file_contract".to_string();
    }
    if looks_like_literal_output_file_content_failure(&lowered) {
        return "repair_literal_output_file_content".to_string();
    }
    if looks_like_deliverable_size_cap_failure(&lowered) {
        return "repair_deliverable_size_cap".to_string();
    }
    if looks_like_single_file_deliverable_directory_failure(&lowered) {
        return "repair_single_file_deliverable_directory_contract".to_string();
    }
    if looks_like_vm_service_readiness_failure(&lowered) {
        return "repair_vm_service_readiness_contract".to_string();
    }
    if looks_like_corewar_warrior_failure(&lowered) {
        return "repair_corewar_warrior_contract".to_string();
    }
    if looks_like_pytorch_distributed_parallelism_failure(&lowered) {
        return "repair_pytorch_distributed_parallelism_contract".to_string();
    }
    if lowered.contains("not found in python-chess") || lowered.contains("python-chess moves") {
        return "match_expected_state_transition_set".to_string();
    }
    if looks_like_missing_output_artifact_failure(&lowered) {
        return "repair_missing_output_artifact_contract".to_string();
    }
    if lowered.contains("calledprocesserror") || lowered.contains("returned non-zero exit status") {
        return "make_verifier_invoked_command_exit_zero".to_string();
    }
    if lowered.contains("not found in python") || lowered.contains("does not match") {
        return "match_expected_output_semantics".to_string();
    }
    if lowered.contains("filenotfounderror")
        || lowered.contains("no such file or directory")
        || lowered.contains("missing")
    {
        return "produce_expected_file_or_path".to_string();
    }
    if lowered.contains("assertionerror") || lowered.contains("assert false") {
        return "fix_asserted_behavior_not_test_harness".to_string();
    }
    "rerun_specific_failed_tests_after_fix".to_string()
}

fn verifier_expected_artifacts(text: &str) -> Vec<String> {
    let mut artifacts = Vec::new();
    let mut seen = HashSet::new();
    let mut push_artifact = |path: &str, artifacts: &mut Vec<String>| {
        let lowered_path = path.to_ascii_lowercase();
        if lowered_path.starts_with("/tests/") || lowered_path.contains("/tests/") {
            return;
        }
        let artifact = normalize_expected_artifact_path(path);
        let basename = Path::new(&artifact)
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or(&artifact);
        let lowered_basename = basename.to_ascii_lowercase();
        if lowered_basename == "test_outputs.py" || lowered_basename.ends_with(".log") {
            return;
        }
        if seen.insert(artifact.clone()) {
            artifacts.push(artifact);
        }
    };

    if let Some(evidence) = deliverable_size_cap_evidence_from_text(text) {
        push_artifact(&evidence.path, &mut artifacts);
    }
    if let Some(evidence) = tokenized_output_file_evidence(text) {
        push_artifact(&evidence.path, &mut artifacts);
    }
    if let Some(evidence) = literal_output_file_evidence(text) {
        push_artifact(&evidence.path, &mut artifacts);
    }
    if let Some(evidence) = missing_output_artifact_evidence(text) {
        for path in evidence.paths {
            push_artifact(&path, &mut artifacts);
        }
    }

    for (candidate, start, end) in verifier_artifact_candidate_tokens(text) {
        if !verifier_artifact_context_mentions_missing(text, start, end) {
            continue;
        }
        push_artifact(&candidate, &mut artifacts);
        if artifacts.len() >= 4 {
            break;
        }
    }
    artifacts
}

fn verifier_artifact_candidate_tokens(text: &str) -> Vec<(String, usize, usize)> {
    let mut tokens = Vec::new();
    let mut seen = HashSet::new();
    for prefix in ["/app/", "/tmp/", "/jail/"] {
        for token in absolute_path_candidate_tokens(text, prefix) {
            if seen.insert(token.0.clone()) {
                tokens.push(token);
            }
        }
    }
    tokens.sort_by_key(|(_, start, _)| *start);
    tokens
}

fn app_path_candidate_tokens(text: &str) -> Vec<(String, usize, usize)> {
    absolute_path_candidate_tokens(text, "/app/")
}

fn absolute_path_candidate_tokens(text: &str, prefix: &str) -> Vec<(String, usize, usize)> {
    let mut tokens = Vec::new();
    let mut search_start = 0usize;
    while let Some(offset) = text[search_start..].find(prefix) {
        let start = search_start + offset;
        let mut end = start;
        for (relative, ch) in text[start..].char_indices() {
            if relative == 0 || is_path_char(ch) {
                end = start + relative + ch.len_utf8();
                continue;
            }
            break;
        }
        let candidate = text[start..end]
            .trim_matches(|ch: char| {
                matches!(
                    ch,
                    '`' | '\'' | '"' | '.' | ',' | ':' | ';' | ')' | ']' | '}'
                )
            })
            .to_string();
        if looks_like_verifier_expected_artifact_path(&candidate) {
            tokens.push((candidate, start, end));
        }
        search_start = end.max(start + prefix.len());
    }
    tokens
}

fn verifier_artifact_context_mentions_missing(text: &str, start: usize, end: usize) -> bool {
    let window_start = text[..start]
        .char_indices()
        .rev()
        .nth(90)
        .map(|(idx, _)| idx)
        .unwrap_or(0);
    let window_end = text[end..]
        .char_indices()
        .nth(90)
        .map(|(idx, _)| end + idx)
        .unwrap_or(text.len());
    let window = text[window_start..window_end].to_ascii_lowercase();
    [
        "does not exist",
        "no such file",
        "file not found",
        "missing",
        "not generated",
        "not created",
        "failed to create",
        "unable to open file",
        "timeout waiting for",
        "required output file",
        "expected output",
    ]
    .iter()
    .any(|marker| window.contains(marker))
}

fn safe_usize(value: Option<&Value>) -> usize {
    value
        .and_then(Value::as_u64)
        .and_then(|value| usize::try_from(value).ok())
        .unwrap_or(0)
}

fn verifier_trace_failure_line(trace: &str) -> String {
    let mut fallback = String::new();
    for line in trace.lines().rev() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('_') {
            continue;
        }
        if verifier_trace_line_is_location_only(trimmed) {
            continue;
        }
        if let Some(stripped) = trimmed.strip_prefix("E       ") {
            return stripped.trim().to_string();
        }
        if let Some(stripped) = trimmed.strip_prefix("E   ") {
            return stripped.trim().to_string();
        }
        if trimmed.contains("Error:")
            || trimmed.contains("AssertionError")
            || trimmed.contains("FileNotFoundError")
            || trimmed.contains("CalledProcessError")
            || trimmed.contains("PatternError")
        {
            return trimmed.to_string();
        }
        if fallback.is_empty() && trimmed.starts_with('>') {
            fallback = trimmed.trim_start_matches('>').trim().to_string();
        }
    }
    fallback
}

fn verifier_trace_line_is_location_only(line: &str) -> bool {
    (line.starts_with('/') || line.starts_with("./") || line.starts_with("../"))
        && line.contains(".py:")
        && (line.contains("AssertionError")
            || line.contains("FileNotFoundError")
            || line.contains("CalledProcessError"))
}

fn prior_error_tail(data: &Value) -> String {
    if let Some(items) = data.get("error_log").and_then(Value::as_array) {
        for item in items.iter().rev() {
            let text = item
                .as_str()
                .map(str::to_string)
                .unwrap_or_else(|| item.to_string());
            if !text.trim().is_empty() {
                return text;
            }
        }
    }
    task_context_string(data, "verifier_output")
}

fn render_prior_failure_summary(summary: &PriorTrialSummary) -> String {
    let mut parts = vec![format!(
        "status={}, score={:.3}",
        summary.status, summary.score
    )];
    if !summary.timeout_phase.is_empty() {
        parts.push(format!("timeout_phase={}", summary.timeout_phase));
    }
    if !summary.failure_signal.is_empty() {
        parts.push(format!("signal={}", summary.failure_signal));
    }
    if !summary.verifier_failure.is_empty() {
        parts.push(format!("verifier={}", summary.verifier_failure));
    }
    if !summary.trajectory_signal.is_empty() {
        parts.push(format!("trajectory={}", summary.trajectory_signal));
    }
    if !summary.error_tail.is_empty() {
        parts.push(format!("tail={}", summary.error_tail));
    }
    format!("- {}: {}", summary.trial_id, parts.join(", "))
}

fn render_prior_pass_summary(summary: &PriorPassSummary) -> String {
    let mut parts = vec![format!(
        "status={}, score={:.3}, verified={}",
        summary.status, summary.score, summary.verified
    )];
    if !summary.verifier_success.is_empty() {
        parts.push(format!("verifier={}", summary.verifier_success));
    }
    if !summary.metadata_signal.is_empty() {
        parts.push(format!("metadata={}", summary.metadata_signal));
    }
    if !summary.model_signal.is_empty() {
        parts.push(format!("model={}", summary.model_signal));
    }
    parts.push(
        "use_as_strategy_signal=current task still requires current-workspace checks and Harbor verification".to_string(),
    );
    format!("- {}: {}", summary.trial_id, parts.join(", "))
}

fn add_memory_deliverable_targets(state: &mut WorkerState, failure_summary_lines: &[String]) {
    let mut seen: HashSet<String> = state.deliverable_targets.iter().cloned().collect();
    let mut gate_seen: HashSet<String> = state
        .missing_output_artifact_gate_targets
        .iter()
        .cloned()
        .collect();
    for line in failure_summary_lines {
        for artifact in expected_artifacts_from_summary_line(line) {
            if seen.insert(artifact.clone()) {
                state.deliverable_targets.push(artifact.clone());
            }
            if missing_output_artifact_gate_target_is_safe(&artifact)
                && gate_seen.insert(artifact.clone())
            {
                state.missing_output_artifact_gate_targets.push(artifact);
            }
            if state.deliverable_targets.len() >= 8 {
                return;
            }
        }
    }
}

fn expected_artifacts_from_summary_line(line: &str) -> Vec<String> {
    let marker = "expected_artifacts=[";
    let Some(start) = line.find(marker) else {
        return Vec::new();
    };
    let after_marker = start + marker.len();
    let Some(end_offset) = line[after_marker..].find(']') else {
        return Vec::new();
    };
    line[after_marker..after_marker + end_offset]
        .split(';')
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .filter(|value| looks_like_deliverable_path(value))
        .take(4)
        .map(str::to_string)
        .collect()
}

fn first_non_empty(values: &[String]) -> String {
    values
        .iter()
        .map(|value| value.trim())
        .find(|value| !value.is_empty())
        .unwrap_or("")
        .to_string()
}

fn first_object<'a>(values: [Option<&'a Value>; 2]) -> &'a Value {
    for value in values.into_iter().flatten() {
        if value.is_object() {
            return value;
        }
    }
    &Value::Null
}

fn string_array(value: Option<&Value>) -> Vec<String> {
    match value {
        Some(Value::Array(items)) => items
            .iter()
            .filter_map(|item| item.as_str().map(str::to_string))
            .filter(|item| !item.trim().is_empty())
            .collect(),
        Some(Value::String(text)) => text
            .split(',')
            .map(str::trim)
            .filter(|item| !item.is_empty())
            .map(str::to_string)
            .collect(),
        _ => Vec::new(),
    }
}

fn sanitize_memory_summary_fragment(value: &str, max_chars: usize) -> String {
    let collapsed = value
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .collect::<Vec<_>>()
        .join(" | ");
    let scrubbed = collapsed
        .split_whitespace()
        .filter(|token| !memory_summary_token_is_path_like(token))
        .collect::<Vec<_>>()
        .join(" ");
    truncate(&scrubbed, max_chars)
}

fn memory_summary_token_is_path_like(token: &str) -> bool {
    let trimmed =
        token.trim_matches(|ch: char| matches!(ch, ',' | ':' | ';' | ')' | '(' | '\'' | '"' | '`'));
    trimmed.starts_with('/')
        || trimmed.starts_with("./")
        || trimmed.starts_with("../")
        || trimmed.contains("/trials/")
        || trimmed.contains("/runs/")
        || trimmed.contains("\\")
}

fn execute_tool_call(
    stdin: &mut impl BufRead,
    state: &WorkerState,
    call: &ToolCall,
) -> (Value, ToolResponse) {
    let parsed_args: Result<Value, _> = serde_json::from_str(&call.arguments);
    let args = match parsed_args {
        Ok(Value::Object(map)) => Value::Object(map),
        Ok(_) => json!({}),
        Err(error) => {
            return (
                json!({}),
                ToolResponse {
                    success: false,
                    output: String::new(),
                    error: format!(
                        "Malformed JSON arguments for tool {}: {}. Regenerate the tool call with valid JSON matching the schema.",
                        call.name, error
                    ),
                    duration_ms: 0.0,
                    metadata: json!({}),
                },
            )
        }
    };
    if let Some(blocked) =
        blocked_structured_csv_preflight_dependency_expansion(state, &call.name, &args)
    {
        return (args, blocked);
    }
    if let Some(blocked) = blocked_dna_primer_preflight_expansion(state, &call.name, &args) {
        return (args, blocked);
    }
    if let Some(blocked) = blocked_sparql_static_preflight_expansion(state, &call.name, &args) {
        return (args, blocked);
    }
    if let Some(blocked) =
        blocked_pytorch_distributed_preflight_dependency_expansion(state, &call.name, &args)
    {
        return (args, blocked);
    }
    if let Some(blocked) =
        blocked_cython_optional_import_dependency_expansion(state, &call.name, &args)
    {
        return (args, blocked);
    }
    if let Some(blocked) =
        blocked_static_deliverable_self_test_dependency_expansion(state, &call.name, &args)
    {
        return (args, blocked);
    }
    if let Some(blocked) = blocked_package_manager_recovery(&call.name, &args) {
        return (args, blocked);
    }
    if let Some(blocked) =
        blocked_dataset_shard_generalization_preflight_expansion(state, &call.name, &args)
    {
        return (args, blocked);
    }
    if let Some(blocked) = blocked_native_crash_preflight_expansion(state, &call.name, &args) {
        return (args, blocked);
    }
    if let Some(blocked) =
        blocked_regex_state_preflight_validation_expansion(state, &call.name, &args)
    {
        return (args, blocked);
    }
    if let Some(blocked) = blocked_repeated_timeout_path(state, &call.name, &args) {
        return (args, blocked);
    }
    if let Some(blocked) = blocked_repeated_dependency_failure_path(state, &call.name, &args) {
        return (args, blocked);
    }
    if let Some(blocked) =
        blocked_hazardous_dependency_artifact_first_replay(state, &call.name, &args)
    {
        return (args, blocked);
    }
    if let Some(blocked) = blocked_historical_dependency_loop_expansion(state, &call.name, &args) {
        return (args, blocked);
    }
    if let Some(blocked) = blocked_post_dependency_checkpoint_expansion(state, &call.name, &args) {
        return (args, blocked);
    }
    if let Some(blocked) = blocked_broad_system_find(&call.name, &args) {
        return (args, blocked);
    }
    if let Some(blocked) = blocked_verifier_artifact_search(&call.name, &args) {
        return (args, blocked);
    }
    if let Some(blocked) = blocked_host_memory_search(&call.name, &args) {
        return (args, blocked);
    }
    send_event(&json!({
        "type": "tool_request",
        "id": call.id,
        "tool": call.name,
        "args": args,
    }));
    match read_typed_response::<ToolResponse>(stdin, "tool_response") {
        Ok(result) => (args, result),
        Err(error) => (
            args,
            ToolResponse {
                success: false,
                output: String::new(),
                error: error,
                duration_ms: 0.0,
                metadata: json!({}),
            },
        ),
    }
}

type RepeatedTimeoutReasonFn = fn(&str) -> Option<(&'static str, &'static str)>;
type RepeatedTimeoutMatcher =
    fn(&WorkerState, &str, &RepeatedTimeoutSpec) -> Option<RepeatedTimeoutMatch>;

struct RepeatedTimeoutSpec {
    semantic_failure_kind: &'static str,
    label: &'static str,
    timeout_context: &'static str,
    phase_names: &'static [&'static str],
    count_metadata_key: &'static str,
    reason_fn: Option<RepeatedTimeoutReasonFn>,
    matcher: RepeatedTimeoutMatcher,
    suffix: &'static str,
    requires_generated_solver_recovery_probe: bool,
}

struct RepeatedTimeoutMatch {
    reason: &'static str,
    recovery_detail: &'static str,
    timeout_count: usize,
}

