fn pytorch_distributed_preflight_expansion_reason(
    command: &str,
) -> Option<(&'static str, &'static str)> {
    if command_looks_like_pytorch_torchrun_probe(command) {
        return Some((
            "pytorch_distributed_preflight_pending_torchrun_probe",
            "Do not replace the verifier's mp.spawn contract with torchrun or torch.distributed.run; mirror the mp.spawn process boundary locally first.",
        ));
    }
    if command_looks_like_dependency_setup_action(command) {
        return Some((
            "pytorch_distributed_preflight_pending_dependency_setup",
            "Do not install torch, uv environments, Python packages, or compiler/toolchain dependencies before the current deliverable has a focused local spawn checker.",
        ));
    }
    if command_looks_like_pytorch_cache_or_verifier_hunt(command)
        || command_looks_like_package_cache_search(command)
        || broad_system_find_command(command)
    {
        return Some((
            "pytorch_distributed_preflight_pending_cache_or_verifier_hunt",
            "Do not inspect /tmp/hl-verifier-cache, broad filesystem roots, package caches, or hidden verifier runtimes while the local rank/world_size checker is missing.",
        ));
    }
    if command_looks_like_manual_dependency_download(command) {
        return Some((
            "pytorch_distributed_preflight_pending_manual_dependency_download",
            "Do not chase PyTorch wheels, PyPI, download.pytorch.org, GitHub archives, or manual package downloads before the focused spawn checker exists and passes.",
        ));
    }
    if command_looks_like_tool_binary_download(command) {
        return Some((
            "pytorch_distributed_preflight_pending_tool_binary_download",
            "Do not fetch a helper binary or runtime before proving the local distributed semantics with the existing task deliverable.",
        ));
    }
    if command_looks_like_broad_pytorch_validation(command) {
        return Some((
            "pytorch_distributed_preflight_pending_broad_validation",
            "Do not rerun broad verifier-style validation or open-ended distributed jobs before a tiny focused mp.spawn fixture passes.",
        ));
    }
    None
}

fn pytorch_distributed_preflight_allows_local_probe(command: &str) -> bool {
    let lowered = command.to_ascii_lowercase();
    text_names_pytorch_distributed_deliverable(&lowered)
        && !command_looks_like_dependency_setup_action(command)
        && !command_looks_like_pytorch_torchrun_probe(command)
        && !command_looks_like_pytorch_cache_or_verifier_hunt(command)
        && !command_looks_like_broad_pytorch_validation(command)
        && [
            "py_compile",
            "test -f",
            "test -s",
            "head ",
            "sed -n",
            "stat ",
            "wc -l",
            "python",
        ]
        .iter()
        .any(|needle| lowered.contains(needle))
}

fn command_looks_like_pytorch_torchrun_probe(command: &str) -> bool {
    let lowered = command.to_ascii_lowercase();
    lowered.contains("torchrun")
        || lowered.contains("torch.distributed.run")
        || lowered.contains("-m torch.distributed")
}

fn command_looks_like_pytorch_cache_or_verifier_hunt(command: &str) -> bool {
    let lowered = command.to_ascii_lowercase();
    looks_like_verifier_artifact_search(command)
        || lowered.contains("/tmp/hl-verifier-cache")
        || lowered.contains("find /")
            && (lowered.contains("torch")
                || lowered.contains("site-packages")
                || lowered.contains("python3.13"))
        || lowered.contains("find /tmp")
            && (lowered.contains("torch") || lowered.contains("uv-python"))
        || lowered.contains("find /root") && lowered.contains("torch")
        || lowered.contains("ls ") && lowered.contains("/tmp/hl-verifier-cache")
}

fn command_looks_like_broad_pytorch_validation(command: &str) -> bool {
    let lowered = command.to_ascii_lowercase();
    let names_distributed_test = lowered.contains("column_parallel")
        || lowered.contains("row_parallel")
        || lowered.contains("pipeline_parallel")
        || lowered.contains("/tests/test_outputs.py")
        || lowered.contains("test_outputs.py")
        || lowered.contains("/tests/");
    if !lowered.contains("torch")
        && !text_names_pytorch_distributed_deliverable(&lowered)
        && !names_distributed_test
    {
        return false;
    }
    let tokens = shell_tokens(&lowered);
    let broad_test = tokens
        .iter()
        .any(|token| matches!(token.as_str(), "pytest" | "py.test"))
        || lowered.contains("/tests/test_outputs.py")
        || lowered.contains("test_outputs.py")
        || lowered.contains("test_column_parallel_linear")
        || lowered.contains("test_row_parallel_linear")
        || lowered.contains("test_pipeline_parallel");
    broad_test && !is_pytorch_distributed_preflight_command("bash", &json!({"command": command}))
}

fn command_looks_like_sparql_runtime_cache_search(command: &str) -> bool {
    let lowered = command.to_ascii_lowercase();
    let tokens = shell_tokens(&lowered);
    let names_runtime = lowered.contains("rdflib")
        || lowered.contains("sparql")
        || lowered.contains("arq")
        || lowered.contains("roqet")
        || lowered.contains("jena")
        || lowered.contains("rapper")
        || lowered.contains("rdfproc")
        || lowered.contains("rdfpipe");
    if !names_runtime {
        return false;
    }
    command_looks_like_package_cache_search(command)
        || tokens.windows(2).any(|pair| {
            matches!(
                (pair[0].as_str(), pair[1].as_str()),
                ("which", _) | ("command", "-v") | ("whereis", _) | ("type", _)
            )
        })
        || lowered.contains("find /")
        || lowered.contains("locate ")
}

fn command_looks_like_sparql_runtime_probe(command: &str) -> bool {
    let lowered = command.to_ascii_lowercase();
    let runtime_probe = lowered.contains("import rdflib")
        || lowered.contains("from rdflib")
        || lowered.contains("graph().query")
        || lowered.contains("g.query(")
        || lowered.contains("python3 -c") && lowered.contains("rdflib")
        || lowered.contains("python -c") && lowered.contains("rdflib")
        || lowered.contains("arq ")
        || lowered.contains("roqet ")
        || lowered.contains("sparql --")
        || lowered.contains("riot ")
        || lowered.contains("rapper ")
        || lowered.contains("jena");
    runtime_probe
}

fn command_looks_like_primer_dependency_cache_search(command: &str) -> bool {
    let lowered = command.to_ascii_lowercase();
    let mentions_primer_tool = lowered.contains("primer3")
        || lowered.contains("oligotm")
        || lowered.contains("ntthal")
        || lowered.contains("perlprimer")
        || lowered.contains("libbio-primer");
    mentions_primer_tool
        && (lowered.contains("apt list")
            || lowered.contains("apt-cache search")
            || lowered.contains("apt search")
            || lowered.contains("dpkg -l")
            || lowered.contains("pip list")
            || lowered.contains("pip show"))
}

fn command_looks_like_primer_broad_system_search(command: &str) -> bool {
    let lowered = command.to_ascii_lowercase();
    broad_system_find_command(command)
        && (lowered.contains("primer3")
            || lowered.contains("oligotm")
            || lowered.contains("ntthal")
            || lowered.contains("primer"))
}

fn command_looks_like_broad_primer3_redesign(command: &str) -> bool {
    let lowered = command.to_ascii_lowercase();
    (lowered.contains("primer3_core") || lowered.contains("primer3 "))
        && !is_dna_primer_preflight_command("bash", &json!({"command": command}))
}

