fn povray_dimension_at_most(text: &str, prefix: &str, max_value: f64) -> bool {
    let mut offset = 0usize;
    while let Some(found) = text[offset..].find(prefix) {
        let absolute = offset + found + prefix.len();
        let digits: String = text[absolute..]
            .chars()
            .take_while(|ch| ch.is_ascii_digit() || *ch == '.')
            .collect();
        if numeric_token(digits.trim()).is_some_and(|value| value <= max_value) {
            return true;
        }
        offset = absolute;
    }
    false
}

fn command_has_tail_limit_at_most(tokens: &[String], max_value: f64) -> bool {
    tokens.windows(2).any(|pair| {
        pair[0] == "tail"
            && pair[1]
                .strip_prefix('-')
                .and_then(numeric_token)
                .is_some_and(|value| value <= max_value)
    })
}

