fn numeric_call_at_most(text: &str, marker: &str, max_value: f64) -> bool {
    let mut offset = 0;
    while let Some(found) = text[offset..].find(marker) {
        let start = offset + found + marker.len();
        let mut number = String::new();
        let mut saw_digit = false;
        for ch in text[start..].chars().take(80) {
            if ch.is_ascii_digit() || (saw_digit && ch == '.') {
                number.push(ch);
                saw_digit = true;
            } else if saw_digit {
                break;
            }
        }
        if !number.is_empty()
            && number
                .parse::<f64>()
                .ok()
                .is_some_and(|value| value <= max_value)
        {
            return true;
        }
        offset = start;
    }
    false
}

