fn timeout_phase_probe_matches_background_process_wait(command: &str) -> bool {
    let lowered = command.to_ascii_lowercase();
    let tokens = shell_tokens(&lowered);
    if command_looks_like_small_background_process_probe(&lowered, &tokens) {
        return false;
    }
    let process_table_poll = command_looks_like_process_table_poll(&lowered, &tokens);
    let background_operator = shell_has_background_operator(command);
    if command_invokes_python(&lowered) && !process_table_poll && !background_operator {
        return false;
    }
    if command_looks_like_package_management(command) && !process_table_poll {
        return false;
    }
    let has_shell_sleep = command_has_shell_sleep(&tokens, &lowered);
    let sleep_loop = has_shell_sleep
        && (lowered.contains("while")
            || lowered.contains("for ")
            || lowered.contains("$(seq")
            || lowered.contains("kill -0")
            || lowered.contains("wait ")
            || command_tails_or_cats_log(&lowered));
    let blind_wait = lowered.trim() == "wait"
        || lowered.trim().starts_with("wait;")
        || tokens.iter().any(|token| token == "wait") && lowered.contains("echo");
    let background_launch_then_wait = background_operator
        && (has_shell_sleep
            || tokens.iter().any(|token| token == "wait")
            || command_looks_like_process_table_poll(&lowered, &tokens)
            || command_tails_or_cats_log(&lowered));
    sleep_loop || process_table_poll || blind_wait || background_launch_then_wait
}

