fn assignment_number_at_most(text: &str, names: &[&str], max_value: f64) -> bool {
    names.iter().any(|name| {
        for separator in ["=", " = "] {
            let marker = format!("{name}{separator}");
            let mut offset = 0;
            while let Some(found) = text[offset..].find(&marker) {
                let start = offset + found + marker.len();
                let numeric = text[start..]
                    .trim_start()
                    .chars()
                    .take_while(|ch| ch.is_ascii_digit() || *ch == '.')
                    .collect::<String>();
                if !numeric.is_empty()
                    && numeric
                        .parse::<f64>()
                        .ok()
                        .is_some_and(|value| value <= max_value)
                {
                    return true;
                }
                offset = start;
            }
        }
        false
    })
}

