fn regex_rule_artifact_preflight_pending(state: &WorkerState) -> bool {
    let reference_turn = regex_rule_artifact_preflight_reference_turn(state);
    reference_turn > 0 && state.last_regex_rule_artifact_preflight_turn < reference_turn
}

fn regex_rule_artifact_preflight_reference_turn(state: &WorkerState) -> usize {
    state
        .regex_rule_artifact_touched_turn
        .max(regex_replacement_backreference_contract_preflight_required_turn(state))
}

fn regex_replacement_backreference_contract_preflight_required_turn(state: &WorkerState) -> usize {
    if regex_rule_artifact_preflight_contracts(state).is_empty() {
        0
    } else {
        1
    }
}

fn regex_replacement_backreference_contract_preflight_required(state: &WorkerState) -> bool {
    regex_replacement_backreference_contract_preflight_required_turn(state) > 0
}

fn regex_rule_artifact_preflight_message(state: &WorkerState) -> String {
    let contract_detail = regex_rule_artifact_preflight_contract_detail(state);
    let trigger = if state.regex_rule_artifact_touched_turn > 0 {
        format!(
            "/app/re.json was generated or modified on turn {}.",
            state.regex_rule_artifact_touched_turn
        )
    } else {
        "visible verifier/task evidence requires /app/re.json regex replacements to pass Python re.sub parse_template checks.".to_string()
    };
    format!(
        "Regex rule artifact preflight: {trigger} Before broad validation or a done call, create or repair /app/re.json if it is missing, then run one focused Python checker that loads json.load(open('/app/re.json')), asserts the loaded rule list is non-empty, iterates every (pattern, repl) pair, compiles each pattern, records pattern.groups and pattern.groupindex, explicitly parses every numeric and named replacement backreference into replacement_refs/numeric_refs/named_refs, rejects ambiguous_numeric_refs including ambiguous numeric backreferences such as \\10, and asserts every numeric ref satisfies 1 <= ref <= pattern.groups and every named ref exists in pattern.groupindex. Force Python replacement-template parsing with re._parser.parse_template(repl, pattern) or an equivalent parser-backed call, then also exercise pattern.sub(repl, focused_sample); pattern.sub alone is insufficient because a non-matching sample can skip replacement parsing. When literal suffixes are intended, rewrite ambiguous numeric references as \\g<1>0. Flag invalid references such as \\2 when the compiled pattern has fewer groups. {contract_detail}This is a semantic artifact preflight, not a loop stop condition, and is not driven by time, round, turn, token, max_turns, timeout, checkpoint count, cooldown, attempt count, cap, count, or budget metadata."
    )
}

fn regex_rule_artifact_preflight_gate_message(state: &WorkerState) -> String {
    let contract_detail = regex_rule_artifact_preflight_contract_detail(state);
    let trigger = if state.regex_rule_artifact_touched_turn > 0 {
        format!(
            "/app/re.json changed on turn {}",
            state.regex_rule_artifact_touched_turn
        )
    } else {
        "visible verifier/task evidence requires /app/re.json regex replacement validation"
            .to_string()
    };
    format!(
        "Regex rule artifact preflight completion gate: {trigger}, and no later focused regex-rule preflight has passed. Create or repair /app/re.json if it is missing, then run a bounded local checker using json.load(open('/app/re.json')) over every (pattern, repl), first asserting the loaded rule list is non-empty. The checker must compile the pattern, record pattern.groups and pattern.groupindex, parse replacement_refs into numeric_refs, named_refs, and ambiguous_numeric_refs, assert every numeric ref is within 1 <= ref <= pattern.groups, assert every named ref is in pattern.groupindex, reject ambiguous numeric backreferences such as \\10 unless rewritten as \\g<1>0, force replacement-template parsing with re._parser.parse_template(repl, pattern) or an equivalent parser-backed call, and then run pattern.sub(repl, focused_sample) before calling done again. Catch parse_template errors and invalid references such as \\2. {contract_detail}This gate is not a loop stop condition and is not driven by time, round, token, max_turns, timeout, checkpoint count, cooldown, attempt count, cap, count, or budget metadata."
    )
}

fn regex_rule_artifact_preflight_contract_detail(state: &WorkerState) -> String {
    let contracts = regex_rule_artifact_preflight_contracts(state);
    if contracts.is_empty() {
        return String::new();
    }
    format!(
        "Visible regex replacement/backreference contract(s): {}. Mirror the failing generated (pattern, repl) pair and exact replacement semantics in the checker before broad generated-solver validation. ",
        contracts
            .iter()
            .map(|contract| truncate(contract, 700))
            .collect::<Vec<_>>()
            .join(" | ")
    )
}

fn regex_rule_artifact_preflight_contracts(state: &WorkerState) -> Vec<String> {
    let mut contracts = Vec::new();
    let mut seen = HashSet::new();
    let mut sources =
        collect_task_context_evidence(&state.task_instruction, &state.task_context, 8);
    if !state.memory_failure_summary_lines.is_empty() {
        sources.push(state.memory_failure_summary_lines.join("\n"));
    }
    if let Some(observation) = state.unresolved_failed_verification.as_ref() {
        sources.push(observation.observation.clone());
        sources.extend(observation.semantic_contracts.clone());
    }
    if let Some(observation) = state.unresolved_local_semantic_failure.as_ref() {
        sources.push(observation.observation.clone());
        sources.extend(observation.semantic_contracts.clone());
    }

    for source in sources {
        for contract in regex_rule_artifact_preflight_contracts_from_text(&source) {
            push_semantic_contract(&mut contracts, &mut seen, contract);
        }
        if contracts.len() >= 2 {
            break;
        }
    }
    contracts
}

fn regex_rule_artifact_preflight_contracts_from_text(text: &str) -> Vec<String> {
    let mut contracts = Vec::new();
    let mut seen = HashSet::new();
    for line in text.lines() {
        let cleaned = verifier_contract_line(line);
        if cleaned.starts_with("regex_replacement_backreference_contract:") {
            push_semantic_contract(&mut contracts, &mut seen, cleaned);
        }
    }
    if !contracts.is_empty() {
        return contracts;
    }
    for contract in live_verifier_semantic_contracts(text)
        .into_iter()
        .filter(|contract| contract.starts_with("regex_replacement_backreference_contract:"))
    {
        push_semantic_contract(&mut contracts, &mut seen, contract);
    }
    if contracts.is_empty()
        && text
            .to_ascii_lowercase()
            .contains("regex_replacement_backreference_contract")
    {
        push_semantic_contract(
            &mut contracts,
            &mut seen,
            format!(
                "regex_replacement_backreference_contract: Python re.sub replacement strings must only reference groups present in the compiled pattern; prior same-task memory named this verifier contract, so audit every generated (pattern, repl) pair, count pattern.groups and pattern.groupindex, force replacement-template parsing, and rewrite ambiguous numeric references such as \\10 as \\g<1>0 before broad validation ({})",
                truncate(text, 320)
            ),
        );
    }
    contracts
}

fn maybe_inject_regex_rule_artifact_preflight_checkpoint(state: &mut WorkerState) -> bool {
    if !regex_rule_artifact_preflight_pending(state) {
        return false;
    }
    let reference_turn = regex_rule_artifact_preflight_reference_turn(state);
    if state.last_regex_rule_artifact_preflight_checkpoint_turn >= reference_turn {
        return false;
    }
    let message = regex_rule_artifact_preflight_message(state);
    let regex_contracts = regex_rule_artifact_preflight_contracts(state);
    state.append_user_message(message);
    state.append_trajectory(json!({
        "type": "regex_rule_artifact_preflight_checkpoint",
        "turn": state.turn_count,
        "regex_rule_artifact_touched_turn": state.regex_rule_artifact_touched_turn,
        "regex_rule_artifact_preflight_reference_turn": reference_turn,
        "last_regex_rule_artifact_preflight_turn": state.last_regex_rule_artifact_preflight_turn,
        "regex_replacement_backreference_contracts": regex_contracts,
        "regex_replacement_backreference_contracts_stop_condition": false,
        "regex_replacement_backreference_contract_preflight_required": regex_replacement_backreference_contract_preflight_required(state),
        "regex_replacement_backreference_contract_preflight_stop_condition": false,
        "loop_stop_condition": false,
        "time_round_token_limit_driven": false,
        "max_turns_stop_condition": false,
        "timeout_seconds_stop_condition": false,
        "round_limit_stop_condition": false,
        "checkpoint_count_stop_condition": false,
        "checkpoint_cooldown_stop_condition": false,
        "attempt_count_stop_condition": false,
        "budget_stop_condition": false,
    }));
    state.last_regex_rule_artifact_preflight_checkpoint_turn = state.turn_count;
    true
}

