fn sparql_static_preflight_pending(state: &WorkerState) -> bool {
    let reference_turn = sparql_static_preflight_reference_turn(state);
    reference_turn > 0 && state.last_sparql_static_preflight_turn < reference_turn
}

fn sparql_static_preflight_reference_turn(state: &WorkerState) -> usize {
    state
        .sparql_static_artifact_touched_turn
        .max(sparql_static_preflight_required_turn(state))
}

fn sparql_static_preflight_required_turn(state: &WorkerState) -> usize {
    if state.sparql_static_preflight_required
        || !sparql_static_preflight_contracts(state).is_empty()
    {
        1
    } else {
        0
    }
}

fn sparql_static_artifact_display_path(state: &WorkerState) -> String {
    if state.sparql_static_artifact_path.trim().is_empty() {
        "/app/solution.sparql".to_string()
    } else {
        state.sparql_static_artifact_path.clone()
    }
}

fn sparql_static_preflight_message(state: &WorkerState) -> String {
    let path = sparql_static_artifact_display_path(state);
    let trigger = if state.sparql_static_artifact_touched_turn > 0 {
        format!(
            "{path} was generated or modified on turn {}.",
            state.sparql_static_artifact_touched_turn
        )
    } else {
        "visible task or verifier evidence requires a static /app/solution.sparql query deliverable."
            .to_string()
    };
    let contract_detail = sparql_static_preflight_contract_detail(state);
    format!(
        "SPARQL static deliverable preflight: {trigger} Before RDFLib/arq/roqet/runtime setup or a done call, run one focused local checker over /app/solution.sparql. Assert the file is non-empty, contains SELECT and WHERE, has balanced braces, declares or uses expected prefixes, projects the visible output variables, and when the result-set contract mentions multi-value fields such as countries, uses GROUP_CONCAT(DISTINCT ...) with GROUP BY so one entity row aggregates all related values. {contract_detail}This is a semantic artifact preflight, not a master, sub-agent, or Worker loop stop condition, and is not driven by time, round, turn, token, max_turns, timeout, checkpoint count, cooldown, attempt count, cap, count, or budget metadata."
    )
}

