fn token_substitution_preflight_pending(state: &WorkerState) -> bool {
    let reference_turn = token_substitution_preflight_reference_turn(state);
    reference_turn > 0 && state.last_token_substitution_preflight_turn < reference_turn
}

fn token_substitution_preflight_reference_turn(state: &WorkerState) -> usize {
    state
        .token_substitution_artifact_touched_turn
        .max(token_substitution_preflight_required_turn(state))
}

fn token_substitution_preflight_required_turn(state: &WorkerState) -> usize {
    if state.token_substitution_preflight_required
        || !token_substitution_preflight_contracts(state).is_empty()
    {
        1
    } else {
        0
    }
}

fn token_substitution_preflight_message(state: &WorkerState) -> String {
    let contract_detail = token_substitution_preflight_contract_detail(state);
    let trigger = if state.token_substitution_artifact_touched_turn > 0 {
        format!(
            "/app/input.tex was generated or modified on turn {}.",
            state.token_substitution_artifact_touched_turn
        )
    } else {
        "visible verifier/task evidence requires input.tex edits to preserve synonyms.txt token-substitution families."
            .to_string()
    };
    format!(
        "Token-substitution preflight: {trigger} Before broad LaTeX validation or a done call, run one focused Python checker that parses synonyms.txt into synonym families, reads original /tests/input.tex and edited /app/input.tex, normalizes em-dashes the same way on both sides, tokenizes with re.findall(r'\\S+'), asserts equal token count, compares prefix/suffix punctuation exactly, and asserts every changed word is in the same synonym family as the original. Print or raise on the first mismatch so illegal substitutions such as Middle -> Hub are caught locally. {contract_detail}This is a semantic artifact preflight, not a master, sub-agent, or Worker loop stop condition, and is not driven by time, round, turn, token, max_turns, timeout, checkpoint count, cooldown, attempt count, cap, count, or budget metadata."
    )
}

fn token_substitution_preflight_gate_message(state: &WorkerState) -> String {
    let contract_detail = token_substitution_preflight_contract_detail(state);
    let trigger = if state.token_substitution_artifact_touched_turn > 0 {
        format!(
            "/app/input.tex changed on turn {}",
            state.token_substitution_artifact_touched_turn
        )
    } else {
        "visible verifier/task evidence requires input.tex token-substitution validation"
            .to_string()
    };
    format!(
        "Token-substitution preflight completion gate: {trigger}, and no later focused synonym-family checker has passed. Run a bounded local checker that loads synonyms.txt, compares /tests/input.tex against /app/input.tex token-by-token, preserves token count and punctuation, and allows only unchanged words or replacements from the same synonym family before calling done again. {contract_detail}This gate is not a master, sub-agent, or Worker loop stop condition and is not driven by time, round, token, max_turns, timeout, checkpoint count, cooldown, attempt count, cap, count, or budget metadata."
    )
}

fn token_substitution_preflight_contract_detail(state: &WorkerState) -> String {
    let contracts = token_substitution_preflight_contracts(state);
    if contracts.is_empty() {
        return String::new();
    }
    format!(
        "Visible token-substitution contract(s): {}. Mirror the verifier's same-family membership, token count, and punctuation checks before relying on pdflatex or grep Overfull. ",
        contracts
            .iter()
            .map(|contract| truncate(contract, 700))
            .collect::<Vec<_>>()
            .join(" | ")
    )
}

fn token_substitution_preflight_contracts(state: &WorkerState) -> Vec<String> {
    let mut contracts = Vec::new();
    let mut seen = HashSet::new();
    let mut sources =
        collect_task_context_evidence(&state.task_instruction, &state.task_context, 8);
    if let Some(observation) = state.unresolved_failed_verification.as_ref() {
        sources.push(observation.observation.clone());
        sources.extend(observation.semantic_contracts.clone());
    }
    if let Some(observation) = state.unresolved_local_semantic_failure.as_ref() {
        sources.push(observation.observation.clone());
        sources.extend(observation.semantic_contracts.clone());
    }

    for source in sources {
        for contract in token_substitution_contracts_from_text(&source) {
            push_semantic_contract(&mut contracts, &mut seen, contract);
        }
        if contracts.len() >= 2 {
            break;
        }
    }
    contracts
}

fn token_substitution_contracts_from_text(text: &str) -> Vec<String> {
    let mut contracts = Vec::new();
    let mut seen = HashSet::new();
    for line in text.lines() {
        let cleaned = verifier_contract_line(line);
        if cleaned.starts_with("token_substitution_contract:") {
            push_semantic_contract(&mut contracts, &mut seen, cleaned);
        }
    }
    for contract in live_verifier_semantic_contracts(text)
        .into_iter()
        .filter(|contract| contract.starts_with("token_substitution_contract:"))
    {
        push_semantic_contract(&mut contracts, &mut seen, contract);
    }
    contracts
}

fn maybe_inject_token_substitution_preflight_checkpoint(state: &mut WorkerState) -> bool {
    if !token_substitution_preflight_pending(state) {
        return false;
    }
    let reference_turn = token_substitution_preflight_reference_turn(state);
    if state.last_token_substitution_preflight_checkpoint_turn >= reference_turn {
        return false;
    }
    let message = token_substitution_preflight_message(state);
    let token_substitution_contracts = token_substitution_preflight_contracts(state);
    state.append_user_message(message);
    state.append_trajectory(json!({
        "type": "token_substitution_preflight_checkpoint",
        "turn": state.turn_count,
        "token_substitution_artifact_touched_turn": state.token_substitution_artifact_touched_turn,
        "token_substitution_preflight_reference_turn": reference_turn,
        "last_token_substitution_preflight_turn": state.last_token_substitution_preflight_turn,
        "token_substitution_preflight_required": state.token_substitution_preflight_required,
        "token_substitution_contracts": token_substitution_contracts,
        "token_substitution_contracts_stop_condition": false,
        "token_substitution_preflight_stop_condition": false,
        "loop_stop_condition": false,
        "time_round_token_limit_driven": false,
        "max_turns_stop_condition": false,
        "timeout_seconds_stop_condition": false,
        "round_limit_stop_condition": false,
        "checkpoint_count_stop_condition": false,
        "checkpoint_cooldown_stop_condition": false,
        "attempt_count_stop_condition": false,
        "budget_stop_condition": false,
    }));
    state.last_token_substitution_preflight_checkpoint_turn = state.turn_count;
    true
}

