fn record_exact_output_readback_artifact_progress(
    state: &mut WorkerState,
    tool_name: &str,
    args: &Value,
    result: &ToolResponse,
) {
    if state.exact_output_readback_targets.is_empty()
        || is_exact_output_readback_preflight_command_for_any_target(state, tool_name, args)
    {
        return;
    }
    let evidence = exact_output_artifact_touch_evidence(tool_name, args, result);
    if evidence.is_empty() {
        return;
    }
    let mut touched_paths = Vec::new();
    for target in &state.exact_output_readback_targets {
        let basename = Path::new(&target.path)
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or(&target.path);
        if evidence
            .iter()
            .any(|text| text.contains(&target.path) || text.contains(basename))
        {
            state
                .exact_output_readback_touched_turns
                .insert(target.path.clone(), state.turn_count);
            touched_paths.push(target.path.clone());
        }
    }
    if touched_paths.is_empty() {
        return;
    }
    state.append_trajectory(json!({
        "type": "exact_output_readback_artifact_touched",
        "turn": state.turn_count,
        "tool": tool_name,
        "command": truncate(args.get("command").and_then(Value::as_str).unwrap_or(""), 1000),
        "file_path": args.get("file_path").and_then(Value::as_str).unwrap_or(""),
        "output_paths": touched_paths,
        "loop_stop_condition": false,
        "time_round_token_limit_driven": false,
        "max_turns_stop_condition": false,
        "timeout_seconds_stop_condition": false,
        "round_limit_stop_condition": false,
        "exact_output_readback_stop_condition": false,
    }));
}

fn exact_output_artifact_touch_evidence(
    tool_name: &str,
    args: &Value,
    result: &ToolResponse,
) -> Vec<String> {
    let mut evidence = Vec::new();
    if tool_name == "write" || tool_name == "edit" {
        if let Some(file_path) = args.get("file_path").and_then(Value::as_str) {
            evidence.push(file_path.to_string());
        }
        return evidence;
    }
    if tool_name != "bash" {
        return evidence;
    }
    let command = args.get("command").and_then(Value::as_str).unwrap_or("");
    if command_likely_mutates_workspace(command)
        || artifact_context_mentions_write_or_change(&command.to_ascii_lowercase())
    {
        evidence.push(command.to_string());
        evidence.push(result.output.to_string());
    }
    evidence
}

fn record_successful_exact_output_readback_preflight(
    state: &mut WorkerState,
    tool_name: &str,
    args: &Value,
) {
    let Some(target) = exact_output_readback_preflight_target(state, tool_name, args).cloned()
    else {
        return;
    };
    state
        .exact_output_readback_preflight_turns
        .insert(target.path.clone(), state.turn_count);
    state.append_trajectory(json!({
        "type": "exact_output_readback_preflight_passed",
        "turn": state.turn_count,
        "tool": tool_name,
        "command": truncate(args.get("command").and_then(Value::as_str).unwrap_or(""), 1000),
        "output_path": target.path,
        "readback_kind": exact_output_readback_kind_name(&target.kind),
        "expected_literal": target.expected_literal,
        "expected_tokens": target.expected_tokens,
        "output_touched_turn": exact_output_readback_touched_turn(state, &target.path),
        "loop_stop_condition": false,
        "time_round_token_limit_driven": false,
        "max_turns_stop_condition": false,
        "timeout_seconds_stop_condition": false,
        "round_limit_stop_condition": false,
        "exact_output_readback_stop_condition": false,
    }));
}

fn exact_output_readback_preflight_pending_target(
    state: &WorkerState,
) -> Option<&ExactOutputReadbackTarget> {
    state.exact_output_readback_targets.iter().find(|target| {
        let touched_turn = exact_output_readback_touched_turn(state, &target.path);
        touched_turn > 0 && exact_output_readback_preflight_turn(state, &target.path) < touched_turn
    })
}

fn exact_output_readback_touched_turn(state: &WorkerState, path: &str) -> usize {
    state
        .exact_output_readback_touched_turns
        .get(path)
        .copied()
        .unwrap_or(0)
}

fn exact_output_readback_preflight_turn(state: &WorkerState, path: &str) -> usize {
    state
        .exact_output_readback_preflight_turns
        .get(path)
        .copied()
        .unwrap_or(0)
}

fn exact_output_readback_kind_name(kind: &ExactOutputReadbackKind) -> &'static str {
    match kind {
        ExactOutputReadbackKind::Literal => "literal",
        ExactOutputReadbackKind::Tokenized { .. } => "tokenized",
    }
}

fn exact_output_readback_preflight_message(
    target: &ExactOutputReadbackTarget,
    state: &WorkerState,
) -> String {
    let touched_turn = exact_output_readback_touched_turn(state, &target.path);
    match &target.kind {
        ExactOutputReadbackKind::Literal => {
            let expected = target.expected_literal.as_deref().unwrap_or("");
            format!(
                "Exact output readback preflight: {path} was generated or modified on turn {touched_turn}, and verifier evidence reads it with Path(...).read_text() against expected_output {expected}. Before broad validation or a done call, run one focused Python checker that reads Path({path_literal}).read_text(), applies the verifier-compatible strip/trailing-newline behavior, and asserts the exact literal equals {expected}. This is a semantic artifact preflight, not a loop stop condition, and is not driven by time, round, turn, token, max_turns, timeout, checkpoint count, cooldown, or budget metadata.",
                path = target.path,
                path_literal = quoted_contract_literal(&target.path),
                expected = quoted_contract_literal(expected),
            )
        }
        ExactOutputReadbackKind::Tokenized { order_insensitive } => {
            let token_detail = exact_output_readback_token_detail(target);
            let ordering = if *order_insensitive {
                "sorted token comparison or set-style ordering"
            } else {
                "the verifier's token order"
            };
            format!(
                "Exact tokenized output readback preflight: {path} was generated or modified on turn {touched_turn}, and verifier evidence reads it with Path(...).read_text().strip().split() against expected tokens [{token_detail}]. Before broad validation or a done call, run one focused Python checker that reads Path({path_literal}).read_text().strip().split(), compares every token boundary using {ordering}, checks duplicates when present, and prints visible expected-vs-actual tokens. This is a semantic artifact preflight, not a loop stop condition, and is not driven by time, round, turn, token, max_turns, timeout, checkpoint count, cooldown, or budget metadata.",
                path = target.path,
                path_literal = quoted_contract_literal(&target.path),
            )
        }
    }
}

fn exact_output_readback_preflight_gate_message(
    target: &ExactOutputReadbackTarget,
    state: &WorkerState,
) -> String {
    let touched_turn = exact_output_readback_touched_turn(state, &target.path);
    match &target.kind {
        ExactOutputReadbackKind::Literal => {
            let expected = target.expected_literal.as_deref().unwrap_or("");
            format!(
                "Exact output readback preflight completion gate: {path} changed on turn {touched_turn} and no later focused readback preflight has passed. Run a bounded local checker using Path({path_literal}).read_text() and assert the exact expected_output literal {expected}, including verifier-compatible strip/trailing-newline behavior, before calling done again. This gate is not a loop stop condition and is not driven by time, round, token, max_turns, timeout, checkpoint count, cooldown, or budget metadata.",
                path = target.path,
                path_literal = quoted_contract_literal(&target.path),
                expected = quoted_contract_literal(expected),
            )
        }
        ExactOutputReadbackKind::Tokenized { order_insensitive } => {
            let token_detail = exact_output_readback_token_detail(target);
            let ordering = if *order_insensitive {
                "sorted/set-equivalent token comparison"
            } else {
                "ordered token comparison"
            };
            format!(
                "Exact tokenized output readback preflight completion gate: {path} changed on turn {touched_turn} and no later focused token readback preflight has passed. Run a bounded local checker using Path({path_literal}).read_text().strip().split(), compare tokens [{token_detail}] with {ordering}, and print expected-vs-actual token evidence before calling done again. This gate is not a loop stop condition and is not driven by time, round, token, max_turns, timeout, checkpoint count, cooldown, or budget metadata.",
                path = target.path,
                path_literal = quoted_contract_literal(&target.path),
            )
        }
    }
}

fn exact_output_readback_token_detail(target: &ExactOutputReadbackTarget) -> String {
    if target.expected_tokens.is_empty() {
        "verifier-visible expected tokens".to_string()
    } else {
        target.expected_tokens.join(" ")
    }
}

fn maybe_inject_exact_output_readback_preflight_checkpoint(state: &mut WorkerState) -> bool {
    let Some(target) = exact_output_readback_preflight_pending_target(state).cloned() else {
        return false;
    };
    let touched_turn = exact_output_readback_touched_turn(state, &target.path);
    let last_checkpoint = state
        .exact_output_readback_checkpoint_turns
        .get(&target.path)
        .copied()
        .unwrap_or(0);
    if last_checkpoint >= touched_turn {
        return false;
    }
    let message = exact_output_readback_preflight_message(&target, state);
    state.append_user_message(message);
    state.append_trajectory(json!({
        "type": "exact_output_readback_preflight_checkpoint",
        "turn": state.turn_count,
        "output_path": target.path,
        "readback_kind": exact_output_readback_kind_name(&target.kind),
        "expected_literal": target.expected_literal,
        "expected_tokens": target.expected_tokens,
        "output_touched_turn": touched_turn,
        "last_exact_output_readback_preflight_turn": exact_output_readback_preflight_turn(state, &target.path),
        "loop_stop_condition": false,
        "time_round_token_limit_driven": false,
        "max_turns_stop_condition": false,
        "timeout_seconds_stop_condition": false,
        "round_limit_stop_condition": false,
        "checkpoint_count_stop_condition": false,
        "checkpoint_cooldown_stop_condition": false,
        "exact_output_readback_stop_condition": false,
    }));
    state
        .exact_output_readback_checkpoint_turns
        .insert(target.path, state.turn_count);
    true
}

