fn html_filter_alert_bypass_preflight_contract_detail(state: &WorkerState) -> String {
    let contracts = html_filter_alert_bypass_preflight_contracts(state);
    if contracts.is_empty() {
        return String::new();
    }
    format!(
        "Visible HTML filter alert-bypass contract(s): {}. Mirror the verifier's filtered-temp-copy browser alert check instead of only inspecting raw HTML. ",
        contracts
            .iter()
            .map(|contract| truncate(contract, 700))
            .collect::<Vec<_>>()
            .join(" | ")
    )
}

fn html_filter_alert_bypass_preflight_sources(state: &WorkerState) -> Vec<String> {
    let mut sources =
        collect_task_context_evidence(&state.task_instruction, &state.task_context, 8);
    if let Some(observation) = state.unresolved_failed_verification.as_ref() {
        sources.push(observation.observation.clone());
        sources.extend(observation.semantic_contracts.clone());
    }
    if let Some(observation) = state.unresolved_local_semantic_failure.as_ref() {
        sources.push(observation.observation.clone());
        sources.extend(observation.semantic_contracts.clone());
    }
    sources
}

fn html_filter_alert_bypass_preflight_contracts(state: &WorkerState) -> Vec<String> {
    let mut contracts = Vec::new();
    let mut seen = HashSet::new();
    for source in html_filter_alert_bypass_preflight_sources(state) {
        for contract in html_filter_alert_bypass_contracts_from_text(&source) {
            push_semantic_contract(&mut contracts, &mut seen, contract);
        }
        if contracts.len() >= 2 {
            break;
        }
    }
    contracts
}

fn html_filter_alert_bypass_contracts_from_text(text: &str) -> Vec<String> {
    let mut contracts = Vec::new();
    let mut seen = HashSet::new();
    for line in text.lines() {
        let cleaned = verifier_contract_line(line);
        if cleaned.starts_with("html_filter_alert_bypass_contract:") {
            push_semantic_contract(&mut contracts, &mut seen, cleaned);
        }
    }
    for contract in live_verifier_semantic_contracts(text)
        .into_iter()
        .filter(|contract| contract.starts_with("html_filter_alert_bypass_contract:"))
    {
        push_semantic_contract(&mut contracts, &mut seen, contract);
    }
    contracts
}

