fn spectral_peak_fit_preflight_required_turn(state: &WorkerState) -> usize {
    if state.spectral_peak_fit_preflight_required
        || !spectral_peak_fit_preflight_contracts(state).is_empty()
    {
        1
    } else {
        0
    }
}

