fn structured_numeric_output_artifact_path(text: &str) -> Option<String> {
    structured_numeric_output_path_from_text(text)
}

fn structured_numeric_output_contracts_from_text(text: &str) -> Vec<String> {
    let mut contracts = Vec::new();
    let mut seen = HashSet::new();
    for line in text.lines() {
        let cleaned = verifier_contract_line(line);
        for marker in [
            "structured_output_schema_contract:",
            "numeric_interval_contract:",
        ] {
            if let Some(contract) = embedded_structured_numeric_contract(&cleaned, marker) {
                push_semantic_contract(&mut contracts, &mut seen, contract);
            }
        }
    }
    for contract in live_verifier_semantic_contracts(text)
        .into_iter()
        .filter(|contract| {
            contract.starts_with("structured_output_schema_contract:")
                || contract.starts_with("numeric_interval_contract:")
        })
    {
        push_semantic_contract(&mut contracts, &mut seen, contract);
    }
    contracts
}

fn embedded_structured_numeric_contract(text: &str, marker: &str) -> Option<String> {
    let start = text.find(marker)?;
    let tail = &text[start..];
    let mut end = tail.len();
    for other_marker in [
        "structured_output_schema_contract:",
        "numeric_interval_contract:",
    ] {
        if other_marker == marker {
            continue;
        }
        if let Some(offset) = tail[marker.len()..].find(other_marker) {
            end = end.min(marker.len() + offset);
        }
    }
    let contract = tail[..end]
        .trim()
        .trim_end_matches(|ch: char| matches!(ch, '.' | ';' | ','))
        .to_string();
    (!contract.is_empty()).then_some(contract)
}

