fn looks_like_text_output_contract_failure(lowered: &str) -> bool {
    if lowered.contains("text_output_contract") {
        return true;
    }
    let mentions_utf8_decode_failure = lowered.contains("unicodedecodeerror")
        || lowered.contains("utf-8 codec") && lowered.contains("decode byte")
        || lowered.contains("can't decode byte")
        || lowered.contains("unexpected end of data") && lowered.contains("utf-8");
    if !mentions_utf8_decode_failure {
        return false;
    }
    lowered.contains("subprocess.run")
        || lowered.contains("text=true")
        || lowered.contains("capture_output=true")
        || lowered.contains("_translate_newlines")
        || lowered.contains("data.decode(encoding, errors)")
        || lowered.contains("stdout")
}

fn gpt2_codegolf_text_contract(text: &str) -> Option<String> {
    let lowered = text.to_ascii_lowercase();
    if !looks_like_gpt2_codegolf_text_contract_failure(&lowered) {
        return None;
    }
    Some(format!(
        "gpt2_codegolf_text_contract: /app/gpt2.c must stay under 5000 bytes, compile with gcc -O3 /app/gpt2.c -lm, and when run as /app/a.out gpt2-124M.ckpt vocab.bpe 'THIS SOFTWARE IS PROVIDED \"AS IS\", WITHOUT' stdout must contain 'WARRANTY OF ANY KIND, EXPRESS OR IMPLIED'; emit valid UTF-8 text and avoid repeated token ids, escaped binary garbage, or prompt-only output ({})",
        truncate(text, 300)
    ))
}

fn caffe_cifar10_artifact_contract(text: &str) -> Option<String> {
    let normalized;
    let source = if text.contains("\\n") {
        normalized = normalize_escaped_trace_text(text);
        normalized.as_str()
    } else {
        text
    };
    if !looks_like_caffe_cifar10_artifact_failure(&source.to_ascii_lowercase()) {
        return None;
    }
    Some(format!(
        "caffe_cifar10_artifact_contract: verifier expects BVLC Caffe 1.0 CPU-only CIFAR-10 quick training artifacts: /app/caffe/.build_release/tools/caffe.bin must execute --version, examples/cifar10/cifar10_quick_solver.prototxt must be CPU-mode compatible, and examples/cifar10/cifar10_quick_iter_500.caffemodel must be a real trained model artifact; check these exact paths/configs before broad apt/pip/toolchain expansion ({})",
        truncate(source, 360)
    ))
}

fn looks_like_adaptive_rejection_sampler_contract_failure(lowered: &str) -> bool {
    let mentions_ars_artifact = lowered.contains("ars.r")
        || lowered.contains("adaptive-rejection-sampler")
        || lowered.contains("adaptive rejection sampler")
        || lowered.contains("adaptive rejection");
    let mentions_sampler_test_summary = lowered
        .contains("test_can_generate_standard_distribution_samples")
        && (lowered.contains("failed to generate valid normal samples")
            || lowered.contains("log_density_prime")
            || lowered.contains("single numeric value")
            || lowered.contains("numeric scalars"));
    let mentions_sampler_call = lowered.contains("ars(")
        || lowered.contains("normal_density")
        || lowered.contains("dnorm")
        || lowered.contains("test_can_generate_standard_distribution_samples")
        || lowered.contains("test_normal_sampler.r");
    let mentions_api_mismatch = lowered.contains("log_density_prime")
        || lowered.contains("'lower' must be a single numeric value")
        || lowered.contains("\"lower\" must be a single numeric value")
        || lowered.contains("'lb' and 'ub' must be numeric scalars")
        || lowered.contains("'lb' must be a single numeric value")
        || lowered.contains("'ub' must be a single numeric value")
        || lowered.contains("c(-5, 5)")
        || lowered.contains("c(-5,5)")
        || lowered.contains("failed to generate valid normal samples")
        || lowered.contains("insufficient samples generated")
        || lowered.contains("mean or std out of range");
    (mentions_ars_artifact || mentions_sampler_test_summary)
        && mentions_sampler_call
        && mentions_api_mismatch
}

fn adaptive_rejection_sampler_contract(text: &str) -> Option<String> {
    let normalized;
    let source = if text.contains("\\n") {
        normalized = normalize_escaped_trace_text(text);
        normalized.as_str()
    } else {
        text
    };
    let lowered = source.to_ascii_lowercase();
    if !looks_like_adaptive_rejection_sampler_contract_failure(&lowered) {
        return None;
    }
    Some(format!(
        "adaptive_rejection_sampler_contract: /app/ars.R must expose ars(density_or_log_density, bounds, n=..., log_density_prime=NULL) compatible with verifier call samples <- ars(normal_density, c(-5, 5), n = 1000); accept a density function like normal_density <- function(x) dnorm(x, mean = 0, sd = 1), not only a log-density derivative signature; treat bounds vector c(lower, upper) as two numeric bounds instead of scalar-only lower/lb/ub arguments; return a numeric vector near requested n with standard-normal fixture length>=900, abs(mean)<0.2, and 0.8<sd<1.2; preserve any required test(n, alpha) wrapper and validate with a tiny local Rscript fixture before full sampling ({})",
        truncate(source, 320)
    ))
}

fn deliverable_size_cap_contract(text: &str) -> Option<String> {
    let evidence = deliverable_size_cap_evidence_from_text(text)?;
    Some(format!(
        "deliverable_size_cap_contract: {} must stay under {} bytes; current observed size={} bytes; preserve required behavior while shrinking/removing debug tables, generated data, unused helpers, comments, and broad fallback code ({})",
        evidence.path,
        evidence.limit_bytes,
        evidence.observed_bytes
            .map(|value| value.to_string())
            .unwrap_or_else(|| "unknown".to_string()),
        truncate(&evidence.excerpt, 220)
    ))
}

#[derive(Clone, Debug)]
struct DeliverableSizeCapEvidence {
    path: String,
    limit_bytes: u64,
    observed_bytes: Option<u64>,
    excerpt: String,
    source_turn: usize,
}

fn maybe_inject_deliverable_size_cap_checkpoint(state: &mut WorkerState) -> bool {
    if state.deliverable_size_cap_checkpoint_injected {
        return false;
    }
    let Some(evidence) = deliverable_size_cap_evidence(state) else {
        return false;
    };
    if evidence.observed_bytes.is_none() {
        return false;
    }
    let observed = evidence
        .observed_bytes
        .map(|value| format!("Observed size: {value} bytes. "))
        .unwrap_or_default();
    let message = format!(
        "Deliverable size-cap checkpoint: visible task/verifier evidence says {path} must be under {limit} bytes. {observed}Evidence: {excerpt}\n\
Do not keep expanding the artifact and do not treat a larger working version as acceptable. First run a short size check such as wc -c or stat -c %s on the exact deliverable, then shrink the smallest implementation path: remove debug scaffolding, comments, unused helper tables, embedded sample data, broad fallbacks, and duplicated code; prefer compact algorithms or generated constants only when the verifier permits them. Rerun the same compile/runtime check plus the size check before done. This checkpoint is recovery guidance, not a loop stop condition.",
        path = evidence.path,
        limit = evidence.limit_bytes,
        observed = observed,
        excerpt = truncate(&evidence.excerpt, 500),
    );
    state.append_user_message(message);
    state.append_trajectory(json!({
        "type": "deliverable_size_cap_checkpoint",
        "turn": state.turn_count,
        "path": evidence.path,
        "limit_bytes": evidence.limit_bytes,
        "observed_bytes": evidence.observed_bytes,
        "evidence": truncate(&evidence.excerpt, 1000),
        "loop_stop_condition": false,
        "deliverable_size_cap_stop_condition": false,
        "time_round_token_limit_driven": false,
        "max_turns_stop_condition": false,
        "timeout_seconds_stop_condition": false,
    }));
    state.deliverable_size_cap_checkpoint_injected = true;
    true
}

fn record_successful_deliverable_size_cap_preflight(
    state: &mut WorkerState,
    tool_name: &str,
    args: &Value,
    result: &ToolResponse,
) {
    let Some(evidence) = deliverable_size_cap_evidence(state) else {
        return;
    };
    if !is_deliverable_size_cap_preflight_command(&evidence, tool_name, args, result) {
        return;
    }
    let observed_bytes = deliverable_size_cap_preflight_observed_bytes(result);
    state
        .deliverable_size_cap_preflight_turns
        .insert(evidence.path.clone(), state.turn_count);
    state.append_trajectory(json!({
        "type": "deliverable_size_cap_preflight_passed",
        "turn": state.turn_count,
        "tool": tool_name,
        "command": truncate(args.get("command").and_then(Value::as_str).unwrap_or(""), 1000),
        "path": evidence.path,
        "limit_bytes": evidence.limit_bytes,
        "observed_bytes": observed_bytes,
        "evidence_source_kind": deliverable_size_cap_evidence_source_kind(&evidence),
        "size_cap_evidence_turn": evidence.source_turn,
        "loop_stop_condition": false,
        "deliverable_size_cap_stop_condition": false,
        "time_round_token_limit_driven": false,
        "max_turns_stop_condition": false,
        "timeout_seconds_stop_condition": false,
        "round_limit_stop_condition": false,
        "checkpoint_count_stop_condition": false,
        "checkpoint_cooldown_stop_condition": false,
        "attempt_count_stop_condition": false,
        "budget_stop_condition": false,
    }));
}

fn deliverable_size_cap_preflight_pending(
    state: &WorkerState,
) -> Option<DeliverableSizeCapEvidence> {
    let evidence = deliverable_size_cap_evidence(state)?;
    let last_preflight_turn = deliverable_size_cap_preflight_turn(state, &evidence.path);
    if last_preflight_turn > evidence.source_turn {
        None
    } else {
        Some(evidence)
    }
}

fn deliverable_size_cap_preflight_turn(state: &WorkerState, path: &str) -> usize {
    state
        .deliverable_size_cap_preflight_turns
        .get(path)
        .copied()
        .unwrap_or(0)
}

fn deliverable_size_cap_evidence_source_kind(
    evidence: &DeliverableSizeCapEvidence,
) -> &'static str {
    if evidence.observed_bytes.is_some() {
        "failure"
    } else {
        "declared_contract"
    }
}

fn deliverable_size_cap_preflight_gate_message(
    evidence: &DeliverableSizeCapEvidence,
    state: &WorkerState,
) -> String {
    let observed = evidence
        .observed_bytes
        .map(|value| format!(" Last observed failing size was {value} bytes."))
        .unwrap_or_default();
    let source_clause = if evidence.observed_bytes.is_some() {
        "visible verifier/task evidence".to_string()
    } else {
        "the declared task/verifier contract".to_string()
    };
    let last_preflight_turn = deliverable_size_cap_preflight_turn(state, &evidence.path);
    let prior = if last_preflight_turn == 0 {
        "No successful focused size preflight has been recorded yet.".to_string()
    } else {
        format!(
            "Last focused size preflight was on turn {last_preflight_turn}, before or not after the current size-cap evidence."
        )
    };
    format!(
        "Deliverable size-cap preflight completion gate: {source_clause} says {path} must stay under {limit} bytes.{observed} {prior}\n\
Before calling done again, run a focused size check on the exact deliverable, such as `wc -c {path}`, `stat -c %s {path}`, or a Python assertion using Path({path_literal}).stat().st_size < {limit}. If behavior changed while shrinking, also rerun the smallest compile/runtime check that exercises the deliverable. This gate is not a master, sub-agent, or Worker loop stop condition and is not driven by time, round, turn, token, max_turns, timeout, checkpoint count, cooldown, attempt count, cap, count, or budget metadata.",
        source_clause = source_clause,
        path = evidence.path,
        limit = evidence.limit_bytes,
        path_literal = quoted_contract_literal(&evidence.path),
    )
}

fn is_deliverable_size_cap_preflight_command(
    evidence: &DeliverableSizeCapEvidence,
    tool_name: &str,
    args: &Value,
    result: &ToolResponse,
) -> bool {
    if tool_name != "bash" && tool_name != "verify" {
        return false;
    }
    let command = args.get("command").and_then(Value::as_str).unwrap_or("");
    if command.trim().is_empty() || !command_mentions_size_cap_path(command, &evidence.path) {
        return false;
    }
    if !command_looks_like_deliverable_size_probe(command) {
        return false;
    }
    if let Some(observed_bytes) = deliverable_size_cap_preflight_observed_bytes(result) {
        return observed_bytes <= evidence.limit_bytes;
    }
    command_has_size_cap_limit_comparison(command, evidence.limit_bytes)
}

fn command_mentions_size_cap_path(command: &str, path: &str) -> bool {
    let lowered = command.to_ascii_lowercase();
    let path_lowered = path.to_ascii_lowercase();
    if lowered.contains(&path_lowered) {
        return true;
    }
    let basename = Path::new(path)
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or(path)
        .to_ascii_lowercase();
    !basename.is_empty() && lowered.contains(&basename)
}

fn command_looks_like_deliverable_size_probe(command: &str) -> bool {
    let lowered = command.to_ascii_lowercase();
    let unquoted = lowered.replace(['\'', '"'], "");
    unquoted.contains("wc -c")
        || unquoted.contains("stat -c %s")
        || unquoted.contains("stat -c%s")
        || unquoted.contains("stat --format=%s")
        || unquoted.contains("stat --printf=%s")
        || lowered.contains(".stat().st_size")
        || lowered.contains("os.path.getsize")
        || lowered.contains("getsize(")
}

fn command_has_size_cap_limit_comparison(command: &str, limit_bytes: u64) -> bool {
    let lowered = command.to_ascii_lowercase();
    let has_comparison = lowered.contains('<')
        || lowered.contains(" -lt ")
        || lowered.contains(" less than ")
        || lowered.contains(" under ")
        || lowered.contains(" below ");
    if !has_comparison {
        return false;
    }
    let limit_text = limit_bytes.to_string();
    lowered.contains(&limit_text)
        || deliverable_size_cap_candidates(command)
            .iter()
            .any(|(candidate_limit, _)| *candidate_limit == limit_bytes)
}

fn deliverable_size_cap_preflight_observed_bytes(result: &ToolResponse) -> Option<u64> {
    let text = join_non_empty(&[result.output.clone(), result.error.clone()]);
    let mut observed = None;
    for line in text.lines() {
        let parsed = parse_size_value_from_line(line).or_else(|| parse_leading_size_value(line));
        if let Some(value) = parsed {
            observed = Some(observed.map_or(value, |current: u64| current.max(value)));
        }
    }
    observed
}

fn parse_leading_size_value(line: &str) -> Option<u64> {
    let trimmed = line.trim_start();
    let (value, after_value, _explicit_unit) = parse_size_literal_at(trimmed, 0)?;
    let tail = trimmed[after_value..].trim_start();
    if tail.is_empty()
        || tail.starts_with('/')
        || tail.starts_with('.')
        || tail
            .chars()
            .next()
            .is_some_and(|ch| ch.is_ascii_alphabetic())
    {
        return Some(value);
    }
    None
}

fn deliverable_size_cap_evidence(state: &WorkerState) -> Option<DeliverableSizeCapEvidence> {
    let mut sources = vec![(single_file_deliverable_task_text(state), 0usize)];
    for message in &state.messages {
        if let Some(content) = message.get("content").and_then(Value::as_str) {
            sources.push((content.to_string(), 0));
        }
    }
    for event in &state.tool_call_history {
        let args = event.get("args").unwrap_or(&Value::Null);
        let command = args.get("command").and_then(Value::as_str).unwrap_or("");
        let output = event.get("output").and_then(Value::as_str).unwrap_or("");
        let error = event.get("error").and_then(Value::as_str).unwrap_or("");
        let turn = event
            .get("turn")
            .and_then(Value::as_u64)
            .map(|value| value as usize)
            .unwrap_or(0);
        sources.push((format!("{command}\n{output}\n{error}"), turn));
    }
    for event in &state.trajectory {
        if let Some(source) = deliverable_size_cap_trajectory_source(event) {
            let turn = event
                .get("turn")
                .and_then(Value::as_u64)
                .map(|value| value as usize)
                .unwrap_or(0);
            sources.push((source, turn));
        }
    }
    if let Some(observation) = state.unresolved_failed_verification.as_ref() {
        sources.push((observation.observation.clone(), observation.turn));
        sources.extend(
            observation
                .semantic_contracts
                .iter()
                .cloned()
                .map(|contract| (contract, observation.turn)),
        );
    }
    let failure_evidence = sources
        .iter()
        .filter_map(|(source, turn)| {
            let mut evidence = deliverable_size_cap_evidence_from_text(source)?;
            evidence.source_turn = *turn;
            Some(evidence)
        })
        .max_by_key(|evidence| (evidence.observed_bytes.unwrap_or(0), evidence.source_turn));
    failure_evidence.or_else(|| state.declared_deliverable_size_cap.clone())
}

fn deliverable_size_cap_trajectory_source(event: &Value) -> Option<String> {
    let event_type = event.get("type").and_then(Value::as_str).unwrap_or("");
    let include = match event_type {
        "entrypoint_scan" => event
            .get("success")
            .and_then(Value::as_bool)
            .is_some_and(|success| !success),
        "failed_verification_observed"
        | "local_semantic_failure_observed"
        | "local_exception_observed" => true,
        _ => false,
    };
    if !include {
        return None;
    }
    let command = event.get("command").and_then(Value::as_str).unwrap_or("");
    let output = event.get("output").and_then(Value::as_str).unwrap_or("");
    let error = event.get("error").and_then(Value::as_str).unwrap_or("");
    let observation = event
        .get("observation")
        .and_then(Value::as_str)
        .unwrap_or("");
    let semantic_contracts = event
        .get("semantic_contracts")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(Value::as_str)
                .collect::<Vec<_>>()
                .join("\n")
        })
        .unwrap_or_default();
    let source = join_non_empty(&[
        command.to_string(),
        output.to_string(),
        error.to_string(),
        observation.to_string(),
        semantic_contracts,
    ]);
    if source.trim().is_empty() {
        None
    } else {
        Some(source)
    }
}

fn deliverable_size_cap_evidence_from_text(text: &str) -> Option<DeliverableSizeCapEvidence> {
    let candidates = deliverable_size_cap_candidates(text);
    if candidates.is_empty() {
        return None;
    }
    let paths = size_cap_path_candidates(text);
    if paths.is_empty() {
        return None;
    }

    let mut selected: Option<(i32, usize, u64, String, Option<u64>)> = None;
    for (limit, position) in candidates {
        if size_cap_candidate_context_is_passing(text, position)
            || size_cap_candidate_context_is_generated_report(text, position)
        {
            continue;
        }
        for (path, start, end) in &paths {
            let score = size_cap_path_score(text, position, path, *start, *end);
            if score <= 0 {
                continue;
            }
            let observed = deliverable_size_observed_bytes_for_path(text, path);
            if observed.is_some_and(|observed_bytes| observed_bytes < limit) {
                continue;
            }
            if observed.is_none() && !has_size_cap_failure_text(text, Some(position)) {
                continue;
            }
            let replace = match &selected {
                Some(current) => (score, position, limit) > (current.0, current.1, current.2),
                None => true,
            };
            if replace {
                selected = Some((score, position, limit, path.clone(), observed));
            }
        }
    }
    let (_score, position, limit_bytes, path, observed) = selected?;
    Some(DeliverableSizeCapEvidence {
        path,
        limit_bytes,
        observed_bytes: observed,
        excerpt: deliverable_size_cap_excerpt(text, Some(position)),
        source_turn: 0,
    })
}

fn deliverable_size_cap_candidates(text: &str) -> Vec<(u64, usize)> {
    let lowered = text.to_ascii_lowercase();
    let mut candidates = Vec::new();
    for marker in [
        "under ",
        "less than ",
        "smaller than ",
        "below ",
        "larger than ",
        "greater than ",
        "over ",
        "< ",
        "<",
    ] {
        let mut search = 0usize;
        while let Some(offset) = lowered[search..].find(marker) {
            let number_start = search + offset + marker.len();
            if let Some((number, after_number, explicit_unit)) =
                parse_size_literal_at(text, number_start)
            {
                if explicit_unit
                    || size_cap_candidate_has_unit_or_context(
                        text,
                        search + offset,
                        after_number,
                        marker,
                    )
                {
                    candidates.push((number, search + offset));
                }
                search = after_number.max(number_start + 1);
            } else {
                search = number_start.max(search + offset + 1);
            }
        }
    }
    candidates
}

fn extract_declared_deliverable_size_cap_contract(
    task_instruction: &str,
    task_context: &Value,
) -> Option<DeliverableSizeCapEvidence> {
    let sources = collect_task_context_evidence(task_instruction, task_context, 4);
    let text = sources.join("\n");
    declared_deliverable_size_cap_evidence_from_text(&text)
}

fn declared_deliverable_size_cap_evidence_from_text(
    text: &str,
) -> Option<DeliverableSizeCapEvidence> {
    let candidates = deliverable_size_cap_candidates(text);
    if candidates.is_empty() {
        return None;
    }
    let paths = size_cap_path_candidates(text);
    if paths.is_empty() {
        return None;
    }

    let mut selected: Option<(i32, usize, u64, String)> = None;
    for (limit, position) in candidates {
        if limit == 0
            || size_cap_candidate_context_is_passing(text, position)
            || size_cap_candidate_context_is_generated_report(text, position)
        {
            continue;
        }
        if !has_declared_size_cap_contract_text(text, position) {
            continue;
        }
        for (path, start, end) in &paths {
            let score = size_cap_path_score(text, position, path, *start, *end);
            if score <= 0 {
                continue;
            }
            let replace = match &selected {
                Some(current) => (score, position, limit) > (current.0, current.1, current.2),
                None => true,
            };
            if replace {
                selected = Some((score, position, limit, path.clone()));
            }
        }
    }
    let (_score, position, limit_bytes, path) = selected?;
    Some(DeliverableSizeCapEvidence {
        path,
        limit_bytes,
        observed_bytes: None,
        excerpt: deliverable_size_cap_excerpt(text, Some(position)),
        source_turn: 0,
    })
}

fn has_declared_size_cap_contract_text(text: &str, position: usize) -> bool {
    let start = text[..position]
        .char_indices()
        .rev()
        .nth(450)
        .map(|(idx, _)| idx)
        .unwrap_or(0);
    let end = text[position..]
        .char_indices()
        .nth(450)
        .map(|(idx, _)| position + idx)
        .unwrap_or(text.len());
    let window = text[start..end].to_ascii_lowercase();
    let has_artifact = window.contains("/app/") || window.contains("path(");
    let has_deliverable_action = [
        "must",
        "should",
        "required",
        "requires",
        "verifier",
        "test",
        "assert",
        "write",
        "create",
        "program",
        "file",
        "deliverable",
    ]
    .iter()
    .any(|needle| window.contains(needle));
    let has_size_language = [
        "bytes",
        "byte",
        "st_size",
        "file size",
        "size cap",
        "under",
        "less than",
    ]
    .iter()
    .any(|needle| window.contains(needle));
    has_artifact && has_deliverable_action && has_size_language
}

fn size_cap_candidate_context_is_generated_report(text: &str, position: usize) -> bool {
    let start = text[..position]
        .char_indices()
        .rev()
        .nth(350)
        .map(|(idx, _)| idx)
        .unwrap_or(0);
    let end = text[position..]
        .char_indices()
        .nth(350)
        .map(|(idx, _)| position + idx)
        .unwrap_or(text.len());
    let lowered = text[start..end].to_ascii_lowercase();
    lowered.contains("deliverable_size_cap_contract:")
        || lowered.contains("mechanism=deliverable_size_cap_contract")
        || lowered.contains("- deliverable_size_cap_contract:")
        || lowered.contains("name=deliverable_size_cap_contract")
}

fn parse_size_literal_at(text: &str, index: usize) -> Option<(u64, usize, bool)> {
    let bytes = text.as_bytes();
    let mut cursor = skip_ascii_whitespace(bytes, index);
    let mut digits = String::new();
    while let Some(byte) = bytes.get(cursor).copied() {
        if byte.is_ascii_digit() {
            digits.push(byte as char);
            cursor += 1;
            continue;
        }
        if matches!(byte, b',' | b'_') {
            cursor += 1;
            continue;
        }
        break;
    }
    if digits.is_empty() {
        return None;
    }
    let suffix_start = cursor;
    while bytes.get(cursor).is_some_and(u8::is_ascii_alphabetic) {
        cursor += 1;
    }
    let mut suffix = text[suffix_start..cursor].to_ascii_lowercase();
    let multiplier = match suffix.as_str() {
        "" | "b" | "byte" | "bytes" => 1,
        "k" | "kb" => 1_000,
        "ki" | "kib" => 1_024,
        "m" | "mb" => 1_000_000,
        "mi" | "mib" => 1_048_576,
        _ => {
            cursor = suffix_start;
            suffix.clear();
            1
        }
    };
    let value = digits.parse::<u64>().ok()?.checked_mul(multiplier)?;
    Some((value, cursor, !suffix.is_empty()))
}

fn size_cap_candidate_has_unit_or_context(
    text: &str,
    position: usize,
    after_number: usize,
    marker: &str,
) -> bool {
    let (line, line_start) = line_around_position(text, position);
    let lowered = line.to_ascii_lowercase();
    let tail_start = after_number.saturating_sub(line_start).min(line.len());
    let tail = line[tail_start..].to_ascii_lowercase();
    let tail_trimmed = tail.trim_start();
    if tail_trimmed.starts_with("byte") || tail_trimmed == "b" || tail_trimmed.starts_with("b ") {
        return true;
    }
    if contains_size_unit_token(&lowered) {
        return true;
    }
    if marker.trim() == "<" {
        return ["st_size", "file size", ".stat()", "size"]
            .iter()
            .any(|token| lowered.contains(token));
    }
    lowered.contains("limit")
        && ["size", "file", "under", "below", "less"]
            .iter()
            .any(|token| lowered.contains(token))
}

fn contains_size_unit_token(text: &str) -> bool {
    text.split(|ch: char| !ch.is_ascii_alphanumeric())
        .any(|token| matches!(token, "byte" | "bytes" | "kb" | "kib" | "mb" | "mib"))
}

fn size_cap_path_candidates(text: &str) -> Vec<(String, usize, usize)> {
    let mut candidates = Vec::new();
    let mut seen = HashSet::new();
    for (candidate, start, end) in verifier_artifact_candidate_tokens(text)
        .into_iter()
        .chain(deliverable_candidate_tokens(text))
    {
        if candidate.starts_with("/tests/") || candidate.contains("/tests/") {
            continue;
        }
        if seen.insert(candidate.clone()) {
            candidates.push((candidate, start, end));
        }
    }
    candidates.sort_by_key(|(_, start, _)| *start);
    candidates
}

fn deliverable_size_observed_bytes_for_path(text: &str, path: &str) -> Option<u64> {
    let mut observed = None;
    let text_lowered = text.to_ascii_lowercase();
    let path_lowered = path.to_ascii_lowercase();
    let basename = Path::new(path)
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or(path)
        .to_ascii_lowercase();
    if !text_lowered.contains(&path_lowered) && !text_lowered.contains(&basename) {
        return None;
    }
    for line in text.lines() {
        let lowered = line.to_ascii_lowercase();
        if !lowered.contains(&path_lowered)
            && !lowered.contains(&basename)
            && !lowered.contains("st_size")
            && !lowered.contains("assert ")
            && !lowered.contains("file size:")
            && !lowered.contains("size:")
        {
            continue;
        }
        if let Some(value) = parse_size_value_from_line(line) {
            observed = Some(observed.map_or(value, |current: u64| current.max(value)));
        }
    }
    observed
}

fn parse_size_value_from_line(line: &str) -> Option<u64> {
    let lowered = line.to_ascii_lowercase();
    for marker in ["st_size=", "size="] {
        if let Some(offset) = lowered.find(marker) {
            return parse_size_literal_at(line, offset + marker.len()).map(|(value, _, _)| value);
        }
    }
    if let Some(offset) = lowered.find("assert ") {
        if let Some((value, after_value, _explicit_unit)) =
            parse_size_literal_at(line, offset + "assert ".len())
        {
            let tail = lowered[after_value..].chars().take(12).collect::<String>();
            if tail.contains('<') {
                return Some(value);
            }
        }
    }
    for marker in ["file size:", "size:"] {
        if let Some(offset) = lowered.find(marker) {
            if let Some((value, after_value, explicit_unit)) =
                parse_size_literal_at(line, offset + marker.len())
            {
                let tail = lowered[after_value..].chars().take(24).collect::<String>();
                if explicit_unit || tail.contains("byte") || tail.trim().is_empty() {
                    return Some(value);
                }
            }
        }
    }
    None
}

fn size_cap_path_score(text: &str, position: usize, path: &str, start: usize, end: usize) -> i32 {
    let distance = position.abs_diff(start).min(position.abs_diff(end));
    if distance > 900 {
        return 0;
    }
    let window_start = text[..position.min(start)]
        .char_indices()
        .rev()
        .nth(500)
        .map(|(idx, _)| idx)
        .unwrap_or(0);
    let window_end = text[position.max(end)..]
        .char_indices()
        .nth(500)
        .map(|(idx, _)| position.max(end) + idx)
        .unwrap_or(text.len());
    let window = text[window_start..window_end].to_ascii_lowercase();
    let path_lowered = path.to_ascii_lowercase();
    let basename = Path::new(path)
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or(path)
        .to_ascii_lowercase();
    let mut score = 0;
    if window.contains(&path_lowered) {
        score += 4;
    }
    if !basename.is_empty() && window.contains(&basename) {
        score += 1;
    }
    if [
        "st_size",
        "file size",
        "larger than",
        "less than",
        "under",
        "below",
        "over",
    ]
    .iter()
    .any(|token| window.contains(token))
    {
        score += 2;
    }
    let (line, _) = line_around_position(text, position);
    let line_lowered = line.to_ascii_lowercase();
    if line_lowered.contains(&path_lowered) || line_lowered.contains(&basename) {
        score += 4;
    }
    if window.contains("subprocess.run")
        && window.contains(&path_lowered)
        && !["st_size", "file size", "larger than"]
            .iter()
            .any(|token| window.contains(token))
    {
        score -= 3;
    }
    score
}

fn size_cap_candidate_context_is_passing(text: &str, position: usize) -> bool {
    let (line, _) = line_around_position(text, position);
    let lowered = line.to_ascii_lowercase();
    if ["fail", "larger than", "greater than", "too large", "exceed"]
        .iter()
        .any(|token| lowered.contains(token))
    {
        return false;
    }
    let compact = lowered.replace(char::is_whitespace, " ");
    compact.contains("limit? yes")
        || compact.contains("limit yes")
        || compact.contains("limit? true")
        || compact.contains("limit true")
        || compact.contains("limit? pass")
        || compact.contains("limit pass")
}

fn line_around_position(text: &str, position: usize) -> (&str, usize) {
    let start = text[..position].rfind('\n').map(|idx| idx + 1).unwrap_or(0);
    let end = text[position..]
        .find('\n')
        .map(|idx| position + idx)
        .unwrap_or(text.len());
    (&text[start..end], start)
}

fn has_size_cap_failure_text(text: &str, position: Option<usize>) -> bool {
    let source = if let Some(position) = position {
        let start = text[..position]
            .char_indices()
            .rev()
            .nth(500)
            .map(|(idx, _)| idx)
            .unwrap_or(0);
        let end = text[position..]
            .char_indices()
            .nth(500)
            .map(|(idx, _)| position + idx)
            .unwrap_or(text.len());
        &text[start..end]
    } else {
        text
    };
    let lowered = source.to_ascii_lowercase();
    lowered.contains("larger than")
        || lowered.contains("greater than")
        || lowered.contains("too large")
        || lowered.contains("exceeds")
        || lowered.contains("over ")
        || lowered.contains("st_size=")
        || lowered.contains("limit? no")
        || lowered.contains("limit no")
        || lowered.contains("limit? false")
        || lowered.contains("limit false")
        || lowered.contains("limit? fail")
        || lowered.contains("limit fail")
        || (lowered.contains("assert ") && lowered.contains('<') && lowered.contains("byte"))
}

fn deliverable_size_cap_excerpt(text: &str, position: Option<usize>) -> String {
    if let Some(position) = position {
        let (line, _) = line_around_position(text, position);
        if !line.trim().is_empty() {
            return line.trim().to_string();
        }
    }
    for line in text.lines() {
        let lowered = line.to_ascii_lowercase();
        if lowered.contains("byte")
            || lowered.contains("st_size")
            || lowered.contains("larger than")
            || lowered.contains("under ")
        {
            return line.trim().to_string();
        }
    }
    text.lines().take(4).collect::<Vec<_>>().join(" | ")
}

