fn git_sanitization_scope_contract(text: &str) -> Option<String> {
    let normalized;
    let source = if text.contains("\\n") {
        normalized = normalize_escaped_trace_text(text);
        normalized.as_str()
    } else {
        text
    };
    let lowered = source.to_ascii_lowercase();
    if !looks_like_git_sanitization_scope_failure(&lowered) {
        return None;
    }
    let changed_paths = git_sanitization_changed_paths(source);
    let changed_path_detail = if changed_paths.is_empty() {
        "any path reported by `File <path> has been changed`".to_string()
    } else {
        changed_paths.join(", ")
    };
    let baseline_detail = if lowered.contains("d6987af002b122fef54bc0be402062c76488a4d9") {
        "baseline commit d6987af002b122fef54bc0be402062c76488a4d9".to_string()
    } else {
        "the verifier baseline commit".to_string()
    };
    Some(format!(
        "git_sanitization_scope_contract: verifier diffs the working tree against {baseline_detail} with commit.diff(None); only files listed in CONTAMINATED_PATHS may change. Preserve already-passing secret removal/replacement behavior, inspect git diff/name-only against the baseline, and revert unrelated changed paths such as {changed_path_detail} before done; rerun the focused test_no_other_files_changed check after the revert"
    ))
}

fn git_sanitization_changed_paths(text: &str) -> Vec<String> {
    let mut paths = Vec::new();
    for line in text.lines() {
        let lowered = line.to_ascii_lowercase();
        let Some(file_offset) = lowered.find("file ") else {
            continue;
        };
        let after_file = file_offset + "file ".len();
        let Some(relative_end) = lowered[after_file..].find(" has been changed") else {
            continue;
        };
        let candidate = line[after_file..after_file + relative_end]
            .trim()
            .trim_matches(|ch: char| matches!(ch, '`' | '\'' | '"' | ':' | ',' | '.'));
        if candidate.is_empty() || candidate.contains(' ') || candidate.starts_with('/') {
            continue;
        }
        paths.push(candidate.to_string());
        if paths.len() >= 4 {
            break;
        }
    }
    dedupe_preserve_order(paths)
}

