fn expected_string_tokens_from_python_lists(text: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let mut index = 0usize;
    while let Some(relative) = text[index..].find('[') {
        let start = index + relative;
        let Some(end) = matching_bracket_end(text, start) else {
            index = start + 1;
            continue;
        };
        let list_text = &text[start + 1..end];
        let values = string_literals_in_text(list_text);
        if !values.is_empty() && values.iter().all(|value| looks_like_output_token(value)) {
            tokens.extend(values);
        }
        index = start + 1;
    }
    dedupe_preserve_order(tokens)
}

fn matching_bracket_end(text: &str, start: usize) -> Option<usize> {
    let mut depth = 0usize;
    let mut quote: Option<char> = None;
    let mut escaped = false;
    for (index, ch) in text[start..].char_indices() {
        let absolute = start + index;
        if let Some(active_quote) = quote {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == active_quote {
                quote = None;
            }
            continue;
        }
        if ch == '\'' || ch == '"' {
            quote = Some(ch);
            continue;
        }
        if ch == '[' {
            depth += 1;
            continue;
        }
        if ch == ']' {
            if depth == 0 {
                return None;
            }
            depth -= 1;
            if depth == 0 {
                return Some(absolute);
            }
        }
    }
    None
}

fn string_literals_in_text(text: &str) -> Vec<String> {
    let mut values = Vec::new();
    let mut chars = text.char_indices().peekable();
    while let Some((index, ch)) = chars.next() {
        if ch != '\'' && ch != '"' {
            continue;
        }
        if let Some(value) = parse_simple_python_string_literal(&text[index..]) {
            values.push(value);
        }
        while let Some((_, next_ch)) = chars.peek() {
            if *next_ch == ',' || next_ch.is_whitespace() {
                break;
            }
            chars.next();
        }
    }
    values
}

fn looks_like_output_token(value: &str) -> bool {
    !value.trim().is_empty()
        && value.chars().count() <= 80
        && !value.chars().any(char::is_whitespace)
}

