fn single_file_observed_entries_detail(text: &str) -> String {
    let mut entries = Vec::new();
    let lowered = text.to_ascii_lowercase();
    for marker in ["found:", "found "] {
        if let Some(start) = lowered.find(marker) {
            let tail = &text[start + marker.len()..];
            for token in tail
                .split(|ch: char| {
                    ch.is_whitespace()
                        || matches!(ch, '[' | ']' | ',' | ':' | ';' | '(' | ')' | '{' | '}')
                })
                .map(|value| value.trim_matches(|ch: char| matches!(ch, '\'' | '"' | '`')))
            {
                if token.is_empty() {
                    continue;
                }
                let lowered_token = token.to_ascii_lowercase();
                if lowered_token.starts_with("test")
                    || lowered_token.starts_with("main_test")
                    || lowered_token.ends_with(".o")
                    || lowered_token.ends_with(".rs")
                    || lowered_token.ends_with(".cpp")
                    || lowered_token == "cmain"
                {
                    entries.push(token.to_string());
                }
                if entries.len() >= 8 {
                    break;
                }
            }
            break;
        }
    }
    let entries = dedupe_preserve_order(entries);
    if entries.is_empty() {
        String::new()
    } else {
        format!(", observed extra entries include {}", entries.join(", "))
    }
}

