fn normalize_escaped_trace_text(text: &str) -> String {
    text.replace("\\n", "\n")
        .replace("\\\"", "\"")
        .replace("\\'", "'")
}

fn python_string_assignment_value(text: &str, variable: &str) -> Option<String> {
    for line in text.lines() {
        let trimmed = line.trim();
        let Some(offset) = trimmed.find(variable) else {
            continue;
        };
        if offset > 0
            && trimmed[..offset]
                .chars()
                .any(|ch| ch.is_ascii_alphanumeric() || ch == '_')
        {
            continue;
        }
        let tail = &trimmed[offset + variable.len()..];
        let tail = tail.trim_start();
        let Some(tail) = tail.strip_prefix('=') else {
            continue;
        };
        let tail = tail.trim_start();
        let value = parse_simple_python_string_literal(tail)?;
        return Some(value);
    }
    None
}

fn path_read_text_target(text: &str) -> Option<String> {
    let path_assignments = path_variable_assignments(text);
    for line in text.lines() {
        if !line.contains("read_text") {
            continue;
        }
        if let Some(path) = path_literal_in_path_call(line) {
            return Some(path);
        }
        for (variable, path) in &path_assignments {
            if line_contains_variable_read_text(line, variable) {
                return Some(path.clone());
            }
        }
    }
    app_path_candidate_tokens(text)
        .into_iter()
        .map(|(candidate, _, _)| candidate)
        .find(|candidate| looks_like_deliverable_path(candidate))
}

fn path_variable_assignments(text: &str) -> Vec<(String, String)> {
    let mut assignments = Vec::new();
    let mut seen = HashSet::new();
    for line in text.lines() {
        if !line.contains("Path(") || !line.contains("/app/") || !line.contains('=') {
            continue;
        }
        let Some((left, right)) = line.split_once('=') else {
            continue;
        };
        let variable = left
            .trim()
            .trim_start_matches('>')
            .trim()
            .trim_start_matches("assert ")
            .trim();
        if !is_simple_python_identifier(variable) {
            continue;
        }
        let Some(path) = path_literal_in_path_call(right) else {
            continue;
        };
        if seen.insert(variable.to_string()) {
            assignments.push((variable.to_string(), path));
        }
    }
    assignments
}

fn path_literal_in_path_call(text: &str) -> Option<String> {
    let mut search = 0usize;
    while let Some(offset) = text[search..].find("Path(") {
        let start = search + offset + "Path(".len();
        let tail = text[start..].trim_start();
        if let Some(path) = parse_simple_python_string_literal(tail) {
            if looks_like_deliverable_path(&path) {
                return Some(path);
            }
        }
        search = start;
    }
    None
}

fn direct_read_text_literal_expected(text: &str) -> Option<String> {
    let path_assignments = path_variable_assignments(text);
    for line in text.lines() {
        if !line.contains("read_text") || !line.contains("==") {
            continue;
        }
        let mentions_path_read = path_literal_in_path_call(line).is_some()
            || path_assignments
                .iter()
                .any(|(variable, _)| line_contains_variable_read_text(line, variable));
        if !mentions_path_read {
            continue;
        }
        let Some((left, right)) = line.split_once("==") else {
            continue;
        };
        if left.contains("read_text") {
            if let Some(value) = parse_assertion_side_string_literal(right) {
                return Some(value);
            }
        }
        if right.contains("read_text") {
            if let Some(value) = parse_assertion_side_string_literal(left) {
                return Some(value);
            }
        }
    }
    None
}

fn parse_assertion_side_string_literal(text: &str) -> Option<String> {
    let trimmed = text
        .trim()
        .trim_start_matches('>')
        .trim()
        .trim_start_matches("assert ")
        .trim();
    parse_simple_python_string_literal(trimmed)
}

fn line_contains_variable_read_text(line: &str, variable: &str) -> bool {
    line.contains(&format!("{variable}.read_text"))
        || line.contains(&format!("{variable} .read_text"))
        || line.contains(&format!("{variable}. read_text"))
        || line.contains(&format!("{variable} . read_text"))
}

fn is_simple_python_identifier(value: &str) -> bool {
    let mut chars = value.chars();
    let Some(first) = chars.next() else {
        return false;
    };
    (first == '_' || first.is_ascii_alphabetic())
        && chars.all(|ch| ch == '_' || ch.is_ascii_alphanumeric())
}

fn parse_simple_python_string_literal(text: &str) -> Option<String> {
    let mut offset = 0usize;
    for ch in text.chars() {
        if matches!(ch, 'r' | 'R' | 'u' | 'U' | 'b' | 'B') {
            offset += ch.len_utf8();
            continue;
        }
        break;
    }
    let text = &text[offset..];
    let quote = text.chars().next()?;
    if quote != '\"' && quote != '\'' {
        return None;
    }
    let mut escaped = false;
    let mut value = String::new();
    for ch in text[quote.len_utf8()..].chars() {
        if escaped {
            let decoded = match ch {
                'n' => '\n',
                't' => '\t',
                'r' => '\r',
                '\\' => '\\',
                '\"' => '\"',
                '\'' => '\'',
                other => other,
            };
            value.push(decoded);
            escaped = false;
            continue;
        }
        if ch == '\\' {
            escaped = true;
            continue;
        }
        if ch == quote {
            return Some(value);
        }
        value.push(ch);
    }
    None
}

fn quoted_contract_literal(value: &str) -> String {
    format!(
        "\"{}\"",
        value
            .replace('\\', "\\\\")
            .replace('"', "\\\"")
            .replace('\n', "\\n")
    )
}

