fn extract_missing_output_artifact_gate_targets(
    task_instruction: &str,
    task_context: &Value,
    deliverable_targets: &[String],
) -> Vec<String> {
    let mut sources = Vec::new();
    sources.push(task_instruction.to_string());
    for key in [
        "completion_condition",
        "environment_context",
        "verifier_output",
        "verifier_logs",
    ] {
        if let Some(value) = task_context.get(key).and_then(Value::as_str) {
            sources.push(value.to_string());
        }
    }
    sources.extend(previous_error_evidence_items(task_context));
    let text = sources.join("\n");
    let lowered = text.to_ascii_lowercase();
    let explicit_missing_or_expected = [
        "does not exist",
        "not found",
        "no such file",
        "filenotfounderror",
        "expected artifact",
        "expected model artifact",
        "expected output",
        "expected deliverable",
        "model artifact",
        "must exist",
        "should exist",
        "save the model",
        "save as",
        "should be saved",
        "save the expected",
        "saved as",
        "output /app/",
        "write to /app/",
    ]
    .iter()
    .any(|needle| lowered.contains(needle));
    if !explicit_missing_or_expected {
        return Vec::new();
    }
    let mut targets = Vec::new();
    let mut seen = HashSet::new();
    for target in deliverable_targets {
        if missing_output_artifact_gate_target_is_safe(target) && seen.insert(target.clone()) {
            targets.push(target.clone());
        }
    }
    if let Some(evidence) = missing_output_artifact_evidence(&text) {
        for path in evidence.paths {
            if missing_output_artifact_gate_target_is_safe(&path) && seen.insert(path.clone()) {
                targets.push(path);
            }
            if targets.len() >= 6 {
                break;
            }
        }
    }
    targets
}

fn extract_exact_output_readback_targets(
    task_instruction: &str,
    task_context: &Value,
) -> Vec<ExactOutputReadbackTarget> {
    let mut sources = Vec::new();
    sources.push(task_instruction.to_string());
    for key in [
        "completion_condition",
        "environment_context",
        "verifier_output",
        "verifier_logs",
    ] {
        if let Some(value) = task_context.get(key).and_then(Value::as_str) {
            sources.push(value.to_string());
        }
    }
    sources.extend(previous_error_evidence_items(task_context));
    let text = sources.join("\n");
    if text.trim().is_empty() {
        return Vec::new();
    }
    let mut targets = Vec::new();
    let mut seen = HashSet::new();
    if let Some(evidence) = literal_output_file_evidence(&text) {
        if exact_output_readback_target_is_safe(&evidence.path)
            && seen.insert(evidence.path.clone())
        {
            targets.push(ExactOutputReadbackTarget {
                path: evidence.path,
                kind: ExactOutputReadbackKind::Literal,
                expected_literal: Some(evidence.expected),
                expected_tokens: Vec::new(),
            });
        }
    }
    if let Some(evidence) = tokenized_output_file_evidence(&text) {
        if exact_output_readback_target_is_safe(&evidence.path)
            && seen.insert(evidence.path.clone())
        {
            targets.push(ExactOutputReadbackTarget {
                path: evidence.path,
                kind: ExactOutputReadbackKind::Tokenized {
                    order_insensitive: evidence.order_insensitive,
                },
                expected_literal: None,
                expected_tokens: evidence.expected_tokens,
            });
        }
    }
    targets
}

fn previous_error_evidence_items(task_context: &Value) -> Vec<String> {
    let Some(previous_errors) = task_context
        .get("previous_errors")
        .and_then(Value::as_array)
    else {
        return Vec::new();
    };
    previous_errors
        .iter()
        .filter_map(|item| {
            let text = item
                .as_str()
                .map(str::to_string)
                .unwrap_or_else(|| item.to_string());
            let trimmed = text.trim();
            if trimmed.is_empty() {
                None
            } else {
                Some(truncate(trimmed, 4000))
            }
        })
        .collect()
}

