fn dependency_checkpoint_cross_arch_hint(state: &WorkerState) -> String {
    if !dependency_checkpoint_should_use_cross_arch_pivot(state) {
        return String::new();
    }
    let deliverables = cross_arch_dependency_deliverable_targets(state);
    let deliverable_clause = if deliverables.is_empty() {
        "/app/doomgeneric_mips or the task-visible MIPS ELF/binary".to_string()
    } else {
        deliverables.join(", ")
    };
    let binutils_clause = if dependency_checkpoint_has_mips_binutils_evidence(state) {
        "The trajectory has already seen MIPS binutils evidence, so prefer mipsel-linux-gnu-as, mipsel-linux-gnu-ld, mipsel-linux-gnu-objdump, readelf, and file over any new gcc/clang/LLVM/cross-toolchain install."
    } else {
        "Probe command -v mipsel-linux-gnu-as mipsel-linux-gnu-ld mipsel-linux-gnu-objdump readelf file once, then use whichever existing assembler/linker/inspectors are present instead of installing gcc, clang, LLVM, qemu, or another cross toolchain."
    };
    format!(
        " Cross-architecture/MIPS toolchain pivot: after repeated gcc, clang, LLVM, binutils, qemu, apt-cache, apt-get, source-build, or root-find setup failures, stop toolchain installation/search work and focus on the visible deliverable(s): {deliverable_clause}. {binutils_clause} Inspect the task source, makefile/linker expectations, ELF class/data/machine, entrypoint, sections, and symbols with readelf -h, file, and objdump -f. If a full Doom port is not feasible with installed tools, produce the smallest verifier-compatible MIPS ELF/binary from the visible contract instead of continuing apt or compiler work. Validate with static ELF checks first and only a tiny bounded qemu-mips smoke when already available; this pivot is not a loop stop condition and is not driven by time, round, turn, token, max_turns, timeout, toolchain failure count, attempt count, cap, or budget metadata."
    )
}

