fn cross_arch_dependency_deliverable_targets(state: &WorkerState) -> Vec<String> {
    let mut deliverables = Vec::new();
    let mut seen = HashSet::new();
    for target in &state.deliverable_targets {
        let lowered = target.to_ascii_lowercase();
        if [
            "doomgeneric_mips",
            "mips",
            "mipsel",
            ".elf",
            ".bin",
            "/app/doomgeneric",
        ]
        .iter()
        .any(|needle| lowered.contains(needle))
            && seen.insert(target.clone())
        {
            deliverables.push(target.clone());
        }
    }
    let scope = dependency_checkpoint_scope_text(state);
    for expected in ["/app/doomgeneric_mips", "doomgeneric_mips"] {
        if scope.contains(&expected.to_ascii_lowercase()) && seen.insert(expected.to_string()) {
            deliverables.push(expected.to_string());
        }
    }
    deliverables
}

