fn dependency_checkpoint_scope_text(state: &WorkerState) -> String {
    format!(
        "{}\n{}\n{}\n{}\n{}\n{}",
        state.task_instruction,
        task_context_string(&state.task_context, "completion_condition"),
        task_context_string(&state.task_context, "environment_context"),
        task_context_string(&state.task_context, "task_id"),
        task_context_historical_failure_text(&state.task_context),
        state.deliverable_targets.join("\n")
    )
    .to_ascii_lowercase()
}

const HISTORICAL_FAILURE_CONTEXT_KEYS: &[&str] = &[
    "previous_errors",
    "historical_analysis_lessons",
    "analysis_lessons",
    "same_task_memory",
    "prior_failure_signals",
    "recent_prior_failure_signals",
    "historical_failures",
    "task_historical_analysis",
    "failure_mechanisms",
    "policy_counts",
    "trajectory_evidence",
    "cross_round_evidence",
];

fn task_context_historical_failure_text(task_context: &Value) -> String {
    let mut fragments = Vec::new();
    for key in HISTORICAL_FAILURE_CONTEXT_KEYS {
        if let Some(value) = task_context.get(*key) {
            append_historical_failure_context_fragment(key, value, &mut fragments, 0);
        }
    }
    fragments.join("\n")
}

fn append_historical_failure_context_fragment(
    label: &str,
    value: &Value,
    fragments: &mut Vec<String>,
    depth: usize,
) {
    if depth > 5 || fragments.len() >= 24 {
        return;
    }
    match value {
        Value::String(text) => {
            let trimmed = text.trim();
            if !trimmed.is_empty() {
                fragments.push(format!("{label}: {}", truncate(trimmed, 2000)));
            }
        }
        Value::Number(_) | Value::Bool(_) => {
            fragments.push(format!("{label}: {value}"));
        }
        Value::Array(items) => {
            for item in items.iter().take(8) {
                append_historical_failure_context_fragment(label, item, fragments, depth + 1);
                if fragments.len() >= 24 {
                    break;
                }
            }
        }
        Value::Object(object) => {
            if label == "policy_counts" {
                let policy_counts = object
                    .iter()
                    .take(12)
                    .map(|(key, value)| format!("{key}={value}"))
                    .collect::<Vec<_>>()
                    .join(", ");
                if !policy_counts.is_empty() {
                    fragments.push(format!("{label}: {policy_counts}"));
                }
            }
            for key in [
                "summary_id",
                "task_id",
                "failure_category",
                "failure_class",
                "mechanism",
                "name",
                "description",
                "detail",
                "evidence",
                "policy_counts",
                "failure_mechanisms",
                "historical_analysis_lessons",
                "analysis_lessons",
                "same_task_memory",
                "prior_failure_signals",
                "recent_prior_failure_signals",
                "historical_failures",
                "timed_out_commands",
                "dependency_and_toolchain_evidence",
                "terminal_environment_markers",
            ] {
                if let Some(nested) = object.get(key) {
                    append_historical_failure_context_fragment(key, nested, fragments, depth + 1);
                    if fragments.len() >= 24 {
                        break;
                    }
                }
            }
        }
        Value::Null => {}
    }
}

