fn maybe_inject_dependency_artifact_first_checkpoint(state: &mut WorkerState) -> bool {
    if state.dependency_checkpoint_count == 0 {
        return false;
    }
    let untouched: Vec<String> = state
        .deliverable_targets
        .iter()
        .filter(|target| !state.touched_deliverables.contains(*target))
        .cloned()
        .collect();
    if untouched.is_empty() {
        return false;
    }
    let mut path_list = untouched
        .iter()
        .take(4)
        .cloned()
        .collect::<Vec<_>>()
        .join(", ");
    if untouched.len() > 4 {
        path_list.push_str(", ...");
    }
    let message = format!(
        "Dependency artifact-first checkpoint: repeated dependency recovery just fired while explicit required artifact(s) remain untouched: {path_list}. Before any further install, download, package-cache search, source build, toolchain chase, full benchmark, or broad exploration, create or repair the smallest real compatible artifact, script, executable, query, model file, or output at the first still-untouched path using visible task data and current evidence. Then run one bounded visible check that proves the artifact exists at the expected path and is non-empty, syntactically loadable, has the expected shape, or exposes the next exact verifier-relevant mismatch. This is recovery guidance only, not a loop stop condition, and not driven by time, round, turn, token, max_turns, timeout, dependency-failure count, checkpoint count, attempt count, cap, or budget metadata."
    );
    state.append_user_message(message);
    state.append_trajectory(json!({
        "type": "dependency_artifact_first_checkpoint",
        "turn": state.turn_count,
        "untouched_deliverable_paths": untouched,
        "touched_deliverable_paths": state.touched_deliverables.iter().cloned().collect::<Vec<_>>(),
        "dependency_checkpoint_count": state.dependency_checkpoint_count,
        "dependency_artifact_first_checkpoint_count": state.dependency_artifact_first_checkpoint_count,
        "deliverable_checkpoint_count": state.deliverable_checkpoint_count,
        "tool_calls_since_deliverable_touch": state.tool_calls_since_deliverable_touch,
        "read_only_tool_calls_since_progress": state.read_only_tool_calls_since_progress,
        "deliverable_checkpoint_cooldown_turns_audit_only": state.thresholds.deliverable_checkpoint_cooldown_turns,
        "deliverable_checkpoint_max_audit_only": state.thresholds.deliverable_checkpoint_max,
        "loop_stop_condition": false,
        "dependency_failure_count_stop_condition": false,
        "dependency_checkpoint_count_stop_condition": false,
        "artifact_first_stop_condition": false,
        "deliverable_checkpoint_max_stop_condition": false,
        "checkpoint_cooldown_stop_condition": false,
        "time_round_token_limit_driven": false,
        "timeout_stop_condition": false,
        "attempt_count_stop_condition": false,
        "cap_count_budget_stop_condition": false,
        "token_budget_stop_condition": false,
        "budget_stop_condition": false,
    }));
    state.dependency_artifact_first_checkpoint_count += 1;
    true
}

