fn tool_call_touches_image_similarity_artifact(
    tool_name: &str,
    args: &Value,
    result: &ToolResponse,
) -> Option<String> {
    if tool_name == "write" || tool_name == "edit" {
        let file_path = args.get("file_path").and_then(Value::as_str).unwrap_or("");
        if text_names_image_similarity_artifact(file_path) {
            return Some(normalize_image_similarity_artifact_path(file_path));
        }
        return None;
    }
    if tool_name != "bash" {
        return None;
    }
    let command = args.get("command").and_then(Value::as_str).unwrap_or("");
    let combined = format!("{command}\n{}", result.output);
    if !text_mentions_image_similarity_artifact_mutation(&combined) {
        return None;
    }
    image_similarity_path_from_text(&combined)
        .or_else(|| image_similarity_path_from_text(command))
        .or_else(|| image_similarity_path_from_text(&result.output))
        .or_else(|| Some("changed image/render artifact".to_string()))
}

fn text_names_image_similarity_artifact(text: &str) -> bool {
    image_similarity_path_from_text(text).is_some()
}

fn text_mentions_image_similarity_artifact_mutation(text: &str) -> bool {
    let lowered = text.to_ascii_lowercase();
    text_names_image_similarity_artifact(&lowered)
        && (artifact_context_mentions_write_or_change(&lowered)
            || lowered.contains("image.save(")
            || lowered.contains("savefig(")
            || lowered.contains("imwrite(")
            || lowered.contains("ppm") && text_mentions_open_write_mode(&lowered)
            || lowered.contains("png") && text_mentions_open_write_mode(&lowered)
            || lowered.contains("jpg") && text_mentions_open_write_mode(&lowered)
            || lowered.contains("jpeg") && text_mentions_open_write_mode(&lowered)
            || lowered.contains("tga") && text_mentions_open_write_mode(&lowered)
            || lowered.contains("chroot")
            || lowered.contains("./image")
            || lowered.contains("/image")
            || lowered.contains("/reverse")
            || lowered.contains("povray"))
}

fn image_similarity_path_from_text(text: &str) -> Option<String> {
    let mut candidates = Vec::new();
    candidates.extend(image_similarity_write_target_candidates(text));
    for token in shell_tokens(text) {
        if looks_like_image_artifact_extension(&token)
            || token.to_ascii_lowercase().ends_with(".tga")
        {
            candidates.push(normalize_image_similarity_artifact_path(&token));
        }
    }
    for raw in text.split(|ch: char| ch.is_whitespace() || matches!(ch, ',' | ';' | ')' | '(')) {
        let trimmed = raw.trim_matches(|ch: char| {
            matches!(ch, '`' | '\'' | '"' | '[' | ']' | '{' | '}' | ':' | '.')
        });
        if looks_like_image_artifact_extension(trimmed)
            || trimmed.to_ascii_lowercase().ends_with(".tga")
        {
            candidates.push(normalize_image_similarity_artifact_path(trimmed));
        }
    }
    choose_image_similarity_artifact_path(candidates)
}

fn choose_image_similarity_artifact_path(candidates: Vec<String>) -> Option<String> {
    let mut normalized = Vec::new();
    for candidate in candidates {
        let path = normalize_image_similarity_artifact_path(&candidate);
        if path.is_empty()
            || !(looks_like_image_artifact_extension(&path)
                || path.to_ascii_lowercase().ends_with(".tga"))
        {
            continue;
        }
        let lowered = path.to_ascii_lowercase();
        if lowered.starts_with("/tests/") || lowered.contains("/tests/") {
            continue;
        }
        if !normalized.contains(&path) {
            normalized.push(path);
        }
    }
    normalized
        .iter()
        .find(|path| {
            let lowered = path.to_ascii_lowercase();
            lowered.starts_with("/app/")
                && !matches!(
                    Path::new(&lowered)
                        .file_name()
                        .and_then(|value| value.to_str()),
                    Some("original.ppm") | Some("reference.ppm") | Some("expected.ppm")
                )
        })
        .cloned()
        .or_else(|| {
            normalized
                .iter()
                .find(|path| path.starts_with("/jail/"))
                .cloned()
        })
        .or_else(|| normalized.iter().find(|path| path.contains('/')).cloned())
        .or_else(|| normalized.first().cloned())
}

fn image_similarity_write_target_candidates(text: &str) -> Vec<String> {
    let mut candidates = Vec::new();
    for marker in ["image.save(", "savefig(", "imwrite(", "open("] {
        let mut search = 0usize;
        let lowered = text.to_ascii_lowercase();
        while let Some(offset) = lowered[search..].find(marker) {
            let start = search + offset + marker.len();
            let segment = &text[start..text.len().min(start + 260)];
            if marker == "open(" && !text_segment_mentions_any_write_mode(segment) {
                search = start;
                continue;
            }
            if let Some(path) = first_image_path_literal(segment) {
                candidates.push(path);
            }
            search = start;
        }
    }
    for marker in [">", "tee ", "-o ", "-o"] {
        let mut search = 0usize;
        while let Some(offset) = text[search..].find(marker) {
            let start = search + offset + marker.len();
            let token = text[start..].split_whitespace().next().unwrap_or("");
            if looks_like_image_artifact_extension(token)
                || token.to_ascii_lowercase().ends_with(".tga")
            {
                candidates.push(normalize_image_similarity_artifact_path(token));
            }
            search = start;
        }
    }
    candidates
}

fn first_image_path_literal(segment: &str) -> Option<String> {
    for quote in ['\'', '"'] {
        let mut search = 0usize;
        while let Some(offset) = segment[search..].find(quote) {
            let start = search + offset + quote.len_utf8();
            let Some(end_offset) = segment[start..].find(quote) else {
                break;
            };
            let value = &segment[start..start + end_offset];
            if looks_like_image_artifact_extension(value)
                || value.to_ascii_lowercase().ends_with(".tga")
            {
                return Some(normalize_image_similarity_artifact_path(value));
            }
            search = start + end_offset + quote.len_utf8();
        }
    }
    None
}

fn text_mentions_open_write_mode(lowered: &str) -> bool {
    let mut search = 0usize;
    while let Some(offset) = lowered[search..].find("open(") {
        let start = search + offset + "open(".len();
        let segment = &lowered[start..lowered.len().min(start + 260)];
        if text_segment_mentions_any_write_mode(segment) {
            return true;
        }
        search = start;
    }
    false
}

fn text_segment_mentions_any_write_mode(segment: &str) -> bool {
    let lowered = segment.to_ascii_lowercase();
    [
        ", 'w",
        ",'w",
        ", \"w",
        ",\"w",
        ", 'wb",
        ",'wb",
        ", \"wb",
        ",\"wb",
        ", 'a",
        ",'a",
        ", \"a",
        ",\"a",
        "mode='w",
        "mode = 'w",
        "mode=\"w",
        "mode = \"w",
        "mode='wb",
        "mode = 'wb",
        "mode=\"wb",
        "mode = \"wb",
    ]
    .iter()
    .any(|needle| lowered.contains(needle))
}

fn normalize_image_similarity_artifact_path(path: &str) -> String {
    path.trim_matches(|ch: char| matches!(ch, '`' | '\'' | '"' | ',' | ';' | ':' | ')' | ']' | '}'))
        .to_string()
}

fn is_image_similarity_preflight_command(tool_name: &str, args: &Value) -> bool {
    if tool_name != "verify" && tool_name != "bash" {
        return false;
    }
    let command = args.get("command").and_then(Value::as_str).unwrap_or("");
    let lowered = command.to_ascii_lowercase();
    if !text_names_image_similarity_artifact(&lowered) {
        return false;
    }
    let inspects_header_or_shape = lowered.contains("head -")
        || lowered.contains("file ")
        || lowered.contains("identify ")
        || lowered.contains("xxd")
        || lowered.contains("pnmfile")
        || lowered.contains("readline")
        || lowered.contains("dimensions")
        || lowered.contains("shape")
        || lowered.contains("size")
        || lowered.contains("mode")
        || lowered.contains("getbands")
        || lowered.contains("maxval")
        || lowered.contains("max value");
    let reads_generated_pixels = image_similarity_preflight_reads_generated_pixels(&lowered);
    let samples_or_compares_pixels = reads_generated_pixels
        && (lowered.contains("sampled pixel")
            || lowered.contains("sampled pixels")
            || lowered.contains("pixel sample")
            || lowered.contains("region") && lowered.contains("pixel")
            || lowered.contains("getpixel")
            || lowered.contains("getdata")
            || lowered.contains("np.array")
            || lowered.contains("flatten")
            || lowered.contains("cosine")
            || lowered.contains("ssim")
            || lowered.contains("similarity")
            || lowered.contains("dot(")
            || lowered.contains("sum(") && lowered.contains("pixel")
            || lowered.contains("max diff")
            || lowered.contains("mean squared")
            || lowered.contains("l2"));
    let checks_result = lowered.contains("assert")
        || lowered.contains("raise assertionerror")
        || lowered.contains("pass")
        || lowered.contains("exit 1")
        || lowered.contains(">0.995")
        || lowered.contains("> 0.995")
        || lowered.contains("==")
        || lowered.contains("<=")
        || lowered.contains(">=");
    inspects_header_or_shape && samples_or_compares_pixels && checks_result
}

fn image_similarity_preflight_reads_generated_pixels(lowered: &str) -> bool {
    let pillow_pixel_read = (lowered.contains("image.open(")
        || lowered.contains("pil.image.open("))
        && (lowered.contains("np.array")
            || lowered.contains("numpy.array")
            || lowered.contains("getdata")
            || lowered.contains("getpixel")
            || lowered.contains(".crop(")
            || lowered.contains("flatten"));
    let iterates_file_pixels = (lowered.contains("for value in line.split")
        || lowered.contains("for value in row.split")
        || lowered.contains("for value in data.split")
        || lowered.contains("for value in payload.split"))
        && (lowered.contains("for index, line in enumerate(f)")
            || lowered.contains("for line in f")
            || lowered.contains("for row in f")
            || lowered.contains("f.read()")
            || lowered.contains("data = f.read")
            || lowered.contains("payload = f.read"));
    let raw_pixel_read = (lowered.contains(".open(") || lowered.contains("open("))
        && (lowered.contains("sampled_pixels.extend") || lowered.contains("sampled_pixels.append"))
        && (iterates_file_pixels
            || lowered.contains("np.frombuffer")
            || lowered.contains("numpy.frombuffer"));
    let array_pixel_read = (lowered.contains("np.asarray")
        || lowered.contains("numpy.asarray")
        || lowered.contains("np.array")
        || lowered.contains("numpy.array"))
        && (lowered.contains("image.open(") || lowered.contains("pil.image.open("));
    pillow_pixel_read || raw_pixel_read || array_pixel_read
}

