fn sql_limit_at_most(text: &str, max_value: f64) -> bool {
    let mut offset = 0;
    while let Some(found) = text[offset..].find("limit") {
        let absolute = offset + found;
        let before_ok = text[..absolute]
            .chars()
            .next_back()
            .is_none_or(|ch| !ch.is_ascii_alphanumeric() && ch != '_');
        let after_start = absolute + "limit".len();
        let after_ok = text[after_start..]
            .chars()
            .next()
            .is_none_or(|ch| !ch.is_ascii_alphanumeric() && ch != '_');
        if before_ok && after_ok {
            let numeric = text[after_start..]
                .trim_start_matches(|ch: char| ch.is_whitespace() || ch == '=' || ch == '(')
                .chars()
                .take_while(|ch| ch.is_ascii_digit() || *ch == '.')
                .collect::<String>();
            if !numeric.is_empty()
                && numeric
                    .parse::<f64>()
                    .ok()
                    .is_some_and(|value| value <= max_value)
            {
                return true;
            }
        }
        offset = after_start;
    }
    false
}

