fn command_looks_like_directory_listing(command: &str) -> bool {
    let lowered = command.to_ascii_lowercase();
    let tokens = shell_tokens_preserve_paths(&lowered);
    if tokens.is_empty() {
        return false;
    }
    if tokens
        .iter()
        .any(|token| matches!(token.as_str(), "sleep" | "while" | "wait"))
    {
        return false;
    }
    if lowered.contains("| head")
        || lowered.contains("| tail")
        || lowered.contains("--max-depth")
        || lowered.contains("-maxdepth")
    {
        return false;
    }
    if command_targets_specific_file(&tokens) {
        return false;
    }
    let has_listing_tool = tokens
        .iter()
        .any(|token| matches!(token.as_str(), "ls" | "du" | "tree" | "find"));
    if !has_listing_tool {
        return false;
    }
    let broad_listing_flag = tokens.iter().any(|token| {
        matches!(token.as_str(), "-r" | "-la" | "-al" | "-lra" | "-ral")
            || token.starts_with("--recursive")
    });
    let explicit_directory = tokens.iter().any(|token| {
        token.ends_with('/')
            || matches!(
                token.as_str(),
                "." | ".." | "/" | "/app" | "/tmp" | "/var" | "/usr" | "/home"
            )
            || token.starts_with("/app/")
            || token.starts_with("/tmp/")
            || token.starts_with("/var/")
            || token.starts_with("/usr/")
            || token.starts_with("/home/")
    });
    let find_directory_walk = tokens.iter().any(|token| token == "find") && explicit_directory;
    let plain_directory_ls = tokens.iter().any(|token| token == "ls") && explicit_directory;
    let directory_du = tokens.iter().any(|token| token == "du") && explicit_directory;
    let tree_directory_walk = tokens.iter().any(|token| token == "tree") && explicit_directory;
    plain_directory_ls
        || directory_du
        || tree_directory_walk
        || (broad_listing_flag && explicit_directory)
        || find_directory_walk
}

fn command_targets_specific_file(tokens: &[String]) -> bool {
    let file_suffixes = [
        ".c", ".cc", ".cpp", ".csv", ".json", ".jsonl", ".log", ".md", ".ml", ".py", ".rs", ".txt",
        ".yaml", ".yml",
    ];
    tokens
        .iter()
        .any(|token| file_suffixes.iter().any(|suffix| token.ends_with(suffix)))
}

