    fn assert_worker_policy_guard_is_non_terminal(metadata: &Value) {
        for key in [
            "policy_guard_stop_condition",
            "operation_guard_stop_condition",
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "max_turns_stop_condition",
            "timeout_seconds_stop_condition",
            "round_limit_stop_condition",
            "attempt_count_stop_condition",
            "budget_stop_condition",
        ] {
            assert_eq!(
                metadata.get(key).and_then(Value::as_bool),
                Some(false),
                "policy guard metadata should mark {key}=false"
            );
        }
    }

    fn assert_worker_policy_event_is_non_terminal(event: &Value) {
        for key in [
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "max_turns_stop_condition",
            "timeout_seconds_stop_condition",
            "round_limit_stop_condition",
            "checkpoint_count_stop_condition",
            "checkpoint_cooldown_stop_condition",
            "attempt_count_stop_condition",
            "budget_stop_condition",
        ] {
            if event.get(key).is_some() {
                assert_eq!(
                    event.get(key).and_then(Value::as_bool),
                    Some(false),
                    "worker policy event should mark {key}=false"
                );
            }
        }
    }

    #[test]
    fn bounded_entrypoint_scan_command_includes_visible_verifier_surface() {
        let command = bounded_entrypoint_scan_command();

        assert!(command.contains("Likely entrypoints:"));
        assert!(command.contains("/tests"));
        assert!(command.contains("Verifier surface files (visible /tests, read-only):"));
        assert!(command.contains("Verifier-facing artifact and command hints"));
        assert!(command.contains("/app/"));
        assert!(command.contains("subprocess[.]run"));
        assert!(command.contains("pmars"));
        assert!(command.contains("gcc"));
        assert!(command.contains("open\\("));
        assert!(command.contains("Path\\("));
        assert!(command.contains("sed -n '1,80p'"));
    }

    #[test]
    fn default_prompts_prohibit_nested_sub_agent_creation() {
        let system = default_system_prompt();
        assert!(system.contains("Only the master HL orchestrator may create sub-agents"));
        assert!(system.contains("must not start Codex"));
        assert!(system.contains("external coding-agent CLI"));
        assert!(system.contains("create nested sub-agents"));

        let task_guidance = default_task_guidance();
        assert!(task_guidance.contains("Only the master HL orchestrator may create sub-agents"));
        assert!(task_guidance.contains("another external coding-agent CLI"));
        assert!(task_guidance.contains("create nested sub-agents"));
    }

    #[test]
    fn bounded_entrypoint_scan_adds_verifier_surface_without_loop_limits() {
        let mut state = worker_state_for_unit_tests();
        state.tool_schemas = vec![json!({"function": {"name": "bash"}})];
        let response = json!({
            "type": "tool_response",
            "payload": {
                "success": true,
                "output": "PWD: /app\n\nLikely entrypoints:\n./README.md\n\nVerifier surface files (visible /tests, read-only):\n/tests/test_outputs.py\n\nVerifier-facing artifact and command hints (visible /tests snippets):\n/tests/test_outputs.py:8:subprocess.run(['pmars', '-b', '-r', '100', '-f', '/app/my_warrior.red'])",
                "error": ""
            }
        });
        let mut stdin = std::io::Cursor::new(format!("{}\n", response));

        let scan = bounded_entrypoint_scan(&mut stdin, &mut state);

        assert!(scan.contains("Bounded entrypoint scan:"));
        assert!(scan.contains("Verifier surface files"));
        assert!(scan.contains("/app/my_warrior.red"));
        let event = latest_event(&state, "entrypoint_scan");
        assert_eq!(
            event
                .get("operation_timeout_seconds_audit_only")
                .and_then(Value::as_u64),
            Some(15)
        );
        assert_eq!(
            event
                .get("entrypoint_scan_loop_stop_condition")
                .and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(
            event
                .get("master_loop_stop_condition")
                .and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(
            event
                .get("sub_agent_loop_stop_condition")
                .and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(
            event
                .get("time_round_limit_stop_condition")
                .and_then(Value::as_bool),
            Some(false)
        );
    }

    fn count_events(state: &WorkerState, event_type: &str) -> usize {
        state
            .trajectory
            .iter()
            .filter(|event| event.get("type").and_then(Value::as_str) == Some(event_type))
            .count()
    }

    fn latest_event<'a>(state: &'a WorkerState, event_type: &str) -> &'a Value {
        state
            .trajectory
            .iter()
            .rev()
            .find(|event| event.get("type").and_then(Value::as_str) == Some(event_type))
            .expect("expected trajectory event")
    }

    #[test]
    fn extracts_relevant_deliverable_paths_from_instruction_and_context() {
        let context = json!({
            "completion_condition": "Expected output file named result.csv must exist.",
            "environment_context": "Do not modify /tests/test_task.py",
            "previous_errors": ["missing /app/recovered.json"]
        });

        let targets = extract_deliverable_targets(
            "Create /app/recovered.json and save the final table to result.csv.",
            &context,
        );

        assert!(targets.contains(&"/app/recovered.json".to_string()));
        assert!(targets.contains(&"result.csv".to_string()));
        assert!(!targets.contains(&"/tests/test_task.py".to_string()));
    }

    #[test]
    fn deliverable_extraction_skips_local_training_input_data_paths() {
        let context = json!({
            "completion_condition": "Expected output artifact is /app/model.bin.",
            "environment_context": "Local training data is /app/data/train-00000-of-00001.parquet with text and label columns."
        });

        let targets = extract_deliverable_targets(
            "Train a fastText classifier from /app/data/train-00000-of-00001.parquet and save /app/model.bin.",
            &context,
        );

        assert!(targets.contains(&"/app/model.bin".to_string()));
        assert!(!targets.contains(&"/app/data/train-00000-of-00001.parquet".to_string()));
    }

    #[test]
    fn read_only_python_is_not_workspace_mutation_but_writes_are() {
        assert!(!command_likely_mutates_workspace(
            "python3 <<'PY'\nprint('inspect only')\nPY"
        ));
        assert!(command_likely_mutates_workspace(
            "python3 -c \"open('/app/out.txt', 'w').write('x')\""
        ));
    }

    #[test]
    fn done_tool_call_triggers_completion_but_prose_does_not() {
        let done = vec![json!({ "tool": "done", "success": true })];
        assert!(done_tool_requested(&done));

        // A failed done call must not trigger completion.
        let failed = vec![json!({ "tool": "done", "success": false })];
        assert!(!done_tool_requested(&failed));

        // Narrative completion words in other tool output are irrelevant now.
        let prose =
            vec![json!({ "tool": "bash", "success": true, "output": "task complete; done" })];
        assert!(!done_tool_requested(&prose));
    }

    fn successful_tool_response(output: &str) -> ToolResponse {
        ToolResponse {
            success: true,
            output: output.to_string(),
            error: String::new(),
            duration_ms: 0.0,
            metadata: json!({}),
        }
    }

    fn failed_tool_response_with_metadata(error: &str, metadata: Value) -> ToolResponse {
        ToolResponse {
            success: false,
            output: String::new(),
            error: error.to_string(),
            duration_ms: 0.0,
            metadata,
        }
    }

    fn pytorch_distributed_spawn_preflight_command() -> String {
        "python3 - <<'PY'\n\
import importlib.util, os, tempfile\n\
import torch\n\
import torch.distributed as dist\n\
import torch.multiprocessing as mp\n\
path = '/app/parallel_linear.py'\n\
spec = importlib.util.spec_from_file_location('parallel_linear', path)\n\
module = importlib.util.module_from_spec(spec)\n\
spec.loader.exec_module(module)\n\
def worker(rank, world_size, init_file):\n\
    dist.init_process_group('gloo', init_method=f'file://{init_file}', rank=rank, world_size=world_size)\n\
    try:\n\
        layer = module.ColumnParallelLinear(4, 8, bias=True)\n\
        x = torch.ones(2, 4)\n\
        y = layer(x)\n\
        gathered = [torch.zeros_like(y) for _ in range(world_size)]\n\
        dist.all_gather(gathered, y)\n\
        reduced = y.clone()\n\
        dist.all_reduce(reduced)\n\
        assert rank < world_size\n\
        assert y.shape[0] == 2\n\
        assert len(gathered) == world_size\n\
        assert reduced.shape == y.shape\n\
        assert layer is not None and world_size in (1, 2, 4)\n\
    finally:\n\
        dist.destroy_process_group()\n\
world_size = 2\n\
with tempfile.NamedTemporaryFile(delete=False) as f:\n\
    init_file = f.name\n\
os.unlink(init_file)\n\
mp.spawn(worker, args=(world_size, init_file), nprocs=world_size, join=True)\n\
print('pytorch distributed mp.spawn preflight passed')\n\
PY"
            .to_string()
    }

