    fn regex_rule_artifact_preflight_command() -> String {
        "python3 - <<'PY'\n\
import json, re\n\
def replacement_refs(repl):\n\
    numeric_refs = []\n\
    named_refs = []\n\
    ambiguous_numeric_refs = []\n\
    i = 0\n\
    while i < len(repl):\n\
        if repl[i] != '\\\\':\n\
            i += 1\n\
            continue\n\
        if i + 1 >= len(repl):\n\
            break\n\
        nxt = repl[i + 1]\n\
        if nxt == 'g' and i + 2 < len(repl) and repl[i + 2] == '<':\n\
            end = repl.find('>', i + 3)\n\
            assert end != -1, (repl, i)\n\
            target = repl[i + 3:end]\n\
            if target.isdigit():\n\
                numeric_refs.append(int(target))\n\
            else:\n\
                named_refs.append(target)\n\
            i = end + 1\n\
            continue\n\
        if nxt.isdigit() and nxt != '0':\n\
            j = i + 1\n\
            while j < len(repl) and repl[j].isdigit():\n\
                j += 1\n\
            digits = repl[i + 1:j]\n\
            numeric_refs.append(int(digits))\n\
            if len(digits) > 1:\n\
                ambiguous_numeric_refs.append('\\\\' + digits)\n\
            i = j\n\
            continue\n\
        i += 2\n\
    return numeric_refs, named_refs, ambiguous_numeric_refs\n\
problems = []\n\
rules = json.load(open('/app/re.json'))\n\
assert rules, 'empty /app/re.json rule set'\n\
for pattern_text, repl in rules:\n\
    pattern = re.compile(pattern_text)\n\
    print(pattern.groups, pattern.groupindex)\n\
    numeric_refs, named_refs, ambiguous_numeric_refs = replacement_refs(repl)\n\
    for ref in numeric_refs:\n\
        assert 1 <= ref <= pattern.groups, (pattern_text, repl, ref, pattern.groups)\n\
    for name in named_refs:\n\
        assert name in pattern.groupindex, (pattern_text, repl, name, pattern.groupindex)\n\
    assert not ambiguous_numeric_refs, (pattern_text, repl, ambiguous_numeric_refs)\n\
    re._parser.parse_template(repl, pattern)\n\
    pattern.sub(repl, '8/8/8/8/8/8/8/8 w - - 0 1')\n\
PY"
        .to_string()
    }

