    fn state_transition_set_preflight_command() -> String {
        "python3 - <<'PY'\n\
import json, re, chess\n\
rules = json.load(open('/app/re.json'))\n\
assert rules, 'empty /app/re.json rule set'\n\
fen = 'rnbqkbnr/pppp1ppp/8/8/4PpP1/8/PPPP3P/RNBQKBNR b KQkq - 0 1'\n\
board = chess.Board(fen)\n\
legal_next_states = set()\n\
for move in board.legal_moves:\n\
    next_board = board.copy()\n\
    next_board.push(move)\n\
    legal_next_states.add(next_board.fen())\n\
    legal_next_states.add(' '.join(next_board.fen().split()[:4]))\n\
candidate_next_states = set()\n\
for pattern_text, repl in rules:\n\
    generated = re.sub(pattern_text, repl, fen)\n\
    candidate_next_states.add(generated)\n\
    candidate_next_states.add(' '.join(generated.split()[:4]))\n\
assert candidate_next_states, 'empty generated candidate next-state set'\n\
unexpected = candidate_next_states - legal_next_states\n\
assert not unexpected, unexpected\n\
assert board.turn == chess.BLACK\n\
print('legal-transition set preflight passed', legal_next_states)\n\
PY"
        .to_string()
    }

