    fn structured_csv_table_preflight_command(path: &str) -> String {
        format!(
            "python3 - <<'PY'\n\
import csv\n\
try:\n\
    import pandas as pd\n\
    df = pd.read_csv('{path}')\n\
    assert list(df.columns) == ['rgb_path', 'csv_path', 'area', 'bbox', 'width', 'height']\n\
    expected_rows = [{{'rgb_path': 'image_001.png', 'csv_path': 'masks_001.csv'}}]\n\
    assert len(df) == len(expected_rows)\n\
    row = df.iloc[0]\n\
    assert row['rgb_path'] == expected_rows[0]['rgb_path']\n\
    assert row['csv_path'] == expected_rows[0]['csv_path']\n\
    assert str(row['rgb_path']).strip()\n\
    assert str(row['csv_path']).strip()\n\
    assert str(row['bbox']).strip()\n\
    assert pd.to_numeric(df['area']).notna().all()\n\
    print(df.dtypes)\n\
except ImportError:\n\
    with open('{path}', newline='') as f:\n\
        reader = csv.DictReader(f)\n\
        assert reader.fieldnames == ['rgb_path', 'csv_path', 'area', 'bbox', 'width', 'height']\n\
        rows = list(reader)\n\
        expected_rows = [{{'rgb_path': 'image_001.png', 'csv_path': 'masks_001.csv'}}]\n\
        assert len(rows) == len(expected_rows)\n\
        row = rows[0]\n\
        assert row['rgb_path'] == expected_rows[0]['rgb_path']\n\
        assert row['csv_path'] == expected_rows[0]['csv_path']\n\
        assert row['rgb_path'].strip() and row['csv_path'].strip()\n\
        assert row['bbox'].strip()\n\
        assert int(float(row['area'])) >= 0\n\
print('structured csv preflight passed')\n\
PY"
        )
    }

