    fn dna_primer_preflight_command() -> String {
        "python3 - <<'PY'\n\
import math, re\n\
from pathlib import Path\n\
lines = [line.rstrip() for line in Path('/app/primers.fasta').read_text().splitlines()]\n\
assert len(lines) == 4, 'exactly 4 FASTA lines required for one primer pair'\n\
assert lines[0].startswith('>') and lines[2].startswith('>'), 'headers must start with >'\n\
fwd_primer = lines[1].lower()\n\
rev_primer = lines[3].lower()\n\
assert re.fullmatch(r'[atcg]+', fwd_primer), 'ATCG-only forward'\n\
assert re.fullmatch(r'[atcg]+', rev_primer), 'ATCG-only reverse'\n\
def rc(seq):\n\
    return seq.translate(str.maketrans('atcg', 'tagc'))[::-1]\n\
def tm(seq):\n\
    return 64.9 + 41 * (seq.count('g') + seq.count('c') - 16.4) / len(seq)\n\
insert = 'tagattagaagaagaattaagaagaagattaacagaaagc'\n\
primers_concat = rc(rev_primer) + fwd_primer\n\
insert_start = primers_concat.find(insert)\n\
assert insert_start != -1, 'inserted DNA present'\n\
annealed_rev = primers_concat[:insert_start]\n\
annealed_fwd = primers_concat[insert_start + len(insert):]\n\
vector1 = 'aagggcgaggagctgttcac' + annealed_rev\n\
vector2 = annealed_fwd + 'tttgtttaactttaagaagg'\n\
assert vector1.endswith(annealed_rev), 'vector1 suffix overlap'\n\
assert vector2.startswith(annealed_fwd), 'vector2 prefix overlap'\n\
assert 15 <= len(annealed_rev) <= 45 and 15 <= len(annealed_fwd) <= 45, 'overlap 15..45'\n\
fwd_tm, rev_tm = tm(fwd_primer), tm(rev_primer)\n\
assert 58 <= fwd_tm <= 72 and 58 <= rev_tm <= 72, 'Tm 58..72'\n\
assert abs(fwd_tm - rev_tm) <= 5, 'Tm delta within 5 C'\n\
print('dna primer preflight passed', len(annealed_rev), len(annealed_fwd), fwd_tm, rev_tm)\n\
PY"
        .to_string()
    }

