    fn dna_assembly_primer_preflight_command() -> String {
        "python3 - <<'PY'\n\
import re\n\
from pathlib import Path\n\
lines = [line.rstrip() for line in Path('/app/primers.fasta').read_text().splitlines()]\n\
assert len(lines) == 16, 'exactly 16 FASTA lines'\n\
headers = lines[0::2]\n\
seqs = [seq.lower() for seq in lines[1::2]]\n\
assert all(header.startswith('>') for header in headers), 'headers must start with >'\n\
def parse_bsai_primer(primer):\n\
    assert re.fullmatch(r'[atcg]+', primer), 'ATCG-only primer'\n\
    site = primer.find('ggtctc')\n\
    assert site >= 1, 'clamp before ggtctc'\n\
    overhang = primer[site + 6:site + 10]\n\
    binding = primer[site + 10:]\n\
    assert len(overhang) == 4, 'four-base overhang'\n\
    assert binding, 'binding sequence after overhang'\n\
    return overhang, binding\n\
def make_fragment(fwd, rev):\n\
    f_overhang, f_binding = parse_bsai_primer(fwd)\n\
    r_overhang, r_binding = parse_bsai_primer(rev)\n\
    return f_overhang + f_binding + r_binding + r_overhang\n\
for seq in seqs:\n\
    parse_bsai_primer(seq)\n\
fragment = make_fragment(seqs[0], seqs[1])\n\
assert fragment and len(fragment) > 12, 'make_fragment fixture'\n\
print('dna assembly primer preflight passed', headers, fragment[:8])\n\
PY"
        .to_string()
    }

