    fn token_substitution_preflight_command() -> String {
        "python3 - <<'PY'\n\
import re\n\
from pathlib import Path\n\
synonyms = {}\n\
for line in Path('/tests/synonyms.txt').read_text().splitlines():\n\
    family = set(line.strip().split(', '))\n\
    for word in family:\n\
        synonyms[word] = family\n\
original = Path('/tests/input.tex').read_text().replace('---', ' --- ')\n\
agent_input = Path('/app/input.tex').read_text().replace('---', ' --- ')\n\
tokens = re.findall(r'\\S+', original)\n\
tokens_agent = re.findall(r'\\S+', agent_input)\n\
assert len(tokens) == len(tokens_agent), 'token count mismatch'\n\
for token, token_agent in zip(tokens, tokens_agent):\n\
    match = re.match(r'^(\\W*)(.*?)(\\W*)$', token)\n\
    match_agent = re.match(r'^(\\W*)(.*?)(\\W*)$', token_agent)\n\
    p, w, s = match.groups()\n\
    p_agent, w_agent, s_agent = match_agent.groups()\n\
    assert p == p_agent and s == s_agent, 'punctuation mismatch'\n\
    assert w == w_agent or (w in synonyms and w_agent in synonyms[w]), 'same synonym family mismatch'\n\
print('token-by-token same synonym family preflight passed')\n\
PY"
            .to_string()
    }

    fn dataset_shard_generalization_preflight_command() -> String {
        "python3 - <<'PY'\n\
import gzip, json, tempfile\n\
from pathlib import Path\n\
root = Path(tempfile.mkdtemp())\n\
shard_paths = [\n\
    root / 'c4-train.00000-of-00002.json.gz',\n\
    root / 'c4-train.00001-of-00002.json.gz',\n\
]\n\
records = [\n\
    [{'text': 'alpha beta', 'timestamp': '1'}],\n\
    [{'text': 'gamma', 'timestamp': '2'}],\n\
]\n\
for shard, rows in zip(shard_paths, records):\n\
    with gzip.open(shard, 'wt') as f:\n\
        for record in rows:\n\
            f.write(json.dumps(record) + '\\n')\n\
def process_shard(path):\n\
    out = []\n\
    with gzip.open(path, 'rt') as f:\n\
        for line in f:\n\
            record = json.loads(line)\n\
            assert set(record) == {'text', 'timestamp'}, 'json schema'\n\
            out.append(record['text'])\n\
    return out\n\
all_records = []\n\
for shard in shard_paths:\n\
    all_records.extend(process_shard(shard))\n\
assert all_records == ['alpha beta', 'gamma'], 'record order count schema'\n\
answer = root / 'answer.txt'\n\
answer.write_text(str(sum(len(text.split()) for text in all_records)))\n\
assert answer.read_text() == '3', 'answer output content'\n\
print('multi-shard gzip jsonl c4-train shard_paths preflight passed')\n\
PY"
        .to_string()
    }

