    #[test]
    fn state_transition_preflight_checkpoint_uses_visible_failing_fen_fixture() {
        let mut state = worker_state_for_unit_tests();
        state.task_context = json!({
            "task_id": "regex-chess",
            "previous_errors": [
                "Position: {fen}, Our move: {x} not found in Python-chess moves",
                "E       AssertionError: Position: rnbqkbnr/pppp1ppp/8/8/4PpP1/8/PPPP3P/RNBQKBNR b KQkq - 0 1, Our move: rnbqkbnr/pppp1ppp/8/8/4PpP1/8/PPPP3P/RNBQKBNR b KQkq - not found in Python-chess moves: ['f4g3', 'f4e3']",
                "state_transition_set_contract: generated next state must be a member of the verifier legal-transition set; preserve castling rights, en-passant target, side-to-move, and in-check legality"
            ]
        });
        state.state_transition_set_preflight_required =
            extract_state_transition_set_preflight_required(
                &state.task_instruction,
                &state.task_context,
            );
        state.turn_count = 3;

        record_tool_progress(
            &mut state,
            "write",
            &json!({"file_path": "/app/re.json", "content": "[]"}),
            &successful_tool_response("wrote /app/re.json"),
        );

        assert!(maybe_inject_state_transition_set_preflight_checkpoint(
            &mut state
        ));
        let event = latest_event(&state, "state_transition_set_preflight_checkpoint");
        let examples = event
            .get("state_transition_set_examples")
            .and_then(Value::as_array)
            .expect("visible state-transition examples");
        let example = examples[0].as_str().unwrap();
        assert!(example
            .contains("Position/FEN `rnbqkbnr/pppp1ppp/8/8/4PpP1/8/PPPP3P/RNBQKBNR b KQkq - 0 1`"));
        assert!(example.contains(
            "generated candidate `rnbqkbnr/pppp1ppp/8/8/4PpP1/8/PPPP3P/RNBQKBNR b KQkq -`"
        ));
        assert_eq!(
            event
                .get("state_transition_set_examples_stop_condition")
                .and_then(Value::as_bool),
            Some(false)
        );
        let contracts = event
            .get("state_transition_set_contracts")
            .and_then(Value::as_array)
            .expect("visible state-transition contracts");
        assert!(contracts[0]
            .as_str()
            .unwrap()
            .contains("legal-transition set"));
        assert_eq!(
            event
                .get("state_transition_set_contracts_stop_condition")
                .and_then(Value::as_bool),
            Some(false)
        );

        let message = state.messages.last().unwrap()["content"].as_str().unwrap();
        assert!(message.contains("Visible failing transition fixture(s)"));
        assert!(message.contains("rnbqkbnr/pppp1ppp/8/8/4PpP1/8/PPPP3P/RNBQKBNR b KQkq - 0 1"));
        assert!(message.contains("Use these exact Position/FEN and generated candidate values"));
        assert!(message.contains("Visible state-transition contract(s)"));
        assert!(message.contains("legal-transition membership check"));
        assert!(
            message.contains("instead of using only a generic empty-board or synthetic smoke case")
        );
        assert!(message.contains("not a master, sub-agent, or Worker loop stop condition"));
    }

