    #[test]
    fn state_transition_preflight_rejects_san_only_legal_move_set() {
        let weak_command = "python3 - <<'PY'\n\
import json, re, chess\n\
rules = json.load(open('/app/re.json'))\n\
fen = 'rnbqkbnr/pppp1ppp/8/8/4PpP1/8/PPPP3P/RNBQKBNR b KQkq - 0 1'\n\
board = chess.Board(fen)\n\
legal_set = {board.san(move) for move in board.legal_moves}\n\
candidate_next_states = set()\n\
for pattern_text, repl in rules:\n\
    candidate_next_states.add(re.sub(pattern_text, repl, fen))\n\
unexpected = candidate_next_states - legal_set\n\
assert not unexpected, unexpected\n\
print('legal-transition set preflight passed', legal_set)\n\
PY";

        assert!(!is_state_transition_set_preflight_command(
            "verify",
            &json!({"command": weak_command})
        ));

        let mut state = worker_state_for_unit_tests();
        state.state_transition_set_preflight_required = true;
        state.turn_count = 5;
        record_tool_progress(
            &mut state,
            "write",
            &json!({"file_path": "/app/re.json", "content": "[]"}),
            &successful_tool_response("wrote /app/re.json"),
        );
        state.last_regex_rule_artifact_preflight_turn = state.regex_rule_artifact_touched_turn;

        state.turn_count = 6;
        record_tool_progress(
            &mut state,
            "verify",
            &json!({"command": weak_command}),
            &successful_tool_response("legal-transition set preflight passed"),
        );

        assert_eq!(state.last_state_transition_set_preflight_turn, 0);
        assert!(state_transition_set_preflight_pending(&state));
    }

