        assert!(state.state_transition_set_preflight_required);
        assert!(state_transition_set_preflight_pending(&state));

        state.turn_count = 2;
        assert!(maybe_inject_regex_rule_artifact_preflight_checkpoint(
            &mut state
        ));
        let regex_checkpoint = latest_event(&state, "regex_rule_artifact_preflight_checkpoint");
