    #[test]
    fn sam_cell_structured_csv_preflight_requires_coordinate_sequence_parsing() {
        let mut state = worker_state_for_unit_tests();
        state.task_context = json!({
            "task_id": "sam-cell-seg",
            "verifier_output": "FAILED ../tests/test_outputs.py::test_demo_metadata_csv_content\n\
        def test_demo_metadata_csv_content():\n\
        df = pd.read_csv(args.csv_path)\n\
        assert len(df) == 48\n\
        for _, row in df.iterrows():\n\
        assert row['type'] == 'polyline'\n\
        Columns: ['Unnamed: 0', 'raw_classification', 'main_classification', 'super_classification', 'type', 'xmin', 'ymin', 'xmax', 'ymax', 'coords_x', 'coords_y']\n\
        1\t,raw_classification,main_classification,super_classification,type,xmin,ymin,xmax,ymax,coords_x,coords_y",
        });

        state.turn_count = 4;
        record_tool_progress(
            &mut state,
            "write",
            &json!({"file_path": "/app/demo_metadata.csv", "content": ",raw_classification,main_classification,super_classification,type,xmin,ymin,xmax,ymax,coords_x,coords_y\n0,cell,cell,cell,polyline,1,1,4,4,\"[1,2,3,1]\",\"[1,1,3,3]\"\n"}),
            &successful_tool_response("wrote /app/demo_metadata.csv"),
        );

        let weak_coords_checker = "python3 - <<'PY'\n\
import csv\n\
try:\n\
    import pandas as pd\n\
    df = pd.read_csv('/app/demo_metadata.csv')\n\
    expected_columns = ['Unnamed: 0', 'raw_classification', 'main_classification', 'super_classification', 'type', 'xmin', 'ymin', 'xmax', 'ymax', 'coords_x', 'coords_y']\n\
    assert list(df.columns) == expected_columns\n\
    expected_rows = [{'type': 'polyline'}]\n\
    assert len(df) == len(expected_rows)\n\
    row = df.iloc[0]\n\
    assert str(row['type']) == 'polyline'\n\
    assert str(row['raw_classification']).strip()\n\
    assert str(row['coords_x']).strip() and str(row['coords_y']).strip()\n\
    for column in ['xmin', 'ymin', 'xmax', 'ymax']:\n\
        assert pd.to_numeric(df[column]).notna().all()\n\
except ImportError:\n\
    with open('/app/demo_metadata.csv', newline='') as f:\n\
        reader = csv.DictReader(f)\n\
        assert reader.fieldnames == ['', 'raw_classification', 'main_classification', 'super_classification', 'type', 'xmin', 'ymin', 'xmax', 'ymax', 'coords_x', 'coords_y']\n\
        rows = list(reader)\n\
        assert len(rows) == 1\n\
        row = rows[0]\n\
        assert row['type'] == 'polyline'\n\
        assert row['coords_x'].strip() and row['coords_y'].strip()\n\
        assert int(float(row['xmin'])) <= int(float(row['xmax']))\n\
        assert int(float(row['ymin'])) <= int(float(row['ymax']))\n\
print('structured csv preflight passed')\n\
PY";

        assert!(is_structured_csv_table_preflight_command(
            "verify",
            &json!({"command": weak_coords_checker})
        ));
        assert!(!is_structured_csv_table_preflight_command_for_state(
            &state,
            "verify",
            &json!({"command": weak_coords_checker})
        ));

        state.turn_count = 5;
        record_tool_progress(
            &mut state,
            "verify",
            &json!({"command": weak_coords_checker}),
            &successful_tool_response("structured csv preflight passed"),
        );

        assert_eq!(state.last_structured_csv_table_preflight_turn, 0);
        assert!(structured_csv_table_preflight_pending(&state));
        let mismatch = latest_event(&state, "structured_csv_table_preflight_schema_mismatch");
        assert_eq!(
            mismatch.get("loop_stop_condition").and_then(Value::as_bool),
            Some(false)
        );

        let strong_checker =
            sam_cell_structured_csv_table_preflight_command("/app/demo_metadata.csv");
        assert!(is_structured_csv_table_preflight_command_for_state(
            &state,
            "verify",
            &json!({"command": strong_checker})
        ));
    }

