    #[test]
    fn structured_csv_preflight_dependency_guard_allows_focused_artifact_checks() {
        let mut state = worker_state_for_unit_tests();
        state.task_context = json!({
            "task_id": "sam-cell-seg",
            "previous_errors": [
                "df = pd.read_csv(args.csv_path)\nFailure mechanism detail: Verifier loads demo_metadata.csv via pd.read_csv(args.csv_path) as a table and checks keyed row content; repair must preserve columns rgb_path, csv_path, area, bbox, width, height in exact order, row count, key column identity, blank-vs-nonblank cells, numeric/text dtype and formatting where applicable."
            ]
        });
        assert!(structured_csv_table_preflight_pending(&state));

        let stdlib_csv_check = "python3 - <<'PY'\n\
import csv\n\
with open('/app/demo_metadata.csv', newline='') as f:\n\
    reader = csv.DictReader(f)\n\
    assert reader.fieldnames == ['rgb_path', 'csv_path', 'area', 'bbox', 'width', 'height']\n\
    rows = list(reader)\n\
    assert len(rows) >= 1\n\
    row = rows[0]\n\
    assert row['rgb_path'].strip() and row['csv_path'].strip()\n\
    print('csv reader preflight passed')\n\
PY";

        for command in [
            structured_csv_table_preflight_command("/app/demo_metadata.csv"),
            "python3 -m py_compile /app/convert_masks.py".to_string(),
            "test -s /app/demo_metadata.csv && head -1 /app/demo_metadata.csv".to_string(),
            stdlib_csv_check.to_string(),
        ] {
            assert!(
                blocked_structured_csv_preflight_dependency_expansion(
                    &state,
                    "bash",
                    &json!({"command": command}),
                )
                .is_none(),
                "focused CSV/artifact command should be allowed"
            );
        }

        assert!(blocked_structured_csv_preflight_dependency_expansion(
            &state,
            "verify",
            &json!({"command": structured_csv_table_preflight_command("/app/demo_metadata.csv")}),
        )
        .is_none());
        let blocked_local_wheel = blocked_structured_csv_preflight_dependency_expansion(
            &state,
            "bash",
            &json!({"command": "python3 -m pip install --no-index --find-links /app/wheelhouse /app/wheelhouse/task_helper.whl"}),
        )
        .expect("structured CSV guard should keep local wheel installs behind focused CSV preflight");
        assert_eq!(
            blocked_local_wheel
                .metadata
                .get("blocked_reason")
                .and_then(Value::as_str),
            Some("structured_csv_preflight_pending_dependency_setup")
        );
    }

