    #[test]
    fn dataset_shard_contract_injects_preflight_checkpoint_without_loop_limit() {
        let mut state = worker_state_for_unit_tests();
        state.task_context = json!({
            "task_id": "count-dataset-tokens",
            "previous_errors": [
                "dataset_shard_generalization_contract: verifier loads c4-train.00009-of-01024.json.gz through datasets/data_files; solution must generalize beyond the visible shard, process arbitrary C4 gzip JSONL shard names, preserve record boundaries, order, count, and JSON schema, and validate with a tiny synthetic multi-shard fixture instead of hardcoding cache paths or one shard"
            ]
        });
        state.dataset_shard_generalization_preflight_required =
            extract_dataset_shard_generalization_preflight_required(
                &state.task_instruction,
                &state.task_context,
            );
        state.turn_count = 3;

        assert!(state.dataset_shard_generalization_preflight_required);
        assert!(dataset_shard_generalization_preflight_pending(&state));
        assert!(maybe_inject_dataset_shard_generalization_preflight_checkpoint(&mut state));

        let event = latest_event(&state, "dataset_shard_generalization_preflight_checkpoint");
        assert_eq!(
            event
                .get("dataset_shard_generalization_preflight_reference_turn")
                .and_then(Value::as_u64),
            Some(1)
        );
        assert_eq!(
            event
                .get("dataset_shard_generalization_preflight_required")
                .and_then(Value::as_bool),
            Some(true)
        );
        let contracts = event
            .get("dataset_shard_generalization_contracts")
            .and_then(Value::as_array)
            .expect("visible dataset shard contracts");
        assert!(contracts[0]
            .as_str()
            .unwrap()
            .contains("c4-train.00009-of-01024.json.gz"));
        for key in [
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "max_turns_stop_condition",
            "timeout_seconds_stop_condition",
            "round_limit_stop_condition",
            "checkpoint_count_stop_condition",
            "checkpoint_cooldown_stop_condition",
            "attempt_count_stop_condition",
            "budget_stop_condition",
            "dataset_shard_generalization_contracts_stop_condition",
            "dataset_shard_generalization_preflight_stop_condition",
        ] {
            assert_eq!(
                event.get(key).and_then(Value::as_bool),
                Some(false),
                "{key}"
            );
        }
        let message = state.messages.last().unwrap()["content"].as_str().unwrap();
        assert!(message.contains("Dataset-shard generalization preflight"));
        assert!(message.contains("two synthetic gzip JSONL shards"));
        assert!(message.contains("arbitrary C4-style names"));
        assert!(message.contains("record boundaries, order, count, JSON schema"));
        assert!(message.contains("not a master, sub-agent, or Worker loop stop condition"));
    }

