    #[test]
    fn dataset_shard_preflight_blocks_remote_dependency_and_single_shard_paths() {
        let mut state = worker_state_for_unit_tests();
        state.task_context = json!({
            "task_id": "count-dataset-tokens",
            "previous_errors": [
                "dataset_shard_generalization_contract: verifier loads c4-train.00009-of-01024.json.gz through datasets/data_files; solution must generalize beyond the visible shard, process arbitrary C4 gzip JSONL shard names, preserve record boundaries, order, count, and JSON schema"
            ]
        });
        state.dataset_shard_generalization_preflight_required = true;
        assert!(dataset_shard_generalization_preflight_pending(&state));

        let cases = [
            (
                "pip install datasets transformers torch",
                "dataset_shard_preflight_pending_dependency_setup",
            ),
            (
                "python3 -c \"from datasets import load_dataset; load_dataset('allenai/c4', data_files='c4-train.00009-of-01024.json.gz')\"",
                "dataset_shard_preflight_pending_full_remote_dataset_fetch",
            ),
            (
                "find /root/.cache/huggingface/datasets -name '*.jsonl' -o -name '*.arrow'",
                "dataset_shard_preflight_pending_cache_hunt",
            ),
            (
                "python3 -c \"open('/app/answer.txt','w').write('c4-train.00009-of-01024.json.gz')\"",
                "dataset_shard_preflight_pending_single_shard_hardcoding",
            ),
        ];

        for (command, expected_reason) in cases {
            let blocked = blocked_dataset_shard_generalization_preflight_expansion(
                &state,
                "bash",
                &json!({"command": command}),
            )
            .unwrap_or_else(|| panic!("dataset shard pending guard should block: {command}"));
            assert_eq!(
                blocked
                    .metadata
                    .get("semantic_failure_kind")
                    .and_then(Value::as_str),
                Some("blocked_dataset_shard_generalization_preflight_expansion")
            );
            assert_eq!(
                blocked
                    .metadata
                    .get("blocked_reason")
                    .and_then(Value::as_str),
                Some(expected_reason)
            );
            assert_worker_policy_guard_is_non_terminal(&blocked.metadata);
            assert_eq!(
                blocked
                    .metadata
                    .get("dataset_shard_generalization_preflight_required")
                    .and_then(Value::as_bool),
                Some(true)
            );
            assert_eq!(
                blocked
                    .metadata
                    .get("dataset_shard_generalization_preflight_stop_condition")
                    .and_then(Value::as_bool),
                Some(false)
            );
            assert_eq!(
                blocked
                    .metadata
                    .get("dataset_shard_generalization_preflight_expansion_stop_condition")
                    .and_then(Value::as_bool),
                Some(false)
            );
            assert!(blocked
                .error
                .contains("Dataset-shard generalization preflight is pending"));
            assert!(blocked.error.contains("multi-shard gzip JSONL fixture"));
            assert!(blocked
                .error
                .contains("not a master, sub-agent, or Worker loop stop condition"));
        }
    }

