    #[test]
    fn deliverable_size_cap_preflight_detects_stat_and_python_limit_assertions() {
        let mut state = worker_state_for_unit_tests();
        state.task_instruction =
            "Create /app/gpt2.c. The file must be under 5000 bytes and compile.".to_string();
        state.tool_call_history = vec![json!({
            "turn": 2,
            "tool": "bash",
            "args": {"command": "cd /app && python3 /tests/test_outputs.py"},
            "success": false,
            "output": "E       AssertionError: File /app/gpt2.c is larger than 5000 bytes\nE       assert 8394 < 5000\nE        +  where 8394 = os.stat_result(st_size=8394).st_size\n",
            "error": "exit code: 1",
        })];
        let evidence = deliverable_size_cap_evidence(&state).unwrap();

        assert!(is_deliverable_size_cap_preflight_command(
            &evidence,
            "bash",
            &json!({"command": "stat -c '%s' /app/gpt2.c"}),
            &successful_tool_response("4999\n"),
        ));
        assert!(is_deliverable_size_cap_preflight_command(
            &evidence,
            "verify",
            &json!({"command": python_size_cap_preflight_command("/app/gpt2.c", 5000)}),
            &successful_tool_response("size 4999\n"),
        ));
        assert!(!is_deliverable_size_cap_preflight_command(
            &evidence,
            "bash",
            &json!({"command": "gcc /app/gpt2.c -o /tmp/gpt2 && /tmp/gpt2"}),
            &successful_tool_response("ok\n"),
        ));
        assert!(!is_deliverable_size_cap_preflight_command(
            &evidence,
            "bash",
            &json!({"command": "wc -c /app/gpt2.c"}),
            &successful_tool_response("8394 /app/gpt2.c\n"),
        ));
    }

