    #[test]
    fn dependency_failure_detector_covers_successful_shell_failure_output() {
        assert!(looks_like_dependency_failure(
            "ERROR: No matching distribution found for pgmpy"
        ));
        assert!(looks_like_dependency_failure(
            "bash: line 1: python3: command not found"
        ));
        assert!(looks_like_dependency_failure(
            "E: Unable to locate package python3-numpy"
        ));
        assert!(looks_like_dependency_failure(
            "ERROR: Wheel 'torch' located at /tmp/torch.whl is invalid."
        ));
        assert!(looks_like_dependency_failure(
            "ImportError: libGL.so.1: cannot open shared object file: No such file or directory"
        ));
        assert!(looks_like_dependency_failure(
            "error while loading shared libraries: libfoo.so: cannot open shared object file: No such file or directory"
        ));
        assert!(looks_like_dependency_failure(
            "ImportError: DLL load failed while importing cv2: The specified module could not be found."
        ));
        assert!(looks_like_dependency_failure(
            "Error: File is not a zip file"
        ));
        assert!(looks_like_dependency_failure(
            "dpkg: dependency problems prevent configuration of libstdc++-12-dev:amd64"
        ));
        assert!(looks_like_dependency_failure(
            "ERROR: failed to lock directory '/usr/local/lib/R/site-library' for modifying"
        ));
        assert!(looks_like_dependency_failure(
            "E: Could not get lock /var/lib/dpkg/lock-frontend. It is held by process 230"
        ));
    }

    #[test]
    fn network_probe_missing_tools_do_not_feed_dependency_checkpoint() {
        let mut state = worker_state_for_unit_tests();
        let probes = [
            (
                "ping -c 1 -W 2 deb.debian.org 2>&1 | head -5",
                "bash: line 1: ping: command not found",
            ),
            (
                "curl --head --connect-timeout 5 https://example.com 2>&1 | head -5",
                "curl: command not found",
            ),
            (
                "nc -z example.com 443 2>&1 | head -5",
                "nc: command not found",
            ),
        ];

        for (command, output) in probes {
            let response = ToolResponse {
                success: true,
                output: output.to_string(),
                error: String::new(),
                duration_ms: 0.0,
                metadata: json!({
                    "semantic_failure_kind": "network_probe_tool_missing",
                    "semantic_failure_detected": true,
                }),
            };
            record_dependency_failure(&mut state, "bash", &json!({"command": command}), &response);
        }

        assert_eq!(state.dependency_failure_count, 0);
        assert!(!maybe_inject_dependency_checkpoint(&mut state));
        assert!(state.trajectory.iter().all(|event| {
            event.get("type").and_then(Value::as_str) != Some("dependency_recovery_checkpoint")
        }));
    }

    #[test]
    fn generic_dependency_command_not_found_still_feeds_dependency_checkpoint() {
        let mut state = worker_state_for_unit_tests();
        let response = ToolResponse {
            success: true,
            output: "bash: line 1: python3: command not found".to_string(),
            error: String::new(),
            duration_ms: 0.0,
            metadata: json!({}),
        };

        record_dependency_failure(
            &mut state,
            "bash",
            &json!({"command": "python3 -m pip install fasttext"}),
            &response,
        );

        assert_eq!(state.dependency_failure_count, 1);
    }

