    #[test]
    fn worker_policy_guards_are_non_terminal_operation_evidence() {
        let cases = [
            blocked_package_manager_recovery(
                "bash",
                &json!({"command": "apt-get install -y clang 2>&1"}),
            )
            .expect("large toolchain guard"),
            blocked_broad_system_find(
                "bash",
                &json!({"command": "find / -name '*rstan*' 2>/dev/null | head -20"}),
            )
            .expect("broad system find guard"),
            blocked_verifier_artifact_search(
                "bash",
                &json!({"command": "ls /logs/verifier /tmp/hl-verifier-cache 2>/dev/null"}),
            )
            .expect("verifier artifact guard"),
            blocked_host_memory_search(
                "grep",
                &json!({"pattern": "rstan", "path": "/trials/runs/mcmc-sampling-stan"}),
            )
            .expect("host memory guard"),
        ];

        for response in cases {
            assert!(!response.success);
            assert!(response
                .metadata
                .get("semantic_failure_kind")
                .and_then(Value::as_str)
                .is_some());
            assert!(response
                .metadata
                .get("blocked_reason")
                .and_then(Value::as_str)
                .is_some());
            assert_worker_policy_guard_is_non_terminal(&response.metadata);
        }
    }

    #[test]
    fn hazardous_package_manager_recovery_blocks_feed_dependency_checkpoint() {
        let mut state = worker_state_for_unit_tests();
        state.turn_count = 4;
        let commands = [
            (
                "package_manager_background",
                "dpkg --configure -a 2>&1 &\nsleep 5",
            ),
            (
                "package_manager_lock_cleanup",
                "rm -f /var/lib/dpkg/lock* /var/cache/apt/archives/lock",
            ),
            ("package_manager_process_kill", "pkill apt-get || true"),
            (
                "package_manager_state_repair",
                "dpkg --configure -a 2>&1 | head -20",
            ),
            (
                "manual_deb_dependency_chase",
                "dpkg -i /tmp/r-cran-rcppparallel_5.1.10-1_amd64.deb",
            ),
            (
                "scripted_package_manager",
                "python3 <<'PY'\nimport pip._internal.cli.main as pip_main\npip_main.main(['install', '--trusted-host', 'pypi.org', 'httpstan'])\nPY",
            ),
        ];

        for (index, (expected_reason, command)) in commands.iter().enumerate() {
            let args = json!({"command": command});
            let blocked = blocked_package_manager_recovery("bash", &args).unwrap_or_else(|| {
                panic!(
                    "hazardous package-manager recovery should be blocked: reason={expected_reason}, command={command}"
                )
            });
            assert_eq!(
                blocked
                    .metadata
                    .get("blocked_reason")
                    .and_then(Value::as_str),
                Some(*expected_reason)
            );
            record_dependency_failure(&mut state, "bash", &args, &blocked);
            assert_eq!(state.dependency_failure_count, index + 1);
        }

        assert!(maybe_inject_dependency_checkpoint(&mut state));
        assert_eq!(state.dependency_checkpoint_count, 1);
        assert_eq!(state.dependency_failure_count, 0);
        let checkpoint = state
            .trajectory
            .iter()
            .find(|event| {
                event.get("type").and_then(Value::as_str) == Some("dependency_recovery_checkpoint")
            })
            .expect("dependency recovery checkpoint event");
        assert_eq!(
            checkpoint.get("failure_count").and_then(Value::as_u64),
            Some(commands.len() as u64)
        );
        assert_eq!(
            checkpoint
                .get("dependency_failure_count_stop_condition")
                .and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(
            checkpoint
                .get("loop_stop_condition")
                .and_then(Value::as_bool),
            Some(false)
        );
    }

