    #[test]
    fn cython_optional_import_guard_blocks_download_cache_and_import_chase() {
        let mut state = worker_state_for_unit_tests();
        state.task_instruction =
            "Fix build-cython-ext for pyknotid.spacecurves.chelpers and ccomplexity.".to_string();
        state.task_context = json!({
            "task_id": "build-cython-ext",
            "failure_mechanisms": [
                {
                    "name": "cython_extension_optional_import_pivot_mechanism",
                    "description": "find_spec for pyknotid.spacecurves.chelpers imported pyknotid.visualise and failed with ModuleNotFoundError: No module named 'vispy'."
                }
            ]
        });

        for (command, expected_reason) in [
            (
                "curl -L https://files.pythonhosted.org/packages/vispy-0.14.3.tar.gz -o /tmp/vispy.tar.gz",
                "cython_optional_gui_manual_download",
            ),
            (
                "python3 -m pip index versions vispy 2>&1 | head -20",
                "cython_optional_gui_cache_search",
            ),
            (
                "python3 - <<'PY'\nimport importlib\nimportlib.import_module('pyknotid.visualise')\nPY",
                "cython_optional_gui_import_probe",
            ),
        ] {
            let blocked = blocked_cython_optional_import_dependency_expansion(
                &state,
                "bash",
                &json!({"command": command}),
            )
            .unwrap_or_else(|| panic!("Cython optional import guard should block: {command}"));
            assert_eq!(
                blocked
                    .metadata
                    .get("blocked_reason")
                    .and_then(Value::as_str),
                Some(expected_reason)
            );
            assert_worker_policy_guard_is_non_terminal(&blocked.metadata);
            assert!(blocked.error.contains("not the optional GUI/visualization stack"));
            assert!(blocked.error.contains("not driven by time, round, turn"));
        }
    }

