    #[test]
    fn historical_dependency_loop_guard_reads_structured_analysis_context() {
        let mut state = worker_state_for_unit_tests();
        state.task_instruction =
            "Train a fastText classifier on the Yelp data and save /app/model.bin.".to_string();
        state.task_context = json!({
            "task_id": "train-fasttext",
            "historical_analysis_lessons": [
                {
                    "summary_id": "summary_003",
                    "task_id": "train-fasttext",
                    "failure_category": "dependency_loop_without_deliverable_progress_mechanism",
                    "failure_mechanisms": [
                        {
                            "name": "fasttext_artifact_pivot_mechanism",
                            "description": "Repeated fastText, fasttext-wheel, C++ header, libstdc++, pip, manual wheel/tarball, or Debian-package setup happened without producing /app/model.bin.",
                            "evidence": "pip install fasttext 2>&1 | tail -5; apt-get install -y fasttext"
                        }
                    ],
                    "policy_counts": {
                        "package_manager_timeout_cap": 8,
                        "manual_dependency_download_guard": 1
                    }
                }
            ]
        });

        let blocked = blocked_historical_dependency_loop_expansion(
            &state,
            "bash",
            &json!({"command": "apt-get update && apt-get install -y fasttext"}),
        )
        .expect("structured historical analysis should block repeated dependency setup");

        assert_eq!(state.dependency_failure_count, 0);
        assert_eq!(
            blocked
                .metadata
                .get("blocked_reason")
                .and_then(Value::as_str),
            Some("post_checkpoint_dependency_setup")
        );
        assert_eq!(
            blocked
                .metadata
                .get("historical_dependency_loop_evidence")
                .and_then(Value::as_bool),
            Some(true)
        );
        assert!(blocked
            .metadata
            .get("historical_dependency_loop_mechanisms")
            .and_then(Value::as_array)
            .is_some_and(|items| items.iter().any(|item| item.as_str()
                == Some("dependency_loop_without_deliverable_progress_mechanism"))));
        assert_worker_policy_guard_is_non_terminal(&blocked.metadata);
        assert!(blocked.error.contains("historical analysis evidence"));
        assert!(blocked
            .error
            .contains("not a master, sub-agent, or Worker loop stop condition"));
    }

