    #[test]
    fn historical_dependency_artifact_first_checkpoint_fires_before_replay_without_loop_limit() {
        let mut state = worker_state_for_unit_tests();
        state.task_instruction =
            "Train a fastText classifier on the Yelp data and save /app/model.bin.".to_string();
        state.task_context = json!({
            "task_id": "train-fasttext",
            "completion_condition": "Expected artifact is /app/model.bin.",
            "environment_context": "Local training data is /app/data/train-00000-of-00001.parquet.",
            "historical_analysis_lessons": [
                {
                    "summary_id": "summary_003",
                    "task_id": "train-fasttext",
                    "failure_category": "dependency_loop_without_deliverable_progress_mechanism",
                    "failure_mechanisms": [
                        {
                            "name": "dependency_loop_without_deliverable_progress_mechanism",
                            "description": "The Worker spent repeated actions on package, toolchain, manual download, or build setup without explicit deliverable progress."
                        },
                        {
                            "name": "fasttext_artifact_pivot_mechanism",
                            "description": "Repeated fastText setup happened without producing /app/model.bin."
                        }
                    ],
                    "policy_counts": {
                        "package_manager_timeout_cap": 41,
                        "manual_dependency_download_guard": 64
                    }
                }
            ]
        });
        state.deliverable_targets =
            extract_deliverable_targets(&state.task_instruction, &state.task_context);
        state.turn_count = 2;

        assert_eq!(state.dependency_checkpoint_count, 0);
        assert!(maybe_inject_historical_dependency_artifact_first_checkpoint(&mut state));
        assert!(!maybe_inject_historical_dependency_artifact_first_checkpoint(&mut state));

        let checkpoint = latest_event(&state, "historical_dependency_artifact_first_checkpoint");
        assert_eq!(
            checkpoint.get("untouched_deliverable_paths"),
            Some(&json!(["/app/model.bin"]))
        );
        assert_eq!(
            checkpoint
                .get("historical_dependency_loop_evidence")
                .and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(
            checkpoint
                .get("historical_dependency_loop_category")
                .and_then(Value::as_str),
            Some("dependency_loop_without_deliverable_progress")
        );
        assert_eq!(
            checkpoint
                .get("dependency_checkpoint_count")
                .and_then(Value::as_u64),
            Some(0)
        );
        assert!(checkpoint
            .get("historical_dependency_loop_mechanisms")
            .and_then(Value::as_array)
            .is_some_and(|items| items.iter().any(|item| item.as_str()
                == Some("dependency_loop_without_deliverable_progress_mechanism"))));
        for key in [
            "historical_dependency_artifact_first_stop_condition",
            "historical_dependency_loop_stop_condition",
            "dependency_failure_count_stop_condition",
            "dependency_checkpoint_count_stop_condition",
            "dependency_artifact_first_checkpoint_count_stop_condition",
            "deliverable_checkpoint_max_stop_condition",
            "checkpoint_count_stop_condition",
            "checkpoint_cooldown_stop_condition",
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "max_turns_stop_condition",
            "timeout_seconds_stop_condition",
            "timeout_stop_condition",
            "round_limit_stop_condition",
            "turn_count_stop_condition",
            "attempt_count_stop_condition",
            "cap_stop_condition",
            "count_limit_stop_condition",
            "cap_count_budget_stop_condition",
            "token_budget_stop_condition",
            "budget_stop_condition",
        ] {
            assert_eq!(
                checkpoint.get(key).and_then(Value::as_bool),
                Some(false),
                "historical dependency artifact-first metadata should mark {key}=false"
            );
        }
        let checkpoint_message = state.messages.last().unwrap()["content"].as_str().unwrap();
        assert!(checkpoint_message.contains("Historical dependency artifact-first checkpoint"));
        assert!(checkpoint_message.contains("/app/model.bin"));
        assert!(checkpoint_message.contains("prior campaign or same-task memory evidence"));
        assert!(checkpoint_message.contains("Start from the artifact contract now"));
        assert!(checkpoint_message.contains("Do not replay package-manager installs"));
        assert!(
            checkpoint_message.contains("not a master, sub-agent, or Worker loop stop condition")
        );
        assert!(checkpoint_message.contains("not driven by time, round, turn, token"));
        assert!(checkpoint_message.contains("checkpoint count"));
        assert!(checkpoint_message.contains("budget metadata"));
    }

    #[test]
    fn stan_partial_deliverable_checkpoint_completes_remaining_outputs() {
        let mut state = worker_state_for_unit_tests();
        state.task_instruction = "Convert /app/gp_rstan.R to PyStan, create /app/pystan_analysis.py, and write /app/predictions.csv.".to_string();
        state.task_context = json!({
            "task_id": "rstan-to-pystan",
            "completion_condition": "Read /app/gp_rstan.R, create /app/pystan_analysis.py using stan.build(..., random_seed=1), and output /app/predictions.csv.",
            "previous_errors": [
                "stan_dependency_stack_pivot_mechanism: repeated PyStan/httpstan/g++ dependency recovery continued after /app/pystan_analysis.py was created but /app/predictions.csv was still missing."
            ]
        });
        state.deliverable_targets =
            extract_deliverable_targets(&state.task_instruction, &state.task_context);
        state.turn_count = 3;
        record_tool_progress(
            &mut state,
            "write",
            &json!({
                "file_path": "/app/pystan_analysis.py",
                "content": "import stan\n# stan.build(..., random_seed=1)\n",
            }),
            &successful_tool_response("wrote /app/pystan_analysis.py"),
        );
        assert!(state
            .touched_deliverables
            .contains("/app/pystan_analysis.py"));
        assert!(!state.touched_deliverables.contains("/app/predictions.csv"));

        state.turn_count = 6;
        for command in [
            "pip install pystan==3.10.0",
            "pip install httpstan",
            "apt-get install -y g++",
        ] {
            record_stan_dependency_failure_for_unit_test(&mut state, command);
        }

        assert!(maybe_inject_dependency_checkpoint(&mut state));
        assert!(maybe_inject_stan_partial_deliverable_checkpoint(&mut state));
        let checkpoint = latest_event(&state, "stan_partial_deliverable_checkpoint");
        assert_eq!(
            checkpoint.get("touched_deliverable_paths"),
            Some(&json!(["/app/pystan_analysis.py"]))
        );
        assert_eq!(
            checkpoint.get("remaining_deliverable_paths"),
            Some(&json!(["/app/predictions.csv"]))
        );
        assert_eq!(
            checkpoint.get("stan_source_context_paths"),
            Some(&json!(["/app/gp_rstan.R"]))
        );
        for key in [
            "loop_stop_condition",
            "stan_partial_deliverable_stop_condition",
            "stan_dependency_stack_stop_condition",
            "dependency_failure_count_stop_condition",
            "dependency_checkpoint_count_stop_condition",
            "artifact_first_stop_condition",
            "checkpoint_count_stop_condition",
            "time_round_token_limit_driven",
            "max_turns_stop_condition",
            "timeout_seconds_stop_condition",
            "round_limit_stop_condition",
            "turn_count_stop_condition",
            "attempt_count_stop_condition",
            "cap_stop_condition",
            "count_limit_stop_condition",
            "token_budget_stop_condition",
            "budget_stop_condition",
        ] {
            assert_eq!(
                checkpoint.get(key).and_then(Value::as_bool),
                Some(false),
                "{key}"
            );
        }
        let checkpoint_message = state.messages.last().unwrap()["content"].as_str().unwrap();
        assert!(checkpoint_message.contains("Stan partial-deliverable checkpoint"));
        assert!(
            checkpoint_message.contains("Keep the touched artifact(s): /app/pystan_analysis.py")
        );
        assert!(checkpoint_message
            .contains("Complete the remaining output artifact(s): /app/predictions.csv"));
        assert!(checkpoint_message
            .contains("Do not restart PyStan, RStan, httpstan, StanHeaders, g++, apt, pip"));
        assert!(checkpoint_message.contains("re-read /app/gp_rstan.R"));
        assert!(checkpoint_message.contains("CSV headers"));
        assert!(checkpoint_message.contains("finite numeric prediction columns"));
        assert!(checkpoint_message.contains("stan.build(..., random_seed=1)"));
        assert!(
            checkpoint_message.contains("not a master, sub-agent, or Worker loop stop condition")
        );
        assert!(checkpoint_message.contains("not driven by time, round, turn, token"));

        assert!(!maybe_inject_stan_partial_deliverable_checkpoint(
            &mut state
        ));
    }

