    #[test]
    fn successful_dependency_probes_do_not_clear_failure_count() {
        for command in [
            "apt-cache search gcc-mipsel-linux-gnu 2>/dev/null | head -20",
            "dpkg -l 2>/dev/null | grep -iE 'gcc|clang|mips'",
            "python3 -m pip show fasttext 2>/dev/null || true",
            "find /tmp -name 'httpstan*.whl' -type f 2>/dev/null",
        ] {
            let mut state = worker_state_for_unit_tests();
            state.dependency_failure_count = 2;
            let args = json!({"command": command});
            let response = ToolResponse {
                success: true,
                output: "probe completed".to_string(),
                error: String::new(),
                duration_ms: 0.0,
                metadata: json!({"exit_code": 0}),
            };

            record_dependency_failure(&mut state, "bash", &args, &response);

            assert_eq!(
                state.dependency_failure_count, 2,
                "successful dependency probe should preserve failure context: {command}"
            );

            let blocked = blocked_repeated_dependency_failure_path(&state, "bash", &args)
                .unwrap_or_else(|| {
                    panic!("repeated dependency failure path should block broad probe: {command}")
                });
            assert_eq!(
                blocked
                    .metadata
                    .get("blocked_reason")
                    .and_then(Value::as_str),
                Some("repeated_package_cache_search_failure")
            );
            assert_eq!(
                blocked
                    .metadata
                    .get("loop_stop_condition")
                    .and_then(Value::as_bool),
                Some(false)
            );
            assert_eq!(
                blocked
                    .metadata
                    .get("dependency_failure_count_stop_condition")
                    .and_then(Value::as_bool),
                Some(false)
            );
            assert_eq!(
                blocked
                    .metadata
                    .get("timeout_escalation_count_stop_condition")
                    .and_then(Value::as_bool),
                Some(false)
            );
            assert_eq!(
                blocked
                    .metadata
                    .get("time_round_token_limit_driven")
                    .and_then(Value::as_bool),
                Some(false)
            );
        }
    }

