    #[test]
    fn image_similarity_artifact_preflight_clears_completion_gate() {
        let mut state = WorkerState::new(WorkerRequest {
            task_instruction: "Reverse engineer the renderer and create /app/reverse so generated image.ppm matches the reference image by cosine similarity.".to_string(),
            task_context: json!({
                "task_id": "path-tracing-reverse",
                "previous_errors": [
                    "image_similarity_contract: Generated image/render artifact must match the verifier reference above the required cosine/SSIM threshold"
                ]
            }),
            initial_messages: Vec::new(),
            initial_trajectory: Vec::new(),
            tool_schemas: Vec::new(),
            max_turns_audit: 10,
            model_used: "test".to_string(),
            todo_items: Vec::new(),
            verification_command: String::new(),
            thresholds: Thresholds {
                compaction_char_threshold: 1000,
                verification_checkpoint_turns: Vec::new(),
                verification_checkpoint_cooldown_turns: 1,
                verification_checkpoint_max: 1,
                verification_checkpoint_min_tool_calls: 1,
                no_progress_checkpoint_tool_calls: 50,
                no_progress_checkpoint_cooldown_turns: 10,
                no_progress_checkpoint_max: 1,
                late_no_progress_turn_percent: 70,
                stalled_tool_loop_calls: 20,
                stalled_tool_loop_cooldown_turns: 8,
                stalled_tool_loop_max: 2,
                deliverable_checkpoint_min_tool_calls: 10,
                deliverable_checkpoint_cooldown_turns: 10,
                deliverable_checkpoint_max: 1,
                empty_response_recovery_limit: 3,
                ephemeral_tool_output_max_chars: 4000,
                ephemeral_tool_output_keep_recent: 4,
                timeout_escalation_count: 2,
                timeout_escalation_late_turn_percent: 66,
            },
            prompt_policy: PromptPolicy::default(),
        });
        assert!(state.image_similarity_preflight_required);
        state.turn_count = 2;
        record_tool_progress(
            &mut state,
            "bash",
            &json!({"command": "cd /app && ./reverse > /app/image2.ppm"}),
            &successful_tool_response("wrote /app/image2.ppm"),
        );

        assert!(maybe_inject_image_similarity_preflight_checkpoint(
            &mut state
        ));
        let checkpoint = latest_event(&state, "image_similarity_preflight_checkpoint");
        assert_eq!(
            checkpoint
                .get("image_similarity_artifact_path")
                .and_then(Value::as_str),
            Some("/app/image2.ppm")
        );
        assert_eq!(
            checkpoint
                .get("image_similarity_preflight_required")
                .and_then(Value::as_bool),
            Some(true)
        );
        for key in [
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "max_turns_stop_condition",
            "timeout_seconds_stop_condition",
            "round_limit_stop_condition",
            "checkpoint_count_stop_condition",
            "checkpoint_cooldown_stop_condition",
            "attempt_count_stop_condition",
            "budget_stop_condition",
            "image_similarity_stop_condition",
        ] {
            assert_eq!(
                checkpoint.get(key).and_then(Value::as_bool),
                Some(false),
                "{key}"
            );
        }
        let checkpoint_message = state.messages.last().unwrap()["content"].as_str().unwrap();
        assert!(checkpoint_message.contains("Image similarity preflight"));
        assert!(checkpoint_message.contains("/app/image2.ppm"));
        assert!(checkpoint_message.contains("cosine/SSIM"));
        assert!(checkpoint_message.contains("sampled pixel/region"));
        assert!(
            checkpoint_message.contains("not a master, sub-agent, or Worker loop stop condition")
        );

        let mut stdin = std::io::Cursor::new(Vec::<u8>::new());
        assert!(!completion_gate_passed(&mut state, &mut stdin));
        let gate = latest_event(&state, "image_similarity_preflight_completion_gate");
        assert_eq!(
            gate.get("image_similarity_artifact_path")
                .and_then(Value::as_str),
            Some("/app/image2.ppm")
        );
        for key in [
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "max_turns_stop_condition",
            "timeout_seconds_stop_condition",
            "round_limit_stop_condition",
            "checkpoint_count_stop_condition",
            "checkpoint_cooldown_stop_condition",
            "attempt_count_stop_condition",
            "budget_stop_condition",
            "image_similarity_stop_condition",
        ] {
            assert_eq!(gate.get(key).and_then(Value::as_bool), Some(false), "{key}");
        }

        state.turn_count = 3;
        let command = image_similarity_preflight_command("/app/image2.ppm");
        assert!(is_image_similarity_preflight_command(
            "verify",
            &json!({"command": command})
        ));
        record_tool_progress(
            &mut state,
            "verify",
            &json!({"command": image_similarity_preflight_command("/app/image2.ppm")}),
            &successful_tool_response("image similarity preflight passed"),
        );

        let passed = latest_event(&state, "image_similarity_preflight_passed");
        assert_eq!(
            passed
                .get("image_similarity_artifact_path")
                .and_then(Value::as_str),
            Some("/app/image2.ppm")
        );
        for key in [
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "max_turns_stop_condition",
            "timeout_seconds_stop_condition",
            "round_limit_stop_condition",
            "attempt_count_stop_condition",
            "budget_stop_condition",
            "image_similarity_stop_condition",
        ] {
            assert_eq!(
                passed.get(key).and_then(Value::as_bool),
                Some(false),
                "{key}"
            );
        }

        state.turn_count = 4;
        let mut stdin = std::io::Cursor::new(Vec::<u8>::new());
        assert!(completion_gate_passed(&mut state, &mut stdin));
    }

    #[test]
    fn image_similarity_preflight_rejects_header_only_hardcoded_pixels() {
        let mut state = worker_state_for_unit_tests();
        state.image_similarity_preflight_required = true;
        state.turn_count = 2;
        record_tool_progress(
            &mut state,
            "bash",
            &json!({"command": "cd /app && ./reverse > /app/image2.ppm"}),
            &successful_tool_response("wrote /app/image2.ppm"),
        );
        assert_eq!(state.image_similarity_artifact_touched_turn, 2);

        let weak_command = "python3 - <<'PY'\n\
from pathlib import Path\n\
path = Path('/app/image2.ppm')\n\
assert path.exists(), path\n\
with path.open('rb') as f:\n\
    header = f.readline().strip()\n\
    dimensions = f.readline().strip()\n\
    maxval = f.readline().strip()\n\
assert header in (b'P3', b'P6'), header\n\
assert dimensions and maxval == b'255'\n\
sampled_pixels = [0, 127, 255]\n\
assert sampled_pixels and all(0 <= value <= 255 for value in sampled_pixels)\n\
cosine_similarity = 1.0\n\
assert cosine_similarity >= 0.995\n\
print('image similarity preflight passed')\n\
PY";

        assert!(!is_image_similarity_preflight_command(
            "verify",
            &json!({"command": weak_command})
        ));
        state.turn_count = 3;
        record_tool_progress(
            &mut state,
            "verify",
            &json!({"command": weak_command}),
            &successful_tool_response("image similarity preflight passed"),
        );

        assert_eq!(state.last_image_similarity_preflight_turn, 0);
        assert!(image_similarity_preflight_pending(&state));
        assert!(!state
            .trajectory
            .iter()
            .any(|event| event.get("type").and_then(Value::as_str)
                == Some("image_similarity_preflight_passed")));

        state.turn_count = 4;
        let mut stdin = std::io::Cursor::new(Vec::<u8>::new());
        assert!(!completion_gate_passed(&mut state, &mut stdin));
        let gate = latest_event(&state, "image_similarity_preflight_completion_gate");
        assert_eq!(
            gate.get("image_similarity_artifact_path")
                .and_then(Value::as_str),
            Some("/app/image2.ppm")
        );
        assert_eq!(
            gate.get("image_similarity_stop_condition")
                .and_then(Value::as_bool),
            Some(false)
        );
    }

    #[test]
    fn html_filter_alert_bypass_preflight_clears_completion_gate() {
        let mut state = WorkerState::new(WorkerRequest {
            task_instruction: "Create /app/out.html that still triggers an alert after /tests/filter.py filters a temp copy.".to_string(),
            task_context: json!({
                "task_id": "break-filter-js-from-html",
                "previous_errors": [
                    "html_filter_alert_bypass_contract: verifier copies /app/out.html to a temp HTML file, runs /tests/filter.py on that copy in place, then loads the filtered artifact in headless Chromium/WebDriver and expects a browser-observable alert"
                ]
            }),
            initial_messages: Vec::new(),
            initial_trajectory: Vec::new(),
            tool_schemas: Vec::new(),
            max_turns_audit: 10,
            model_used: "test".to_string(),
            todo_items: Vec::new(),
            verification_command: String::new(),
            thresholds: Thresholds {
                compaction_char_threshold: 1000,
                verification_checkpoint_turns: Vec::new(),
                verification_checkpoint_cooldown_turns: 1,
                verification_checkpoint_max: 1,
                verification_checkpoint_min_tool_calls: 1,
                no_progress_checkpoint_tool_calls: 50,
                no_progress_checkpoint_cooldown_turns: 10,
                no_progress_checkpoint_max: 1,
                late_no_progress_turn_percent: 70,
                stalled_tool_loop_calls: 20,
                stalled_tool_loop_cooldown_turns: 8,
                stalled_tool_loop_max: 2,
                deliverable_checkpoint_min_tool_calls: 10,
                deliverable_checkpoint_cooldown_turns: 10,
                deliverable_checkpoint_max: 1,
                empty_response_recovery_limit: 3,
                ephemeral_tool_output_max_chars: 4000,
                ephemeral_tool_output_keep_recent: 4,
                timeout_escalation_count: 2,
                timeout_escalation_late_turn_percent: 66,
            },
            prompt_policy: PromptPolicy::default(),
        });
        assert!(state.html_filter_alert_bypass_preflight_required);
        state.turn_count = 2;
        record_tool_progress(
            &mut state,
            "bash",
            &json!({"command": "cat > /app/out.html <<'HTML'\n<html><body>payload</body></html>\nHTML"}),
            &successful_tool_response("wrote /app/out.html"),
        );

        assert_eq!(state.html_filter_alert_bypass_artifact_touched_turn, 2);
        assert_eq!(
            state.html_filter_alert_bypass_artifact_path,
            "/app/out.html"
        );
        assert!(html_filter_alert_bypass_preflight_pending(&state));
        assert!(maybe_inject_html_filter_alert_bypass_preflight_checkpoint(
            &mut state
        ));

        let checkpoint = latest_event(&state, "html_filter_alert_bypass_preflight_checkpoint");
        assert_eq!(
            checkpoint
                .get("html_filter_alert_bypass_artifact_path")
                .and_then(Value::as_str),
            Some("/app/out.html")
        );
        assert_eq!(
            checkpoint
                .get("html_filter_alert_bypass_preflight_required")
                .and_then(Value::as_bool),
            Some(true)
        );
        for key in [
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "max_turns_stop_condition",
            "timeout_seconds_stop_condition",
            "round_limit_stop_condition",
            "checkpoint_count_stop_condition",
            "checkpoint_cooldown_stop_condition",
            "attempt_count_stop_condition",
            "budget_stop_condition",
            "html_filter_alert_bypass_stop_condition",
        ] {
            assert_eq!(
                checkpoint.get(key).and_then(Value::as_bool),
                Some(false),
                "{key}"
            );
        }
        let checkpoint_message = state.messages.last().unwrap()["content"].as_str().unwrap();
        assert!(checkpoint_message.contains("HTML filter alert bypass preflight"));
        assert!(checkpoint_message.contains("/tests/filter.py"));
        assert!(checkpoint_message.contains("headless Chromium/WebDriver alert path"));
        assert!(checkpoint_message.contains("browser-observable alert still fires"));

        let mut stdin = std::io::Cursor::new(Vec::<u8>::new());
        assert!(!completion_gate_passed(&mut state, &mut stdin));
        let gate = latest_event(&state, "html_filter_alert_bypass_preflight_completion_gate");
        assert_eq!(
            gate.get("html_filter_alert_bypass_artifact_path")
                .and_then(Value::as_str),
            Some("/app/out.html")
        );
        let gate_message = state.messages.last().unwrap()["content"].as_str().unwrap();
        assert!(gate_message.contains(
            "Simple file-exists, grep, syntax, or unfiltered-HTML checks do not clear this gate"
        ));

        let weak_command = weak_html_filter_raw_grep_check();
        assert!(!is_html_filter_alert_bypass_preflight_command(
            "verify",
            &json!({"command": weak_command})
        ));
        state.turn_count = 3;
        record_tool_progress(
            &mut state,
            "verify",
            &json!({"command": weak_html_filter_raw_grep_check()}),
            &successful_tool_response("raw html contains alert"),
        );
        assert_eq!(state.last_html_filter_alert_bypass_preflight_turn, 0);
        assert!(html_filter_alert_bypass_preflight_pending(&state));

        let command = html_filter_alert_bypass_preflight_command();
        assert!(is_html_filter_alert_bypass_preflight_command(
            "verify",
            &json!({"command": command})
        ));
        state.turn_count = 4;
        record_tool_progress(
            &mut state,
            "verify",
            &json!({"command": html_filter_alert_bypass_preflight_command()}),
            &successful_tool_response("html filter alert bypass preflight passed"),
        );
        assert_eq!(state.last_html_filter_alert_bypass_preflight_turn, 4);
        assert!(!html_filter_alert_bypass_preflight_pending(&state));
        let passed = latest_event(&state, "html_filter_alert_bypass_preflight_passed");
        assert_eq!(
            passed
                .get("html_filter_alert_bypass_artifact_path")
                .and_then(Value::as_str),
            Some("/app/out.html")
        );
        for key in [
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "max_turns_stop_condition",
            "timeout_seconds_stop_condition",
            "round_limit_stop_condition",
            "attempt_count_stop_condition",
            "budget_stop_condition",
            "html_filter_alert_bypass_stop_condition",
        ] {
            assert_eq!(
                passed.get(key).and_then(Value::as_bool),
                Some(false),
                "{key}"
            );
        }

        state.turn_count = 5;
        let mut stdin = std::io::Cursor::new(Vec::<u8>::new());
        assert!(completion_gate_passed(&mut state, &mut stdin));
    }

