    #[test]
    fn pytorch_distributed_preflight_blocks_dependency_cache_and_torchrun_expansion() {
        let mut state = worker_state_for_unit_tests();
        state.pytorch_distributed_preflight_required = true;
        state.pytorch_distributed_contract_observed_turn = 1;

        for (command, reason) in [
            (
                "pip3 install --break-system-packages --trusted-host pypi.org torch",
                "pytorch_distributed_preflight_pending_dependency_setup",
            ),
            (
                "/tmp/hl-verifier-cache/uv-python/bin/uv pip install torch",
                "pytorch_distributed_preflight_pending_dependency_setup",
            ),
            (
                "find / -path \"*/torch/__init__.py\" 2>/dev/null | head -10",
                "pytorch_distributed_preflight_pending_cache_or_verifier_hunt",
            ),
            (
                "python3 -m torch.distributed.run --nproc_per_node=4 check.py",
                "pytorch_distributed_preflight_pending_torchrun_probe",
            ),
            (
                "pytest /tests/test_outputs.py -k column_parallel",
                "pytorch_distributed_preflight_pending_broad_validation",
            ),
        ] {
            let blocked = blocked_pytorch_distributed_preflight_dependency_expansion(
                &state,
                "bash",
                &json!({"command": command}),
            )
            .expect(command);
            assert_eq!(
                blocked
                    .metadata
                    .get("semantic_failure_kind")
                    .and_then(Value::as_str),
                Some("blocked_pytorch_distributed_preflight_dependency_expansion")
            );
            assert_eq!(
                blocked
                    .metadata
                    .get("blocked_reason")
                    .and_then(Value::as_str),
                Some(reason),
                "{command}"
            );
            assert_worker_policy_guard_is_non_terminal(&blocked.metadata);
            assert_eq!(
                blocked
                    .metadata
                    .get("pytorch_distributed_preflight_stop_condition")
                    .and_then(Value::as_bool),
                Some(false)
            );
            assert_eq!(
                blocked
                    .metadata
                    .get("pytorch_distributed_preflight_expansion_stop_condition")
                    .and_then(Value::as_bool),
                Some(false)
            );
            assert!(blocked
                .error
                .contains("not a master, sub-agent, or Worker loop stop condition"));
        }
    }

