    #[test]
    fn successful_native_crash_preflight_clears_completion_gate() {
        let mut state = worker_state_for_unit_tests();
        state.native_crash_preflight_required = true;
        state.native_crash_contract_observed_turn = 1;
        state.turn_count = 6;
        let command = native_crash_preflight_command();
        assert!(is_native_crash_preflight_command(
            "verify",
            &json!({"command": command})
        ));
        assert!(is_local_verification_tool_call(
            "verify",
            &json!({"command": native_crash_preflight_command()})
        ));
        record_tool_progress(
            &mut state,
            "verify",
            &json!({"command": native_crash_preflight_command()}),
            &successful_tool_response("native crash preflight passed"),
        );

        assert_eq!(state.last_native_crash_preflight_turn, 6);
        assert!(!native_crash_preflight_pending(&state));
        let event = latest_event(&state, "native_crash_preflight_passed");
        for key in [
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "max_turns_stop_condition",
            "timeout_seconds_stop_condition",
            "round_limit_stop_condition",
            "attempt_count_stop_condition",
            "budget_stop_condition",
            "native_crash_contracts_stop_condition",
            "native_crash_preflight_stop_condition",
        ] {
            assert_eq!(
                event.get(key).and_then(Value::as_bool),
                Some(false),
                "{key}"
            );
        }

        state.turn_count = 7;
        let mut stdin = std::io::Cursor::new(Vec::<u8>::new());
        assert!(completion_gate_passed(&mut state, &mut stdin));
    }

    #[test]
    fn native_crash_preflight_guard_blocks_broad_expansion_but_allows_targeted_reproducer() {
        let mut state = worker_state_for_unit_tests();
        state.native_crash_preflight_required = true;
        state.native_crash_contract_observed_turn = 1;
        assert!(native_crash_preflight_pending(&state));

        let blocked = blocked_native_crash_preflight_expansion(
            &state,
            "bash",
            &json!({"command": "apt-get update && apt-get install -y build-essential clang lldb"}),
        )
        .expect("native crash pending guard should block dependency expansion");
        assert_eq!(
            blocked
                .metadata
                .get("semantic_failure_kind")
                .and_then(Value::as_str),
            Some("blocked_native_crash_preflight_expansion")
        );
        assert_eq!(
            blocked
                .metadata
                .get("blocked_reason")
                .and_then(Value::as_str),
            Some("native_crash_preflight_pending_dependency_setup")
        );
        assert!(blocked
            .error
            .contains("not a master, sub-agent, or Worker loop stop condition"));
        for key in [
            "policy_guard_stop_condition",
            "operation_guard_stop_condition",
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "max_turns_stop_condition",
            "timeout_seconds_stop_condition",
            "round_limit_stop_condition",
            "attempt_count_stop_condition",
            "budget_stop_condition",
            "native_crash_contracts_stop_condition",
            "native_crash_preflight_stop_condition",
            "native_crash_preflight_expansion_stop_condition",
        ] {
            assert_eq!(
                blocked.metadata.get(key).and_then(Value::as_bool),
                Some(false),
                "{key}"
            );
        }

        assert!(blocked_native_crash_preflight_expansion(
            &state,
            "bash",
            &json!({"command": native_crash_preflight_command()}),
        )
        .is_none());
        assert!(blocked_native_crash_preflight_expansion(
            &state,
            "bash",
            &json!({"command": "gdb --args /app/decomp2 /app/data.comp"}),
        )
        .is_none());
    }

    #[test]
    fn blocks_repeated_remote_dataset_timeout_path_but_allows_bounded_local_probe() {
        let mut state = worker_state_for_unit_tests();
        state
            .timeout_phase_counts
            .insert("remote_dataset_fetch".to_string(), 2);

        let blocked_load_dataset = blocked_repeated_timeout_path(
            &state,
            "bash",
            &json!({"command": "python3 -c \"from datasets import load_dataset; ds=load_dataset('ryanmarten/OpenThoughts-1k-sample'); print(ds)\" 2>&1"}),
        )
        .expect("full load_dataset command should be blocked after repeated remote dataset timeouts");
        assert!(!blocked_load_dataset.success);
        assert!(blocked_load_dataset
            .error
            .contains("Blocked repeated remote dataset timeout path"));
        assert!(blocked_load_dataset
            .error
            .contains("This is a recovery guard, not a loop stop condition"));
        assert!(blocked_load_dataset
            .error
            .contains("not driven by a time, round, turn, token, or max_turns limit"));
        assert_eq!(
            blocked_load_dataset
                .metadata
                .get("semantic_failure_kind")
                .and_then(Value::as_str),
            Some("blocked_repeated_remote_dataset_timeout_path")
        );
        assert_eq!(
            blocked_load_dataset
                .metadata
                .get("blocked_reason")
                .and_then(Value::as_str),
            Some("repeated_remote_dataset_api_fetch_timeout")
        );
        assert_eq!(
            blocked_load_dataset
                .metadata
                .get("remote_dataset_timeout_count")
                .and_then(Value::as_u64),
            Some(2)
        );
        assert_eq!(
            blocked_load_dataset
                .metadata
                .get("loop_stop_condition")
                .and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(
            blocked_load_dataset
                .metadata
                .get("time_round_token_limit_driven")
                .and_then(Value::as_bool),
            Some(false)
        );

        let blocked_dataset_info = blocked_repeated_timeout_path(
            &state,
            "bash",
            &json!({"command": "python3 <<'PYEOF'\nfrom huggingface_hub import HfApi\napi = HfApi()\nprint(api.dataset_info('ryanmarten/OpenThoughts-1k-sample'))\nPYEOF"}),
        )
        .expect("dataset_info command should be blocked after repeated remote dataset timeouts");
        assert_eq!(
            blocked_dataset_info
                .metadata
                .get("timeout_phase")
                .and_then(Value::as_str),
            Some("remote_dataset_fetch")
        );

        let blocked_cache_hunt = blocked_repeated_timeout_path(
            &state,
            "bash",
            &json!({"command": "find / -name '*.parquet' -o -name '*.arrow' -o -name '*.jsonl' 2>/dev/null"}),
        )
        .expect("broad dataset cache hunt should be blocked after repeated remote dataset timeouts");
        assert_eq!(
            blocked_cache_hunt
                .metadata
                .get("blocked_reason")
                .and_then(Value::as_str),
            Some("repeated_broad_dataset_cache_hunt_timeout")
        );
        assert!(blocked_cache_hunt.error.contains("-maxdepth"));

        assert!(blocked_repeated_timeout_path(
            &state,
            "bash",
            &json!({"command": "find /app -maxdepth 3 -name '*.parquet' | head -20"}),
        )
        .is_none());
        assert!(blocked_repeated_timeout_path(
            &state,
            "bash",
            &json!({"command": "python3 -c \"from datasets import load_dataset; ds=load_dataset('ryanmarten/OpenThoughts-1k-sample', streaming=True); print(list(ds['train'].take(10)))\""}),
        )
        .is_none());
        assert!(blocked_repeated_timeout_path(
            &state,
            "bash",
            &json!({"command": "python3 - <<'PY'\nimport itertools\nfrom datasets import load_dataset\nds = load_dataset('x/y', streaming=True)\nprint(list(itertools.islice(ds['train'], 5)))\nPY"}),
        )
        .is_none());
        assert!(blocked_repeated_timeout_path(
            &state,
            "read",
            &json!({"file_path": "/app/data/shard.parquet"}),
        )
        .is_none());
    }

