    #[test]
    fn generated_solver_guard_requires_later_bounded_probe_before_done() {
        let mut state = worker_state_for_unit_tests();
        let blocked_command = "cd /app && timeout 180 python gen_simple.py 2>&1";
        let blocked = failed_tool_response_with_metadata(
            "Blocked repeated generated solver timeout path",
            json!({
                "semantic_failure_kind": "blocked_repeated_generated_solver_timeout_path",
                "blocked_reason": "repeated_generated_solver_full_generation_timeout",
                "blocked_command": blocked_command,
            }),
        );
        state.turn_count = 5;
        record_tool_progress(
            &mut state,
            "bash",
            &json!({"command": blocked_command}),
            &blocked,
        );

        let required = latest_event(&state, "generated_solver_recovery_probe_required");
        assert_eq!(
            required.get("blocked_reason").and_then(Value::as_str),
            Some("repeated_generated_solver_full_generation_timeout")
        );
        assert_eq!(
            required.get("loop_stop_condition").and_then(Value::as_bool),
            Some(false)
        );
        assert!(generated_solver_recovery_probe_pending(&state));

        let mut stdin = std::io::Cursor::new(Vec::<u8>::new());
        assert!(!completion_gate_passed(&mut state, &mut stdin));
        let gate = latest_event(&state, "generated_solver_recovery_probe_completion_gate");
        assert_eq!(
            gate.get("generated_solver_guard_turn")
                .and_then(Value::as_u64),
            Some(5)
        );
        for key in [
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "max_turns_stop_condition",
            "timeout_seconds_stop_condition",
            "round_limit_stop_condition",
            "checkpoint_count_stop_condition",
            "checkpoint_cooldown_stop_condition",
            "attempt_count_stop_condition",
            "budget_stop_condition",
            "generated_solver_stop_condition",
        ] {
            assert_eq!(gate.get(key).and_then(Value::as_bool), Some(false), "{key}");
        }

        state.turn_count = 6;
        let shape_probe = "cd /app && python3 -c \"import json; rules=json.load(open('/app/re.json')); print('rule count', len(rules))\"";
        record_tool_progress(
            &mut state,
            "bash",
            &json!({"command": shape_probe}),
            &successful_tool_response("rule count 42"),
        );
        assert!(!generated_solver_recovery_probe_pending(&state));
        let passed = latest_event(&state, "generated_solver_recovery_probe_passed");
        assert_eq!(
            passed.get("command").and_then(Value::as_str),
            Some(shape_probe)
        );
        for key in [
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "max_turns_stop_condition",
            "timeout_seconds_stop_condition",
            "round_limit_stop_condition",
            "attempt_count_stop_condition",
            "budget_stop_condition",
            "generated_solver_stop_condition",
        ] {
            assert_eq!(
                passed.get(key).and_then(Value::as_bool),
                Some(false),
                "{key}"
            );
        }

        state.turn_count = 7;
        let mut stdin = std::io::Cursor::new(Vec::<u8>::new());
        assert!(completion_gate_passed(&mut state, &mut stdin));
    }

