    #[test]
    fn prior_failure_summary_is_bounded_and_path_scrubbed() {
        let data = json!({
            "trial_id": "old-trial",
            "status": "timeout",
            "score": 0.0,
            "metadata": {
                "timeout_phase": "dependency_setup",
                "agent_exception_type": "AgentTimeoutError"
            },
            "error_log": ["Agent execution timed out while reading /host/trials/runs/old/trajectory.jsonl and /app/private.log"]
        });

        let result_path = temp_result_path("path-scrubbed");
        let summary = prior_trial_failure_summary(
            &data,
            &result_path,
            "old-trial",
            "timeout".to_string(),
            0.0,
        )
        .expect("summary");
        let rendered = render_prior_failure_summary(&summary);

        assert!(rendered.contains("status=timeout"));
        assert!(rendered.contains("timeout_phase=dependency_setup"));
        assert!(rendered.contains("signal=AgentTimeoutError"));
        assert!(rendered.contains("Agent execution timed out"));
        assert!(!rendered.contains("/host/trials"));
        assert!(!rendered.contains("/app/private.log"));
        assert!(!rendered.contains("trajectory.jsonl"));
    }

    #[test]
    fn prior_failure_summary_extracts_bounded_ctrf_failures() {
        let data = json!({
            "trial_id": "old-trial",
            "status": "failed",
            "score": 0.0,
            "metadata": {
                "failure_category": "verifier_mismatch",
                "verifier_logs": "## ctrf.json\n{\n  \"results\": {\n    \"summary\": {\"tests\": 4, \"passed\": 1, \"failed\": 3},\n    \"tests\": [\n      {\"name\": \"test_outputs.py::test_immortal_game\", \"status\": \"failed\", \"trace\": \"def test():\\n> assert False\\nE       AssertionError: Our move /app/private.log not found in Python-chess moves\\n/tests/test_outputs.py:20: AssertionError\", \"message\": \"The test failed in the call phase due to an assertion error\"},\n      {\"name\": \"test_outputs.py::test_game_of_century\", \"status\": \"failed\", \"trace\": \"E           re.PatternError: invalid group reference 10 at position 19\", \"message\": \"\"},\n      {\"name\": \"test_outputs.py::test_third_case\", \"raw_status\": \"call_failed\", \"trace\": \"E       FileNotFoundError: [Errno 2] No such file or directory: '/app/recovered.json'\"},\n      {\"name\": \"test_outputs.py::test_fourth_case\", \"status\": \"failed\", \"trace\": \"E       should not be included\"}\n    ]\n  }\n}\n\n## test-stdout.txt\nlarge logs"
            },
            "error_log": ["{\"reward\": 0.0}"]
        });

        let result_path = temp_result_path("ctrf");
        let summary = prior_trial_failure_summary(
            &data,
            &result_path,
            "old-trial",
            "failed".to_string(),
            0.0,
        )
        .expect("summary");
        let rendered = render_prior_failure_summary(&summary);

        assert!(rendered.contains("signal=verifier_mismatch"));
        assert!(rendered.contains("verifier=verifier_failed=3/4 tests"));
        assert!(rendered.contains("passed=1"));
        assert!(rendered.contains("repair_focus=match_expected_state_transition_set"));
        assert!(rendered.contains("expected_artifacts=[/app/recovered.json]"));
        assert!(rendered.contains("test_outputs.py::test_immortal_game"));
        assert!(rendered.contains("Our move"));
        assert!(rendered.contains("test_outputs.py::test_game_of_century"));
        assert!(rendered.contains("PatternError"));
        assert!(rendered.contains("test_outputs.py::test_third_case"));
        assert!(rendered.contains("FileNotFoundError"));
        assert!(!rendered.contains("test_fourth_case"));
        assert!(!rendered.contains("/app/private.log"));
        assert!(!rendered.contains("large logs"));
    }

    #[test]
    fn prior_failure_summary_extracts_tail_trajectory_failure_signals() {
        let result_path = temp_result_path("trajectory");
        let trajectory_path = result_path.parent().unwrap().join("trajectory.jsonl");
        let events = vec![
            json!({
                "type": "tool_timeout_recovery_prompt",
                "tool": "bash",
                "command": "R CMD INSTALL /tmp/rstan.tar.gz 2>&1 | tail -40",
                "error": "Command timed out after 120s",
            }),
            json!({
                "type": "tool_call",
                "tool": "bash",
                "success": false,
                "args": {"command": "apt-get install -y r-cran-rstan"},
                "error": "Command timed out after 120s",
                "output": "",
            }),
            json!({
                "type": "dependency_recovery_checkpoint",
                "failure_count": 3,
            }),
            json!({
                "type": "terminal_environment_unavailable",
                "tool": "bash",
                "error": "service \"main\" is not running after /app/private.log",
            }),
        ];
        fs::write(
            &trajectory_path,
            events
                .iter()
                .map(Value::to_string)
                .collect::<Vec<_>>()
                .join("\n"),
        )
        .unwrap();
        let data = json!({
            "trial_id": "old-trial",
            "status": "timeout",
            "score": 0.0,
            "metadata": {"agent_exception_type": "AgentTimeoutError"},
            "error_log": ["Agent execution timed out after 1800.0 seconds"]
        });

        let summary = prior_trial_failure_summary(
            &data,
            &result_path,
            "old-trial",
            "timeout".to_string(),
            0.0,
        )
        .expect("summary");
        let rendered = render_prior_failure_summary(&summary);

        assert!(rendered.contains("trajectory="));
        assert!(rendered.contains("dependency_setup_trap"));
        assert!(rendered.contains("avoid replaying package managers or source builds"));
        assert!(rendered.contains("smallest deliverable early"));
        assert!(rendered.contains("tool_timeout phase=dependency_setup"));
        assert!(rendered.contains("R CMD INSTALL"));
        assert!(rendered.contains("failed_dependency_step"));
        assert!(rendered.contains("apt-get install -y r-cran-rstan"));
        assert!(rendered.contains("dependency_recovery_checkpoint"));
        assert!(!rendered.contains("/tmp/rstan.tar.gz"));
        assert!(!rendered.contains("/app/private.log"));
    }

