    #[test]
    fn prior_failure_summary_flags_repeated_long_command_replay_trap() {
        let result_path = temp_result_path("agent-timeout-trajectory");
        let trajectory_path = result_path.parent().unwrap().join("trajectory.jsonl");
        let events = vec![
            json!({
                "type": "tool_timeout_recovery_prompt",
                "tool": "bash",
                "command": "make all",
                "error": "Command timed out after 120s",
            }),
            json!({
                "type": "tool_call",
                "tool": "bash",
                "success": false,
                "args": {"command": "curl -L https://example.invalid/large.tar.gz"},
                "error": "Command timed out after 60s",
                "output": "",
            }),
            json!({
                "type": "tool_timeout_recovery_prompt",
                "tool": "bash",
                "command": "python train.py --epochs 10",
                "error": "Command timed out after 120s",
            }),
        ];
        fs::write(
            &trajectory_path,
            events
                .iter()
                .map(Value::to_string)
                .collect::<Vec<_>>()
                .join("\n"),
        )
        .unwrap();
        let data = json!({
            "trial_id": "timeout-trial",
            "status": "timeout",
            "score": 0.0,
            "metadata": {"timeout_phase": "agent_execution"},
            "error_log": ["Agent execution timed out after 1800.0 seconds"]
        });

        let summary = prior_trial_failure_summary(
            &data,
            &result_path,
            "timeout-trial",
            "timeout".to_string(),
            0.0,
        )
        .expect("summary");
        let rendered = render_prior_failure_summary(&summary);

        assert!(rendered.contains("long_command_replay_trap"));
        assert!(rendered.contains("bound setup/build/download work"));
        assert!(rendered.contains("smallest deliverable"));
        assert!(rendered.contains("tool_timeout phase=build_compile"));
        assert!(rendered.contains("tool_timeout phase=long_compute"));
        assert!(!rendered.contains("dependency_setup_trap"));
        assert!(!rendered.contains("https://example.invalid"));
    }

