    fn write_memory_result(runs_dir: &Path, run_name: &str, result: Value, trajectory: Vec<Value>) {
        let run_dir = runs_dir.join(run_name);
        fs::create_dir_all(&run_dir).unwrap();
        fs::write(run_dir.join("result.json"), result.to_string()).unwrap();
        fs::write(
            run_dir.join("trajectory.jsonl"),
            trajectory
                .iter()
                .map(Value::to_string)
                .collect::<Vec<_>>()
                .join("\n"),
        )
        .unwrap();
    }

    #[test]
    fn memory_expected_artifacts_extend_deliverable_targets_and_completion_gate() {
        let mut state = WorkerState::new(WorkerRequest {
            task_instruction: "task".to_string(),
            task_context: json!({"task_id": "task-a"}),
            initial_messages: Vec::new(),
            initial_trajectory: Vec::new(),
            tool_schemas: Vec::new(),
            max_turns_audit: 10,
            model_used: "test".to_string(),
            todo_items: Vec::new(),
            verification_command: String::new(),
            thresholds: Thresholds {
                compaction_char_threshold: 1000,
                verification_checkpoint_turns: Vec::new(),
                verification_checkpoint_cooldown_turns: 1,
                verification_checkpoint_max: 1,
                verification_checkpoint_min_tool_calls: 1,
                no_progress_checkpoint_tool_calls: 10,
                no_progress_checkpoint_cooldown_turns: 10,
                no_progress_checkpoint_max: 1,
                late_no_progress_turn_percent: 70,
                stalled_tool_loop_calls: 20,
                stalled_tool_loop_cooldown_turns: 8,
                stalled_tool_loop_max: 2,
                deliverable_checkpoint_min_tool_calls: 10,
                deliverable_checkpoint_cooldown_turns: 10,
                deliverable_checkpoint_max: 1,
                empty_response_recovery_limit: 3,
                ephemeral_tool_output_max_chars: 4000,
                ephemeral_tool_output_keep_recent: 4,
                timeout_escalation_count: 2,
                timeout_escalation_late_turn_percent: 66,
            },
            prompt_policy: PromptPolicy::default(),
        });
        let lines = vec![
            "- old: verifier=verifier_failed=2/2 tests, repair_focus=produce_expected_file_or_path, expected_artifacts=[/app/recovered.json; mystery.c; my_warrior.red; result.csv]".to_string(),
        ];

        add_memory_deliverable_targets(&mut state, &lines);

        assert!(state
            .deliverable_targets
            .contains(&"/app/recovered.json".to_string()));
        assert!(state.deliverable_targets.contains(&"mystery.c".to_string()));
        assert!(state
            .deliverable_targets
            .contains(&"my_warrior.red".to_string()));
        assert!(state
            .deliverable_targets
            .contains(&"result.csv".to_string()));
        assert!(state
            .missing_output_artifact_gate_targets
            .contains(&"/app/recovered.json".to_string()));
        assert!(state
            .missing_output_artifact_gate_targets
            .contains(&"mystery.c".to_string()));
        assert!(state
            .missing_output_artifact_gate_targets
            .contains(&"my_warrior.red".to_string()));
        assert!(state
            .missing_output_artifact_gate_targets
            .contains(&"result.csv".to_string()));

        state.turn_count = 3;
        let mut stdin = std::io::Cursor::new(Vec::<u8>::new());
        assert!(!completion_gate_passed(&mut state, &mut stdin));
        let gate = latest_event(&state, "missing_output_artifact_completion_gate");
        assert_eq!(
            gate.get("unconfirmed_deliverable_paths")
                .and_then(Value::as_array),
            Some(&vec![
                json!("/app/recovered.json"),
                json!("mystery.c"),
                json!("my_warrior.red"),
                json!("result.csv")
            ])
        );
        for key in [
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "max_turns_stop_condition",
            "timeout_seconds_stop_condition",
            "round_limit_stop_condition",
            "artifact_first_stop_condition",
            "missing_output_artifact_stop_condition",
            "checkpoint_count_stop_condition",
            "checkpoint_cooldown_stop_condition",
        ] {
            assert_eq!(gate.get(key).and_then(Value::as_bool), Some(false), "{key}");
        }
    }

