    #[test]
    fn missing_output_artifacts_ignore_dependency_scratch_paths() {
        let text = "Train the classifier and save the expected model artifact as /app/model.bin.\n\
E       AssertionError: File /app/model.bin does not exist\n\
E       File \"/tmp/fasttext-0.9.3/setup.py\", line 151, in build_extensions\n\
E       FileNotFoundError: [Errno 2] No such file or directory: '/tmp/libmpfr6_4.2.1-1_amd64.deb'\n\
E       dpkg: dependency problems prevent configuration because /tmp/libmpfr6 was not found";

        let artifacts = verifier_expected_artifacts(text);
        let full_paths = live_verifier_expected_artifact_paths(text);
        let contract = missing_output_artifact_contract(text).expect("missing artifact contract");

        assert_eq!(artifacts, vec!["/app/model.bin".to_string()]);
        assert_eq!(full_paths, vec!["/app/model.bin".to_string()]);
        assert!(contract.contains("/app/model.bin"));
        assert!(!contract.contains("/tmp/fasttext-0.9.3/setup.py"));
        assert!(!contract.contains("/tmp/libmpfr6"));
    }

