    #[test]
    fn live_verifier_semantic_contracts_extract_single_file_directory_contract() {
        let contracts = live_verifier_semantic_contracts(
            "def test_fibonacci_polyglot():\n\
    polyglot_files = os.listdir(\"/app/polyglot\")\n\
    assert polyglot_files == [\"main.rs\"]\n\
E       AssertionError: Expected only main.rs, found: ['test_poly.rs', 'test_macro.cpp', 'main.rs', 'main_test', 'test_inner_attr.rcgu.o', 'cmain']",
        );

        let contract = contracts
            .iter()
            .find(|contract| contract.starts_with("single_file_deliverable_directory_contract:"))
            .expect("single-file directory contract");
        assert!(contract.contains("/app/polyglot"));
        assert!(contract.contains("exactly main.rs"));
        assert!(contract.contains("scratch probes"));
        assert!(contract.contains("compiled binaries"));
        assert!(contract.contains("object files"));
        assert!(contract.contains("test_* artifacts"));
        assert!(contract.contains("os.listdir/exact-file-list check"));
        assert!(contract.contains("observed extra entries include test_poly.rs"));
    }

