    #[test]
    fn deliverable_size_cap_checkpoint_prefers_observed_tool_failure() {
        let mut state = worker_state_for_unit_tests();
        state.task_instruction =
            "Create /app/gpt2.c. The file must be under 5000 bytes and compile.".to_string();
        state.turn_count = 2;
        state.tool_call_history = vec![json!({
            "turn": 1,
            "tool": "bash",
            "args": {"command": "cd /app && python3 /tests/test_outputs.py"},
            "success": false,
            "output": "E       AssertionError: File /app/gpt2.c is larger than 5000 bytes\nE       assert 8394 < 5000\nE        +  where 8394 = os.stat_result(st_size=8394).st_size\n",
            "error": "exit code: 1",
        })];

        assert!(maybe_inject_deliverable_size_cap_checkpoint(&mut state));
        assert!(state.messages.iter().any(|message| {
            message
                .get("content")
                .and_then(Value::as_str)
                .is_some_and(|content| {
                    content.contains("Deliverable size-cap checkpoint")
                        && content.contains("Observed size: 8394 bytes")
                })
        }));
        assert!(state.trajectory.iter().any(|event| {
            event.get("type").and_then(Value::as_str) == Some("deliverable_size_cap_checkpoint")
                && event.get("observed_bytes").and_then(Value::as_u64) == Some(8394)
                && event
                    .get("deliverable_size_cap_stop_condition")
                    .and_then(Value::as_bool)
                    == Some(false)
        }));
    }

    #[test]
    fn deliverable_size_cap_checkpoint_uses_failed_entrypoint_scan_evidence() {
        let mut state = worker_state_for_unit_tests();
        state.task_instruction =
            "Create /app/gpt2.c. The file must be under 5000 bytes and compile.".to_string();
        state.turn_count = 1;
        state.trajectory = vec![json!({
            "type": "entrypoint_scan",
            "success": false,
            "output": "E       AssertionError: File /app/gpt2.c is larger than 5000 bytes\nE       assert 8394 < 5000\nE        +  where 8394 = os.stat_result(st_size=8394).st_size\n",
            "error": "exit code: 1",
        })];

        assert!(maybe_inject_deliverable_size_cap_checkpoint(&mut state));
        assert!(state.messages.iter().any(|message| {
            message
                .get("content")
                .and_then(Value::as_str)
                .is_some_and(|content| {
                    content.contains("Deliverable size-cap checkpoint")
                        && content.contains("/app/gpt2.c")
                        && content.contains("Observed size: 8394 bytes")
                })
        }));
        assert!(state.trajectory.iter().any(|event| {
            event.get("type").and_then(Value::as_str) == Some("deliverable_size_cap_checkpoint")
                && event.get("path").and_then(Value::as_str) == Some("/app/gpt2.c")
                && event.get("limit_bytes").and_then(Value::as_u64) == Some(5000)
                && event
                    .get("deliverable_size_cap_stop_condition")
                    .and_then(Value::as_bool)
                    == Some(false)
        }));
    }

