    #[test]
    fn live_verifier_semantic_contracts_extract_async_cancellation_cleanup_contract() {
        let contracts = live_verifier_semantic_contracts(
            "def test_tasks_cancel_above_max_concurrent():\n\
        proc = subprocess.Popen([\"python\", \"test.py\", \"--n-tasks\", \"3\", \"--max-concurrent\", \"2\"], stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n\
        time.sleep(0.5)\n\
        proc.send_signal(signal.SIGINT)\n\
        stdout, stderr = proc.communicate(timeout=5)\n\
        stdout = stdout.decode(\"utf-8\")\n\
        assert stdout.count(\"Task started.\") == 2\n\
>       assert stdout.count(\"Cleaned up.\") == 2\n\
E       AssertionError: assert 0 == 2\n\
E        +  where 0 = <built-in method count of str object at 0xabc>(\"Cleaned up.\")\n\
E        +    where <built-in method count of str object at 0xabc> = \"Task started.\\nTask started.\\n\".count",
        );

        let contract = contracts
            .iter()
            .find(|contract| contract.starts_with("async_cancellation_cleanup_contract:"))
            .expect("async cancellation cleanup semantic contract");
        assert!(contract.contains("SIGINT/KeyboardInterrupt"));
        assert!(contract.contains("every already-started async/concurrent task"));
        assert!(contract.contains("preserve max-concurrency semantics"));
        assert!(contract.contains("await cancellation/finally blocks"));
        assert!(contract.contains("flush stdout/stderr"));
        assert!(contract.contains("proc.send_signal(signal.SIGINT)"));
        assert!(contract.contains("proc.communicate(timeout=5)"));
        assert!(contract.contains("Task started."));
        assert!(contract.contains("Cleaned up."));
    }

