    fn live_verifier_semantic_contracts_extract_dna_insert_primer_pair_contracts() {
        let contracts = live_verifier_semantic_contracts(
            "def test_primers():\n\
    primers_path = Path(\"/app/primers.fasta\")\n\
    assert len(lines) == 4, \"Invalid number of lines in primers.fasta.\"\n\
    fwd_primer = lines[1].lower()\n\
    rev_primer = lines[3].lower()\n\
    assert re.fullmatch(r\"[atcg]+\", fwd_primer), \"Primer must contain only A, T, C, G.\"\n\
    assert re.fullmatch(r\"[atcg]+\", rev_primer), \"Primer must contain only A, T, C, G.\"\n\
    primers_concat = rc(rev_primer) + fwd_primer\n\
    insert_start = primers_concat.find(insert)\n\
>   assert insert_start != -1, \"Primer must contain inserted DNA.\"\n\
E   AssertionError: Primer must contain inserted DNA.\n\
    annealed_rev = primers_concat[:insert_start]\n\
    annealed_fwd = primers_concat[insert_end:]\n\
    assert 15 <= len(annealed_fwd) <= 45\n\
    assert vector1[-len(annealed_rev):] == annealed_rev\n\
    assert vector2[:len(annealed_fwd)] == annealed_fwd\n\
    assert 58 <= fwd_tm <= 72\n\
    assert abs(fwd_tm - rev_tm) <= 5",
        );

        assert!(contracts.iter().any(|contract| {
            contract.starts_with("dna_insert_primer_pair_contract:")
                && contract.contains("exactly 4 FASTA lines")
                && contract.contains("one forward/reverse primer pair")
                && contract.contains("rc(rev_primer)+fwd_primer")
                && contract.contains("insert present exactly between annealed_rev and annealed_fwd")
                && contract.contains("15..45 nt")
                && contract.contains("58..72 C")
                && contract.contains("within 5 C")
                && contract.contains("tiny local checker")
        }));
    }

