    #[test]
    fn verifier_mismatch_recovery_checkpoint_injects_once_per_failure() {
        let mut state = WorkerState::new(WorkerRequest {
            task_instruction: "task".to_string(),
            task_context: json!({"task_id": "regex-chess"}),
            initial_messages: Vec::new(),
            initial_trajectory: Vec::new(),
            tool_schemas: Vec::new(),
            max_turns_audit: 10,
            model_used: "test".to_string(),
            todo_items: Vec::new(),
            verification_command: String::new(),
            thresholds: Thresholds {
                compaction_char_threshold: 1000,
                verification_checkpoint_turns: Vec::new(),
                verification_checkpoint_cooldown_turns: 1,
                verification_checkpoint_max: 1,
                verification_checkpoint_min_tool_calls: 1,
                no_progress_checkpoint_tool_calls: 10,
                no_progress_checkpoint_cooldown_turns: 10,
                no_progress_checkpoint_max: 1,
                late_no_progress_turn_percent: 70,
                stalled_tool_loop_calls: 20,
                stalled_tool_loop_cooldown_turns: 8,
                stalled_tool_loop_max: 2,
                deliverable_checkpoint_min_tool_calls: 10,
                deliverable_checkpoint_cooldown_turns: 10,
                deliverable_checkpoint_max: 1,
                empty_response_recovery_limit: 3,
                ephemeral_tool_output_max_chars: 4000,
                ephemeral_tool_output_keep_recent: 4,
                timeout_escalation_count: 2,
                timeout_escalation_late_turn_percent: 66,
            },
            prompt_policy: PromptPolicy::default(),
        });
        state.turn_count = 3;
        state.unresolved_failed_verification = Some(FailedVerificationObservation {
            turn: 2,
            tool: "verify".to_string(),
            command: "python3 check_outputs.py".to_string(),
            observation: "AssertionError: Our move e2e4 not found in Python-chess moves"
                .to_string(),
            expected_artifacts: Vec::new(),
            semantic_contracts: vec![
                "state_transition_set_contract: generated next state must be a member of the verifier legal-transition set"
                    .to_string(),
            ],
        });

        assert!(maybe_inject_verifier_mismatch_recovery_checkpoint(
            &mut state
        ));
        assert!(!maybe_inject_verifier_mismatch_recovery_checkpoint(
            &mut state
        ));
        assert!(state.messages.iter().any(|message| {
            message.get("role").and_then(Value::as_str) == Some("user")
                && message
                    .get("content")
                    .and_then(Value::as_str)
                    .unwrap_or("")
                    .contains("Verifier-mismatch recovery checkpoint")
        }));
        assert!(state.trajectory.iter().any(|event| {
            event.get("type").and_then(Value::as_str)
                == Some("verifier_mismatch_recovery_checkpoint")
                && event.get("focus").and_then(Value::as_str)
                    == Some("match_expected_state_transition_set")
                && event
                    .get("semantic_contracts")
                    .and_then(Value::as_array)
                    .is_some_and(|contracts| {
                        contracts.iter().any(|contract| {
                            contract
                                .as_str()
                                .unwrap_or("")
                                .starts_with("state_transition_set_contract:")
                        })
                    })
                && event
                    .get("expected_artifacts_stop_condition")
                    .and_then(Value::as_bool)
                    == Some(false)
                && event
                    .get("semantic_contracts_stop_condition")
                    .and_then(Value::as_bool)
                    == Some(false)
                && event.get("loop_stop_condition").and_then(Value::as_bool) == Some(false)
        }));
    }

    #[test]
    fn verifier_mismatch_checkpoint_guides_structured_numeric_output_repair() {
        let mut state = WorkerState::new(WorkerRequest {
            task_instruction: "task".to_string(),
            task_context: json!({"task_id": "video-processing"}),
            initial_messages: Vec::new(),
            initial_trajectory: Vec::new(),
            tool_schemas: Vec::new(),
            max_turns_audit: 10,
            model_used: "test".to_string(),
            todo_items: Vec::new(),
            verification_command: String::new(),
            thresholds: Thresholds {
                compaction_char_threshold: 1000,
                verification_checkpoint_turns: Vec::new(),
                verification_checkpoint_cooldown_turns: 1,
                verification_checkpoint_max: 1,
                verification_checkpoint_min_tool_calls: 1,
                no_progress_checkpoint_tool_calls: 10,
                no_progress_checkpoint_cooldown_turns: 10,
                no_progress_checkpoint_max: 1,
                late_no_progress_turn_percent: 70,
                stalled_tool_loop_calls: 20,
                stalled_tool_loop_cooldown_turns: 8,
                stalled_tool_loop_max: 2,
                deliverable_checkpoint_min_tool_calls: 10,
                deliverable_checkpoint_cooldown_turns: 10,
                deliverable_checkpoint_max: 1,
                empty_response_recovery_limit: 3,
                ephemeral_tool_output_max_chars: 4000,
                ephemeral_tool_output_keep_recent: 4,
                timeout_escalation_count: 2,
                timeout_escalation_late_turn_percent: 66,
            },
            prompt_policy: PromptPolicy::default(),
        });
        state.turn_count = 4;
        state.unresolved_failed_verification = Some(FailedVerificationObservation {
            turn: 3,
            tool: "verify".to_string(),
            command: "python3 /tests/test_outputs.py".to_string(),
            observation: "output_path = Path(\"/app/output.toml\")\nrequired_fields = [\"jump_takeoff_frame_number\", \"jump_land_frame_number\"]\ntakeoff_range = (50, 54)\nlanding_range = (62, 64)".to_string(),
            expected_artifacts: vec!["/app/output.toml".to_string()],
            semantic_contracts: vec![
                "structured_output_schema_contract: verifier expects parseable output.toml with required numeric field(s) jump_takeoff_frame_number, jump_land_frame_number".to_string(),
                "numeric_interval_contract: verifier validates numeric outputs against inclusive range(s) takeoff_range=50..=54, landing_range=62..=64".to_string(),
            ],
        });

        assert!(maybe_inject_verifier_mismatch_recovery_checkpoint(
            &mut state
        ));
        let checkpoint = state
            .messages
            .iter()
            .find_map(|message| {
                let content = message.get("content").and_then(Value::as_str)?;
                content
                    .contains("Structured numeric output repair focus")
                    .then_some(content)
            })
            .expect("structured numeric repair checkpoint message");
        assert!(checkpoint.contains("output.toml"));
        assert!(checkpoint.contains("exact required keys"));
        assert!(checkpoint.contains("parseable scalar numeric values"));
        assert!(checkpoint.contains("*_range tuple"));
        assert!(checkpoint.contains("inclusive min/max bounds"));
        assert!(state.trajectory.iter().any(|event| {
            event.get("type").and_then(Value::as_str)
                == Some("verifier_mismatch_recovery_checkpoint")
                && event.get("focus").and_then(Value::as_str)
                    == Some("repair_structured_numeric_output_contract")
                && event.get("loop_stop_condition").and_then(Value::as_bool) == Some(false)
        }));
    }

    #[test]
    fn verifier_mismatch_checkpoint_guides_structured_csv_table_repair() {
        let mut state = worker_state_for_unit_tests();
        state.task_context = json!({"task_id": "financial-document-processor"});
        state.turn_count = 4;
        state.unresolved_failed_verification = Some(FailedVerificationObservation {
            turn: 3,
            tool: "verify".to_string(),
            command: "python3 /tests/test_outputs.py".to_string(),
            observation: "df = pd.read_csv(Path(\"/app/invoices/summary.csv\"))\nexpected_data = {'hash': {'total_amount': 6204.19, 'vat_amount': ''}, 'total': {'total_amount': 81315.20, 'vat_amount': 5402.48}}\nfor _, row in df.iterrows(): filename = row['filename']; file_identifier = compute_file_hash(file_path)\nAssertionError: Unexpected file abc in summary".to_string(),
            expected_artifacts: vec!["/app/invoices/summary.csv".to_string()],
            semantic_contracts: vec![
                "structured_csv_table_contract: verifier loads summary.csv via pd.read_csv(Path(\"/app/invoices/summary.csv\")) as a table and checks keyed row content; preserve columns filename, total_amount, vat_amount in exact order, row count, key column identity, blank-vs-nonblank cells, numeric/text dtype and formatting where applicable, and row identifiers must preserve the original file identity used by the verifier, such as original filenames or computed file hashes, plus total row semantics and decimal numeric values such as total_amount and vat_amount before broad document, image, or data parsing changes".to_string(),
            ],
        });

        assert!(maybe_inject_verifier_mismatch_recovery_checkpoint(
            &mut state
        ));
        let checkpoint = state
            .messages
            .iter()
            .find_map(|message| {
                let content = message.get("content").and_then(Value::as_str)?;
                content
                    .contains("Structured CSV/table repair focus")
                    .then_some(content)
            })
            .expect("structured CSV repair checkpoint message");
        assert!(checkpoint.contains("pd.read_csv(Path(\"/app/invoices/summary.csv\"))"));
        assert!(checkpoint.contains("exact column names"));
        assert!(checkpoint.contains("column names and order"));
        assert!(checkpoint.contains("row count"));
        assert!(checkpoint.contains("original filename or computed file hash"));
        assert!(checkpoint.contains("total row semantics"));
        assert!(checkpoint.contains("blank vs nonblank cells"));
        assert!(checkpoint.contains("numeric/text dtype"));
        assert!(checkpoint.contains("decimal numeric values"));
        assert!(checkpoint.contains("total_amount and vat_amount"));
        assert!(checkpoint.contains("one visible keyed row plus the total row"));
        assert!(state.trajectory.iter().any(|event| {
            event.get("type").and_then(Value::as_str)
                == Some("verifier_mismatch_recovery_checkpoint")
                && event.get("focus").and_then(Value::as_str)
                    == Some("repair_structured_csv_table_contract")
                && event.get("loop_stop_condition").and_then(Value::as_bool) == Some(false)
        }));
    }

