    #[test]
    fn local_semantic_checkpoint_guides_regex_backreference_repair_before_verifier_mismatch() {
        let mut state = worker_state_for_unit_tests();
        state.turn_count = 2;
        let mut result = ToolResponse {
            success: false,
            output: "fen = re.sub(pattern, repl, fen)\nE           re.PatternError: invalid group reference 10 at position 19\nError at pair 6174: invalid group reference 2 at position 5\n  Pattern: '(?m) (w|b) [^-]+ [a-h][36] '\n  Replacement: ' \\1 \\2 - '\n".to_string(),
            error: "exit code: 1".to_string(),
            duration_ms: 0.0,
            metadata: json!({"exit_code": 1}),
        };
        let args = json!({"command": "cd /app && python3 check_regex_pairs.py"});

        record_local_semantic_failure_observation(&mut state, "bash", &args, &result);

        let observed = latest_event(&state, "local_semantic_failure_observed");
        assert_eq!(
            observed.get("focus").and_then(Value::as_str),
            Some("fix_generated_regex_or_replacement_validity")
        );
        for key in [
            "semantic_contracts_stop_condition",
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "attempt_count_stop_condition",
        ] {
            assert_eq!(observed.get(key).and_then(Value::as_bool), Some(false));
        }
        let contracts = observed
            .get("semantic_contracts")
            .and_then(Value::as_array)
            .expect("semantic contracts");
        assert!(contracts
            .iter()
            .any(|contract| { contract.as_str().unwrap_or("").contains("pair index 6174") }));

        assert!(maybe_inject_local_semantic_failure_recovery_checkpoint(
            &mut state
        ));
        assert!(!maybe_inject_verifier_mismatch_recovery_checkpoint(
            &mut state
        ));
        let checkpoint = latest_event(&state, "local_semantic_failure_recovery_checkpoint");
        assert_eq!(
            checkpoint.get("focus").and_then(Value::as_str),
            Some("fix_generated_regex_or_replacement_validity")
        );
        for key in [
            "semantic_contracts_stop_condition",
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "token_budget_stop_condition",
            "budget_stop_condition",
            "attempt_count_stop_condition",
            "checkpoint_count_stop_condition",
            "checkpoint_cooldown_stop_condition",
        ] {
            assert_eq!(checkpoint.get(key).and_then(Value::as_bool), Some(false));
        }
        let message = state
            .messages
            .iter()
            .find_map(|message| {
                let content = message.get("content").and_then(Value::as_str)?;
                content
                    .contains("Local semantic failure recovery checkpoint")
                    .then_some(content)
            })
            .expect("local semantic recovery message");
        assert!(message.contains("Regex replacement repair focus"));
        assert!(message.contains("Semantic contract(s) extracted"));
        assert!(message.contains("pair index 6174"));
        assert!(message.contains("\\10 mean group 10"));
        assert!(message.contains("\\g<1>0"));
        assert!(message.contains("pattern.groups"));
        assert!(message.contains("pattern.groupindex"));
        assert!(message.contains("pattern.sub(repl, focused_sample)"));
        assert!(message.contains("Prefer a parser or explicit state transition"));
        assert!(message.contains("not a loop stop condition"));
        assert!(message.contains("not caused by time, round, turn, attempt, token, budget"));

        let mut stdin = std::io::Cursor::new(Vec::<u8>::new());
        assert!(!completion_gate_passed(&mut state, &mut stdin));
        let completion_gate = latest_event(&state, "local_semantic_failure_completion_gate");
        assert_eq!(
            completion_gate.get("focus").and_then(Value::as_str),
            Some("fix_generated_regex_or_replacement_validity")
        );
        for key in [
            "semantic_contracts_stop_condition",
            "loop_stop_condition",
            "time_round_token_limit_driven",
            "token_budget_stop_condition",
            "budget_stop_condition",
            "attempt_count_stop_condition",
            "checkpoint_count_stop_condition",
            "checkpoint_cooldown_stop_condition",
        ] {
            assert_eq!(
                completion_gate.get(key).and_then(Value::as_bool),
                Some(false)
            );
        }

        result.success = true;
        record_tool_progress(
            &mut state,
            "verify",
            &json!({"command": "pytest -q"}),
            &result,
        );
        assert!(state.unresolved_local_semantic_failure.is_none());
    }

