    #[test]
    fn corewar_candidate_checkpoint_promotes_tmp_redcode_to_required_deliverable() {
        let mut state = worker_state_for_unit_tests();
        state.task_instruction =
            "Create the Core War warrior for winning-avg-corewars.".to_string();
        state.task_context = json!({
            "task_id": "winning-avg-corewars",
            "completion_condition": "Verifier runs pmars against /app/my_warrior.red",
        });
        state.deliverable_targets = vec!["/app/my_warrior.red".to_string()];
        state.turn_count = 2;

        record_corewar_candidate_progress(
            &mut state,
            "write",
            &json!({"file_path": "/tmp/rave_d1p.red"}),
            &ToolResponse {
                success: true,
                output: "/tmp/rave_d1p.red".to_string(),
                error: String::new(),
                duration_ms: 0.0,
                metadata: json!({}),
            },
        );
        assert!(maybe_inject_corewar_deliverable_checkpoint(&mut state));
        let early_message = state
            .messages
            .iter()
            .find_map(|message| {
                let content = message.get("content").and_then(Value::as_str)?;
                content
                    .contains("Core War deliverable checkpoint")
                    .then_some(content)
            })
            .expect("early corewar deliverable checkpoint message");
        assert!(early_message.contains("Even before additional tmp-path testing"));
        assert!(early_message.contains("/app/my_warrior.red"));
        assert!(state.trajectory.iter().any(|event| {
            event.get("type").and_then(Value::as_str) == Some("corewar_deliverable_checkpoint")
                && event.get("candidate_path").and_then(Value::as_str) == Some("/tmp/rave_d1p.red")
                && event
                    .get("candidate_validated_with_pmars")
                    .and_then(Value::as_bool)
                    == Some(false)
                && event.get("loop_stop_condition").and_then(Value::as_bool) == Some(false)
        }));

        state.corewar_deliverable_checkpoint_injected = false;
        state.messages.clear();
        state.turn_count = 3;
        record_corewar_candidate_progress(
            &mut state,
            "bash",
            &json!({
                "command": "cd /app && pmars -b -r 100 -f /tmp/rave_d1p.red warriors/stone.red 2>&1",
            }),
            &ToolResponse {
                success: true,
                output: "Rave-D1p scores 214 Stone scores 85 Results: 71 28 1".to_string(),
                error: String::new(),
                duration_ms: 0.0,
                metadata: json!({}),
            },
        );

        assert!(maybe_inject_corewar_deliverable_checkpoint(&mut state));
        let message = state
            .messages
            .iter()
            .find_map(|message| {
                let content = message.get("content").and_then(Value::as_str)?;
                content
                    .contains("Core War deliverable checkpoint")
                    .then_some(content)
            })
            .expect("corewar deliverable checkpoint message");
        assert!(message.contains("/tmp/rave_d1p.red"));
        assert!(message.contains("/app/my_warrior.red"));
        assert!(message.contains("pmars -b -r 100 -f /app/my_warrior.red"));
        assert!(message.contains("71.0% wins"));
        assert!(message.contains("below the visible 75% threshold"));
        assert!(message.contains("stone.red>=75%"));
        assert!(message.contains("vampire.red>=75%"));
        assert!(message.contains("not a master, sub-agent, or Worker loop stop condition"));
        assert!(message.contains("not driven by time, round, turn, token, max_turns"));
        assert!(state.trajectory.iter().any(|event| {
            event.get("type").and_then(Value::as_str) == Some("corewar_candidate_observed")
                && event.get("candidate_path").and_then(Value::as_str) == Some("/tmp/rave_d1p.red")
                && event
                    .get("candidate_validated_with_pmars")
                    .and_then(Value::as_bool)
                    == Some(true)
                && event
                    .get("candidate_pmars_result")
                    .and_then(|value| value.get("opponent"))
                    .and_then(Value::as_str)
                    == Some("stone.red")
                && event
                    .get("candidate_pmars_result")
                    .and_then(|value| value.get("wins"))
                    .and_then(Value::as_i64)
                    == Some(71)
                && event
                    .get("candidate_pmars_result")
                    .and_then(|value| value.get("threshold_percent"))
                    .and_then(Value::as_i64)
                    == Some(75)
                && event
                    .get("candidate_pmars_result")
                    .and_then(|value| value.get("meets_threshold"))
                    .and_then(Value::as_bool)
                    == Some(false)
                && event.get("loop_stop_condition").and_then(Value::as_bool) == Some(false)
        }));
        assert!(state.trajectory.iter().any(|event| {
            event.get("type").and_then(Value::as_str) == Some("corewar_deliverable_checkpoint")
                && event.get("candidate_path").and_then(Value::as_str) == Some("/tmp/rave_d1p.red")
                && event
                    .get("required_deliverable_path")
                    .and_then(Value::as_str)
                    == Some("/app/my_warrior.red")
                && event
                    .get("corewar_deliverable_stop_condition")
                    .and_then(Value::as_bool)
                    == Some(false)
                && event
                    .get("candidate_pmars_result")
                    .and_then(|value| value.get("win_rate_percent"))
                    .and_then(Value::as_f64)
                    == Some(71.0)
                && event
                    .get("time_round_token_limit_driven")
                    .and_then(Value::as_bool)
                    == Some(false)
                && event
                    .get("max_turns_stop_condition")
                    .and_then(Value::as_bool)
                    == Some(false)
                && event
                    .get("timeout_seconds_stop_condition")
                    .and_then(Value::as_bool)
                    == Some(false)
                && event
                    .get("round_limit_stop_condition")
                    .and_then(Value::as_bool)
                    == Some(false)
                && event
                    .get("attempt_count_stop_condition")
                    .and_then(Value::as_bool)
                    == Some(false)
                && event.get("budget_stop_condition").and_then(Value::as_bool) == Some(false)
        }));
    }

