    #[test]
    fn corewar_required_path_single_opponent_pass_records_progress_without_confirmation() {
        let mut state = worker_state_for_unit_tests();
        state.task_instruction =
            "Create the Core War warrior for winning-avg-corewars.".to_string();
        state.task_context = json!({
            "task_id": "winning-avg-corewars",
            "completion_condition": "Verifier runs pmars against /app/my_warrior.red",
        });
        state.deliverable_targets = vec!["/app/my_warrior.red".to_string()];
        state.corewar_candidate_path = "/app/my_warrior.red".to_string();
        state.turn_count = 6;

        record_confirmed_corewar_deliverable_progress(
            &mut state,
            "bash",
            &json!({
                "command": "cd /app && pmars -b -r 100 -f /app/my_warrior.red /app/warriors/stone.red 2>&1",
            }),
            &ToolResponse {
                success: true,
                output: "My warrior scores 226 Stone scores 74 Results: 75 24 1".to_string(),
                error: String::new(),
                duration_ms: 0.0,
                metadata: json!({"exit_code": 0}),
            },
        );

        assert!(!state.confirmed_deliverables.contains("/app/my_warrior.red"));
        assert_eq!(
            count_events(&state, "corewar_deliverable_preflight_passed"),
            0
        );
        assert!(state
            .corewar_required_path_passed_opponents
            .contains_key("stone.red"));
        let event = latest_event(&state, "corewar_required_path_opponent_preflight_passed");
        let score = event
            .get("candidate_pmars_result")
            .expect("pmars score metadata");
        assert_eq!(
            score.get("opponent").and_then(Value::as_str),
            Some("stone.red")
        );
        assert_eq!(score.get("wins").and_then(Value::as_i64), Some(75));
        assert_eq!(
            score.get("threshold_percent").and_then(Value::as_i64),
            Some(75)
        );
        assert_eq!(
            score.get("meets_threshold").and_then(Value::as_bool),
            Some(true)
        );
        assert!(event
            .get("corewar_required_path_passed_opponents")
            .and_then(|value| value.get("stone.red"))
            .is_some());
        assert_eq!(
            event
                .get("corewar_missing_required_opponents")
                .and_then(Value::as_array),
            Some(&vec![
                json!("vampire.red"),
                json!("paper.red"),
                json!("snake.red"),
                json!("g2-clear.red"),
            ])
        );
        assert_eq!(
            event.get("loop_stop_condition").and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(
            event
                .get("time_round_token_limit_driven")
                .and_then(Value::as_bool),
            Some(false)
        );

        let mut stdin = std::io::Cursor::new(Vec::<u8>::new());
        assert!(!completion_gate_passed(&mut state, &mut stdin));
        let gate = latest_event(&state, "corewar_deliverable_completion_gate");
        assert_eq!(
            gate.get("corewar_missing_required_opponents")
                .and_then(Value::as_array),
            Some(&vec![
                json!("vampire.red"),
                json!("paper.red"),
                json!("snake.red"),
                json!("g2-clear.red"),
            ])
        );
    }

    #[test]
    fn corewar_required_path_all_opponents_pass_before_confirming_deliverable() {
        let mut state = worker_state_for_unit_tests();
        state.task_instruction =
            "Create the Core War warrior for winning-avg-corewars.".to_string();
        state.task_context = json!({
            "task_id": "winning-avg-corewars",
            "completion_condition": "Verifier runs pmars against /app/my_warrior.red",
        });
        state.deliverable_targets = vec!["/app/my_warrior.red".to_string()];
        state.corewar_candidate_path = "/app/my_warrior.red".to_string();

        for (turn, opponent, output) in [
            (
                6,
                "stone.red",
                "My warrior scores 226 Stone scores 74 Results: 75 24 1",
            ),
            (
                7,
                "vampire.red",
                "My warrior scores 226 Vampire scores 74 Results: 75 24 1",
            ),
            (
                8,
                "paper.red",
                "My warrior scores 226 Paper scores 74 Results: 75 24 1",
            ),
            (
                9,
                "snake.red",
                "My warrior scores 99 Snake scores 201 Results: 33 67 0",
            ),
            (
                10,
                "g2-clear.red",
                "My warrior scores 99 Clear scores 201 Results: 33 67 0",
            ),
        ] {
            state.turn_count = turn;
            record_confirmed_corewar_deliverable_progress(
                &mut state,
                "bash",
                &json!({
                    "command": format!(
                        "cd /app && pmars -b -r 100 -f /app/my_warrior.red /app/warriors/{opponent} 2>&1"
                    ),
                }),
                &ToolResponse {
                    success: true,
                    output: output.to_string(),
                    error: String::new(),
                    duration_ms: 0.0,
                    metadata: json!({"exit_code": 0}),
                },
            );
            if opponent != "g2-clear.red" {
                assert!(!state.confirmed_deliverables.contains("/app/my_warrior.red"));
            }
        }

        assert!(state.confirmed_deliverables.contains("/app/my_warrior.red"));
        assert_eq!(
            count_events(&state, "corewar_required_path_opponent_preflight_passed"),
            4
        );
        let event = latest_event(&state, "corewar_deliverable_preflight_passed");
        assert_eq!(
            event
                .get("corewar_missing_required_opponents")
                .and_then(Value::as_array),
            Some(&vec![])
        );
        let passed = event
            .get("corewar_required_path_passed_opponents")
            .and_then(Value::as_object)
            .expect("passed opponents metadata");
        for opponent in corewar_required_opponents() {
            assert!(passed.contains_key(opponent), "missing {opponent}");
        }
        assert_eq!(
            event
                .get("candidate_pmars_result")
                .and_then(|value| value.get("opponent"))
                .and_then(Value::as_str),
            Some("g2-clear.red")
        );
        assert_eq!(
            event
                .get("candidate_pmars_result")
                .and_then(|value| value.get("threshold_percent"))
                .and_then(Value::as_i64),
            Some(33)
        );
        assert_eq!(
            event.get("loop_stop_condition").and_then(Value::as_bool),
            Some(false)
        );
    }

