    #[test]
    fn verifier_mismatch_checkpoint_guides_native_binary_crash_repair() {
        let mut state = worker_state_for_unit_tests();
        state.turn_count = 4;
        state.unresolved_failed_verification = Some(FailedVerificationObservation {
            turn: 3,
            tool: "verify".to_string(),
            command: "python3 /tests/test_outputs.py".to_string(),
            observation: "cat /app/data.comp | /app/decomp2\nDecompression failed with error: Segmentation fault (core dumped)\nE       assert 139 == 0\nCompletedProcess(args='cat /app/data.comp | /app/decomp2', returncode=139, stdout='', stderr='Segmentation fault (core dumped)\\n')".to_string(),
            expected_artifacts: vec!["/app/data.comp".to_string()],
            semantic_contracts: vec![
                "native_crash_contract: verifier-invoked native binary or pipeline must exit 0 without SIGSEGV/core dump on the visible input; reproduce the exact command, then fix bounds, EOF, allocation-size, and state-machine handling before broad rewrites".to_string(),
            ],
        });

        assert!(maybe_inject_verifier_mismatch_recovery_checkpoint(
            &mut state
        ));
        let checkpoint = state
            .messages
            .iter()
            .find_map(|message| {
                let content = message.get("content").and_then(Value::as_str)?;
                content
                    .contains("Native binary crash repair focus")
                    .then_some(content)
            })
            .expect("native crash repair checkpoint message");
        assert!(checkpoint.contains("exact verifier-invoked command or pipeline"));
        assert!(checkpoint.contains("cat input | ./binary"));
        assert!(checkpoint.contains("exit status, stderr"));
        assert!(checkpoint.contains("bounds/EOF assertions"));
        assert!(checkpoint.contains("buffer length checks"));
        assert!(checkpoint.contains("signed/unsigned sizes"));
        assert!(checkpoint.contains("allocation sizes"));
        assert!(checkpoint.contains("one-byte/empty/truncated-input smoke case"));
        assert!(checkpoint.contains("not a loop stop condition"));
        assert!(state.trajectory.iter().any(|event| {
            event.get("type").and_then(Value::as_str)
                == Some("verifier_mismatch_recovery_checkpoint")
                && event.get("focus").and_then(Value::as_str)
                    == Some("repair_native_binary_crash_contract")
                && event.get("loop_stop_condition").and_then(Value::as_bool) == Some(false)
        }));
    }

    #[test]
    fn strong_exception_repair_requires_failed_path_or_import() {
        let mut state = WorkerState::new(WorkerRequest {
            task_instruction: "task".to_string(),
            task_context: json!({"task_id": "task-a"}),
            initial_messages: Vec::new(),
            initial_trajectory: Vec::new(),
            tool_schemas: Vec::new(),
            max_turns_audit: 10,
            model_used: "test".to_string(),
            todo_items: Vec::new(),
            verification_command: String::new(),
            thresholds: Thresholds {
                compaction_char_threshold: 1000,
                verification_checkpoint_turns: Vec::new(),
                verification_checkpoint_cooldown_turns: 1,
                verification_checkpoint_max: 1,
                verification_checkpoint_min_tool_calls: 1,
                no_progress_checkpoint_tool_calls: 10,
                no_progress_checkpoint_cooldown_turns: 10,
                no_progress_checkpoint_max: 1,
                late_no_progress_turn_percent: 70,
                stalled_tool_loop_calls: 20,
                stalled_tool_loop_cooldown_turns: 8,
                stalled_tool_loop_max: 2,
                deliverable_checkpoint_min_tool_calls: 10,
                deliverable_checkpoint_cooldown_turns: 10,
                deliverable_checkpoint_max: 1,
                empty_response_recovery_limit: 3,
                ephemeral_tool_output_max_chars: 4000,
                ephemeral_tool_output_keep_recent: 4,
                timeout_escalation_count: 2,
                timeout_escalation_late_turn_percent: 66,
            },
            prompt_policy: PromptPolicy::default(),
        });
        state.unresolved_local_exception = Some(LocalExceptionObservation {
            turn: 1,
            tool: "bash".to_string(),
            command: "python3 /app/convert_masks.py".to_string(),
            observation: "ModuleNotFoundError: No module named 'numpy'".to_string(),
        });

        assert!(!is_strong_exception_repair_verification(
            &state,
            "verify",
            &json!({"command": "python3 -c \"print('hello')\""})
        ));
        assert!(!is_strong_exception_repair_verification(
            &state,
            "verify",
            &json!({"command": "python3 -c \"import py_compile; py_compile.compile('/app/convert_masks.py', doraise=True)\""})
        ));
        assert!(is_strong_exception_repair_verification(
            &state,
            "verify",
            &json!({"command": "python3 -c \"import numpy\""})
        ));
        assert!(is_strong_exception_repair_verification(
            &state,
            "verify",
            &json!({"command": "python3 /app/convert_masks.py --help"})
        ));

        state.unresolved_local_exception = Some(LocalExceptionObservation {
            turn: 2,
            tool: "bash".to_string(),
            command: "python3 -c \"import cv2\"".to_string(),
            observation:
                "ImportError: libGL.so.1: cannot open shared object file: No such file or directory"
                    .to_string(),
        });
        assert!(!is_strong_exception_repair_verification(
            &state,
            "verify",
            &json!({"command": "python3 -c \"import torch\""})
        ));
        assert!(is_strong_exception_repair_verification(
            &state,
            "verify",
            &json!({"command": "python3 -c \"import cv2\""})
        ));
    }

    #[test]
    fn successful_verify_traceback_is_normalized_to_failure() {
        let mut response = ToolResponse {
            success: true,
            output: "Traceback (most recent call last):\nRuntimeError: bad artifact".to_string(),
            error: String::new(),
            duration_ms: 0.0,
            metadata: json!({"exit_code": 0}),
        };

        normalize_local_verification_exception_result(
            "verify",
            &json!({"command": "python3 check_outputs.py"}),
            &mut response,
        );

        assert!(!response.success);
        assert!(response
            .error
            .contains("local verification output contains an exception"));
        assert_eq!(
            response
                .metadata
                .get("semantic_failure_kind")
                .and_then(Value::as_str),
            Some("local_verification_exception")
        );
        assert_eq!(
            response
                .metadata
                .get("semantic_failure_detected")
                .and_then(Value::as_bool),
            Some(true)
        );
    }

    #[test]
    fn successful_bash_masked_exception_is_normalized_to_failure() {
        let mut response = ToolResponse {
            success: true,
            output: "Error processing file: cannot access free variable 're' where it is not associated with a value in enclosing scope".to_string(),
            error: String::new(),
            duration_ms: 0.0,
            metadata: json!({"exit_code": 0}),
        };

        normalize_local_verification_exception_result(
            "bash",
            &json!({"command": "python3 /app/filter.py /tmp/sample.html 2>&1 || true"}),
            &mut response,
        );

        assert!(!response.success);
        assert!(response.error.contains("failure was masked by `|| true`"));
        assert_eq!(
            response
                .metadata
                .get("semantic_failure_kind")
                .and_then(Value::as_str),
            Some("masked_local_exception")
        );
        assert_eq!(
            response
                .metadata
                .get("masked_shell_failure")
                .and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(
            response
                .metadata
                .get("semantic_failure_detected")
                .and_then(Value::as_bool),
            Some(true)
        );
    }

    #[test]
    fn terminal_provider_error_classifies_billing_without_loop_stop_flags() {
        let error = LlmError {
            error_type: "BadRequestError".to_string(),
            message: "OpenAIException - Insufficient Balance".to_string(),
        };

        let provider_error = terminal_provider_error(&error).expect("provider terminal error");
        assert_eq!(provider_error.kind, "billing_quota");

        let state = worker_state_for_unit_tests();
        let result = state.terminal_provider_error_result(&error, &provider_error);

        assert_eq!(result.get("status").and_then(Value::as_str), Some("error"));
        assert_eq!(
            result
                .get("metadata")
                .and_then(|metadata| metadata.get("provider_terminal_error"))
                .and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(
            result
                .get("metadata")
                .and_then(|metadata| metadata.get("provider_billing_quota_stop_condition"))
                .and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(
            result
                .get("metadata")
                .and_then(|metadata| metadata.get("loop_stop_condition"))
                .and_then(Value::as_bool),
            Some(false)
        );
    }
